window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_005"]={"n":"邓云霄","dyn":"明","poems":[{"t":"受长洲令出都门戏作长歌","f":"七言古诗","c":["从来懒慢喜逍遥，林下闻风欲弃瓢。","东海肯将龙性扰，北山谁把鹤书招？","朅来京陌红尘里，奏对明光谒天子。","骥尾犹随十九人，鹏溟休说三千里。","一行作吏傍凫飞，此日驱车出帝畿。","风木哀吟愁捧檄，尘埃世态易沾衣。","平生疑是劳薪骨，簿领从今终矻矻。","折腰断不受人怜，强项雄心未全歇。","丈夫有甑学莱芜，独鹤随行兴不孤。","物力东南今正竭，谁能鞭扑更催租。","莫言下吏翻嫌俗，百里郎官高列宿。","一曲琴清化茧丝，九还丹就骑鸿鹄。","梦中彩笔去曾携，一片闲心物外栖。","吴门烟月宜仙令，处处湖山待品题。"]},{"t":"至茂苑","f":"七言律诗","c":["翛然身世两无求，一入尘涂意转幽。","范蠡芳湖连苑外，虎丘山寺挂城头。","散衙入夜开芸阁，问俗乘春上野舟。","莫怪河阳誇傲吏，县门长对百花洲。"]},{"t":"小漆园八咏 其一 碧梧","f":"七言律诗","c":["炎天庭院午生凉，为有双梧对小堂。","金并银床邀夜月，彩鸾威凤待朝阳。","瑶琴曲度龙门险，石鼓声传蜀道长。","莫向西风惊一叶，疏枝偏不碍秋光。"]},{"t":"小漆园八咏 其二 翠竹","f":"七言律诗","c":["长日谁堪领簿书，绕亭苍翠可逃虚。","清风入榻茶烟罢，疏雨鸣梢午梦馀。","赋就梁园无俗调，影摇湘水动仙裾。","主人最爱清狂客，为问王猷肯命车。"]},{"t":"小漆园八咏 其三 古柏","f":"七言律诗","c":["秋深霜落满园芜，爱尔亭亭晚节孤。","黛色浮香如隐麝，苍枝横铁亦栖乌。","古堂疏豁欹朝枕，小榭阴森换夕垆。","老友岁寒堪共对，女萝余蔓莫教扶。"]},{"t":"小漆园八咏 其四 丛兰","f":"七言律诗","c":["楚客香传九畹名，西轩栏槛最留情。","当门弄色人争妒，幽谷孤芳尔独贞。","冷翠迎秋襟袖薄，淡妆团露梦魂清。","同心入室今何在，岁晏怀人别恨生。"]},{"t":"小漆园八咏 其五 丹桂","f":"七言律诗","c":["霓裳仙袖暗分丹，冉冉秋香怅独攀。","霜露可能欺绿叶，神仙长与驻朱颜。","寻芳有客登中岳，招隐何人继小山。","遥望故乡森八树，西风流水夜潺潺。"]},{"t":"小漆园八咏 其六 黄菊","f":"七言律诗","c":["晚对金尊泛落英，西山爽气入秋明。","偏怜骨为淩霜瘦，更羡香缘饮露清。","薄宦几年犹浪迹，故园三径正含情。","凭君寄谢东篱客，啸傲归来得此生。"]},{"t":"小漆园八咏 其七 盆鱼","f":"七言律诗","c":["日月曾闻寄一壶，谁云勺水异江湖。","天光云影含虚镜，碧藻红鳞漾锦铺。","渔父持竿空伫立，波臣卧辙笑相呼。","翛然齐物同观化，未辨濠梁乐有无。"]},{"t":"小漆园八咏 其八 湖石","f":"七言律诗","c":["永日求羊不到门，烟霞片石意犹存。","神鞭驱出洞庭泣，仙子骑来震泽翻。","幽壑转疑迷竹径，危峰直欲压松轩。","参禅一悟生公偈，静坐焚香可对言。"]},{"t":"卧病暮春","f":"七言律诗","c":["经旬休沐拥愁眠，不分残花笑欲然。","吏俗尚堪呼酒圣，官贫犹得数榆钱。","惟将案牍供多病，谁把升沉错料天。","共道出郊人事少，开衙应去课春田。"]},{"t":"棕拂子","f":"五言古诗","c":["避暑早扃门，道书行尚把。","脱巾握棕拂，意态何潇洒。","非无白羽扇，能使烦襟写。","无风风乃清，此物较幽雅。","古人琴无弦，希声不外假。","繄余悟此理，隐几高梧下。","地静如清秋，苍蝇胡为者。"]},{"t":"清风亭","f":"五言古诗","c":["夜来坐虚亭，蘋末微风起。","金波摇素练，江上月千里。","何处采莲归，歌声传渌水。","更有扁舟人，濯足月明里。","茶烟飞一缕，知是天随子。"]},{"t":"吴子夜四时欢歌 其一","f":"五言绝句","c":["蜂翅初试黄，豆蔻花渐吐。","小姑未许人，不敢下堂步。"]},{"t":"吴子夜四时欢歌 其二","f":"五言绝句","c":["大嫂唤小姑，踏青南浦去。","儿夫同一艇，系缆人稀处。"]},{"t":"吴子夜四时欢歌 其三","f":"五言绝句","c":["前行逐后行，同著锦裲裆。","弹莺休中燕，打鸭莫惊鸯。"]},{"t":"吴子夜四时欢歌 其四","f":"五言绝句","c":["踏青晚醉归，郎醉且休寝。","上堂问舅姑，挑灯还制锦。"]},{"t":"吴子夜四时欢歌 其五","f":"五言绝句","c":["竹箔罢春蚕，生丝作夏衫。","今年家计好，斗草剩宜男。"]},{"t":"吴子夜四时欢歌 其六","f":"五言绝句","c":["游子转兰船，调侬曲港边。","采花先得藕，不受外人莲。"]},{"t":"吴子夜四时欢歌 其七","f":"五言绝句","c":["江上龙舟戏，新妆照碧波。","隔船呼女伴，举酒酹曹娥。"]},{"t":"吴子夜四时欢歌 其八","f":"五言绝句","c":["欢向临邛去，经年不寄书。","还及浮瓜节，初看燕乳雏。"]},{"t":"吴子夜四时欢歌 其九","f":"五言绝句","c":["挈枕上高楼，银床凉似水。","对郎弹箜篌，恐落邻家耳。"]},{"t":"吴子夜四时欢歌 其十","f":"五言绝句","c":["瓜果郎休笑，邻姑共巧筵。","今宵逢七夕，光景异常年。"]},{"t":"吴子夜四时欢歌 其十一","f":"五言绝句","c":["摘药裹萤火，应手药先飞。","妾貌同衰叶，追思嫁日衣。"]},{"t":"吴子夜四时欢歌 其十二","f":"五言绝句","c":["昔日梦辽西，生憎络纬啼。","欢归秋夜永，不敢怨邻鸡。"]},{"t":"吴子夜四时欢歌 其十三","f":"五言绝句","c":["应怜夜度娘，动寒往相觅。","可畏双行缠，已落雪上迹。"]},{"t":"吴子夜四时欢歌 其十四","f":"五言绝句","c":["兽炭拥貂衾，欢情中夜满。","颇怪芙蓉褥，留得三春暖。"]},{"t":"吴子夜四时欢歌 其十五","f":"五言绝句","c":["新妆非好淡，本欲学梅花。","妾异东邻女，墙头盼宋家。"]},{"t":"吴子夜四时欢歌 其十六","f":"五言绝句","c":["守岁对寒灯，寒暄兹夜隔。","侬作玉壶冰，愿君如松柏。"]},{"t":"吴子夜四时懊歌 其一","f":"五言绝句","c":["自君之出矣，缲丝头绪多。","朝来理蚕箔，不忍见双蛾。"]},{"t":"吴子夜四时懊歌 其二","f":"五言绝句","c":["妾忆初归日，栽桃碧沼旁。","君行不觉久，桃树出楼长。"]},{"t":"吴子夜四时懊歌 其三","f":"五言绝句","c":["步出城南陌，客来乘五马。","可笑使君愚，调侬绿桑下。"]},{"t":"吴子夜四时懊歌 其四","f":"五言绝句","c":["暮春朝气和，侬自肝肠热。","何许最撩人，林间啼百舌。"]},{"t":"吴子夜四时懊歌 其五","f":"五言绝句","c":["生女有所归，莫嫁吴中估。","江头望回船，日日多风雨。"]},{"t":"吴子夜四时懊歌 其六","f":"五言绝句","c":["寄语采莲伴，谁知莲苦心。","齐桡翻弄曲，若个是知音。"]},{"t":"吴子夜四时懊歌 其七","f":"五言绝句","c":["避暑水亭中，紧下葳蕤锁。","夜短梦难成，日长愁杀我。"]},{"t":"吴子夜四时懊歌 其八","f":"五言绝句","c":["少女拜新月，临阶幽意多。","但祈夫婿贵，不愿似嫦娥。"]},{"t":"吴子夜四时懊歌 其九","f":"五言绝句","c":["家住阊门外，笙歌搅独愁。","三年空见雁，两鬓易惊秋。"]},{"t":"吴子夜四时懊歌 其十","f":"五言绝句","c":["登楼望阊门，下见倡家女。","萍荇蔓芙渠，雪深谁采汝。"]},{"t":"吴子夜四时懊歌 其十一","f":"五言绝句","c":["梦断辽阳戌，心西火共流。","莫言闺里苦，边塞正防秋。"]},{"t":"吴子夜四时懊歌 其十二","f":"五言绝句","c":["拟作回文句，残机懒更开。","愁来眠不著，促织夜相催。"]},{"t":"吴子夜四时懊歌 其十三","f":"五言绝句","c":["南雪不到地，著树斗琼花。","正是可怜色，儿童休打鸦。"]},{"t":"吴子夜四时懊歌 其十四","f":"五言绝句","c":["独觞不成醉，独被不禁寒。","颇怪邻家语，喧喧到夜兰。"]},{"t":"吴子夜四时懊歌 其十五","f":"五言绝句","c":["片心焦若火，两泪滴成冰。","早晚逢西使，重园在白登。"]},{"t":"吴子夜四时懊歌 其十六","f":"五言绝句","c":["岁去暗须惊，春远似相识。","梅花在陇头，为我传消息。"]},{"t":"除夕携演春乐部过张伯起幼于昆仲园亭把玩腊梅残菊席上同赋三首 其一","f":"七言律诗","c":["江左机云远擅场，华筵法曲并传觞。","群芳已变繁霜后，空谷犹存晚节香。","艳骨未随长笛落，幽姿偏藉短篱藏。","岁寒吾辈能相守，春事何心怪底忙。"]},{"t":"除夕携演春乐部过张伯起幼于昆仲园亭把玩腊梅残菊席上同赋三首 其二","f":"七言律诗","c":["汉殿迎年催赐衣，幽人犹自把寒枝。","携来彭泽先生酒，同和扬州水部诗。","春入池塘惊晓梦，歌翻子夜倚吴儿。","巡檐欲写东篱意，冉冉孤芳可赠谁。"]},{"t":"除夕携演春乐部过张伯起幼于昆仲园亭把玩腊梅残菊席上同赋三首 其三","f":"七言律诗","c":["香色凭栏对美人，娇歌妙舞起梁尘。","谁家彩胜纷矜巧，得似蓬蒿别有春。","不惜柏尊邀上客，从教琼露湿花神。","少微夜半光连宿，坐看星回万象新。"]},{"t":"胥门晚春闲眺","f":"七言律诗","c":["胥江春浪迭平沙，野水浮来尽落花。","遥望片帆归别浦，不知双燕入谁家。","孤村斜日收渔网，远寺残钟起暮鸦。","试问城中歌舞地，何如此处最清嘉。"]},{"t":"宝带桥夜泊玩月二首 其一","f":"七言律诗","c":["长桥十里卧晴虹，吴会山川在镜中。","岂有神鞭驱海石，遥听仙佩下琼宫。","双星寄恨三天水，半夜怀人一笛风。","此去沧洲知远近，且将孤舫狎渔翁。"]},{"t":"宝带桥夜泊玩月二首 其二","f":"七言律诗","c":["潮归月落夜渐分，人语空江隔岸闻。","化鹤道士不入梦，弄珠神女能为云。","天上白榆侵桂树，枝间干鹊随鸦群。","秋近骚人无限意，乘流东下吊湘君。"]},{"t":"和申瑶翁咏物十四首 其一 竹粉","f":"七言律诗","c":["万竿晴拂渭川烟，解琼箨枝自皛然。","湘水裙摇珠佩冷，葛陂云护玉龙眠。","看来翻恨何郎妒，栽处应将汉署连。","六月林间犹带雪，可留清韵待群贤。"]},{"t":"和申瑶翁咏物十四首 其二 松涛","f":"七言律诗","c":["龙鳞蹙沓起狂飙，虎啸空山动泬㵳。","万树忽飞秦帝雨，千岩遥涌浙江潮。","徂徕欲驾神鳌去，精卫宁衔大木飘。","澎湃寒声催作赋，八乘雄笔未须骄。"]},{"t":"和申瑶翁咏物十四首 其三 花影","f":"七言律诗","c":["瑶台仙态自重重，色相元来未是空。","暂试新妆临晓镜，更怜残照倚东风。","洛神解佩淩波上，巫女行云度峡中。","几向雕兰频想像，蛾眉偏爱月如弓。"]},{"t":"和申瑶翁咏物十四首 其四 雪花","f":"七言律诗","c":["蕊宫天女下仙台，剪落琼枝片片开。","邹谷未缘吹暖律，梁园先觉报春梅。","暗香总入冰壶淡，素质非惊玉笛催。","羞向群芳誇皎洁，灵根元是倚云栽。"]},{"t":"和申瑶翁咏物十四首 其五 烟柳","f":"七言律诗","c":["垂丝百尺荫红桥，香蔼茏葱半未消。","眉黛拂残留淡粉，舞腰凝望隔轻绡。","章台雨过霏霏湿，隋苑霞明冉冉娇。","十里紫骝迷去影，临风谁折最长条。"]},{"t":"和申瑶翁咏物十四首 其六 梅雪","f":"七言律诗","c":["玄冥变律转青皇，瑶树琼花兢晓妆。","梦入罗浮偏觉冷，舟回剡曲暗闻香。","惠连赋就枝横月，何逊诗成笔带霜。","莫向蓝关觅春信，陇头消息正茫茫。"]},{"t":"和申瑶翁咏物十四首 其七 荷珠","f":"七言律诗","c":["绿波深处近鲛宫，颗颗新翻翠盖中。","光浸冰盘霏早露，影回浮仙掌舞风。","谁将罗袖探骊颔，忽有琼浆泻碧筒。","自是若耶多堕珥，歌声遥隔在江东。"]},{"t":"和申瑶翁咏物十四首 其八 烛泪","f":"七言律诗","c":["兰堂张宴夜将阑，锦幕风摇宝炬残。","乍看新花生火树，俄惊仙露满铜盘。","光浮珠汗心偏热，暗湿鲛绡焰觉寒。","恐有向隅孤影里，寄言豪客莫穷欢。"]},{"t":"和申瑶翁咏物十四首 其九 睡蝶","f":"七言律诗","c":["燕懒莺慵春昼长，舞残粉翅未须忙。","倦依柳幕为苏帐，静儭花茵作宝床。","酣处不知弦管促，醒来犹觉梦魂香。","漆园傲吏籧籧后，赋得新诗浪拟庄。"]},{"t":"和申瑶翁咏物十四首 其十 雁字","f":"七言律诗","c":["书传关塞近如何，遥见宾鸿阵阵过。","雪窖海边斜系帛，锦纹天外倩飞梭。","迹分苍颉阶前鸟，巧换山阴院里鹅。","几幅练裙堪点染，潇湘空阔静无波。"]},{"t":"和申瑶翁咏物十四首 其十一 香尘","f":"七言律诗","c":["日暖花明风正狂，马蹄终日踏花忙。","谁家罗袜莲生足，几处兰樽曲绕梁。","衣染龙涎呈妙舞，埃笼檀晕掩新妆。","芬芳岂独誇金谷，别有西施响屧廊。"]},{"t":"和申瑶翁咏物十四首 其十二 游丝","f":"七言律诗","c":["微云淡日养花天，银缕高飞百丈牵。","欲度金针窥绣阁，更随红袖拂秋千。","香风送去缠花片，细雨徐沾著柳绵。","莫道轻盈不堪织，莺梭戛戛锦丛边。"]},{"t":"和申瑶翁咏物十四首 其十三 麦浪","f":"七言律诗","c":["满陇新风翠穗浮，遥惊沧海在平畴。","桃花似涌青青沫，竹箭如翻渐渐流。","萧瑟乱霏高凤雨，涟漪堪泛范家舟。","更看万顷黄云暮，四月狂涛已报秋。"]},{"t":"和申瑶翁咏物十四首 其十四 月露","f":"七言律诗","c":["秋夕烟消万里天，冰轮沆瀣两澄鲜。","洗妆半湿霓裳袖，扬彩轻沾玉井莲。","不用方诸偏滴沥，直从仙掌望婵娟。","夜寒宫瓦层澜动，犹伴长门玉箸悬。"]},{"t":"放鹦鹉","f":"五言律诗","c":["独怜翻旋急，放汝入空林。","莫逞新声巧，能忘故主心。","防危秋隼逼，归路陇山深。","客意亦如此，因之起越吟。"]},{"t":"堤上行三首 其一","f":"七言绝句","c":["万井楼台落镜中，环堤处处小桥通。","吴娃惯荡莲舟戏，水浅沙明不畏风。"]},{"t":"堤上行三首 其二","f":"七言绝句","c":["大堤风物类襄阳，上巳年年兢女郎。","自是吴王歌舞地，至今犹学浣纱妆。"]},{"t":"堤上行三首 其三","f":"七言绝句","c":["月明谁唱竹枝歌，声绕江风起白波。","古渡春来潮正急，停舟估客意如何。"]},{"t":"寒山寺避暑对客二首寺有佳竹可以消暑 其一","f":"七言绝句","c":["隔岸垂杨暗老枫，客来清午不闻钟。","贫僧止解栽修竹，五月凉生制火龙。"]},{"t":"寒山寺避暑对客二首寺有佳竹可以消暑 其二","f":"七言绝句","c":["绿筱深深白鹤栖，烹茶烧笋称招提。","此中已入清凉界，棋局淹留日易西。"]},{"t":"江南弄","f":"七言律诗","c":["野水春来急似梭，远山日晚团如螺。","谁家莲舟起新曲，吴音片片锵寒玉。","矶头双鸳睡未足，惊飞掠破晴烟绿。","江村门巷多不俗，美人娟娟倚修竹。"]},{"t":"偶成","f":"五言律诗","c":["自得漆园意，散衙成隐居。","微官不属我，止足岂求馀。","花发侵虚牖，香消扬广除。","年来何所慕，喜看道家书。"]},{"t":"西园","f":"五言古诗","c":["西园桑椹熟，万颗红珠碎。","开尊绿桑下，鸠与人同醉。","春院足花茵，陶然堪一睡。"]},{"t":"渔樵耕牧词有序 其一","f":"五言律诗","c":["八月流潦清，芙蓉浇秋水。","白云江上来，伴宿空船里。","持竿不设饵，取适而已矣。","偏嫌张季鹰，更羡鲈鱼美。"]},{"t":"渔樵耕牧词有序 其二","f":"五言律诗","c":["大斧入平林，不踏险崖路。","野泉聊濯足，松风引轻步。","日晚负薪归，裘敝馀里布。","道旁有遗金，掉头未回顾。"]},{"t":"渔樵耕牧词有序 其三","f":"五言律诗","c":["人皆犁膏土，我独守石田。","瑶草别有根，呼鸟为耕烟。","空山学辟谷，洗心祈长年。","何事戴胜啼，来惊春昼眠。"]},{"t":"渔樵耕牧词有序 其四","f":"五言律诗","c":["驱牛出东野，新草绿于罗。","短笛叫长川，同伴扬清歌。","游牝得其时，黄犊看渐多。","不知南山下，白石近如何。"]},{"t":"姑苏八景五言古有序 其一 支硎","f":"五言律诗","c":["支公固好禅，何事偏爱马。","至今饮马处，春水潺潺泻。","王生立佳城，近在马涧下。","因悟无生法，四大皆幻者。"]},{"t":"姑苏八景五言古有序 其二 虎丘","f":"五言律诗","c":["吴王坟踞虎，不及生公石。","石悟已忘言，虎去无留迹。","我来千载后，访古一叹息。","山门夜寂寥，月冷剑池碧。"]},{"t":"姑苏八景五言古有序 其三 太湖","f":"五言律诗","c":["太湖岂云阔，天地一勺水。","我心无涯涘，汪汪亦如此。","夜来风浪收，人坐明镜里。","湖心伫彩云，缥渺思仙子。"]},{"t":"姑苏八景五言古有序 其四 上方","f":"五言律诗","c":["上方何处好，湖水浸长桥。","月出摇波光，灵鹊若可招。","醉后发清啸，空江动回潮。","何须登绝顶，高险多风飙。"]},{"t":"姑苏八景五言古有序 其五 灵岩","f":"五言律诗","c":["灵岩有古寺，人道馆娃宫。","不识西施貌，禅宗色是空。","采香幽径没，响屧落山风。","往事休回首，吴门匹练中。"]},{"t":"姑苏八景五言古有序 其六 天池","f":"五言律诗","c":["池边多灵草，山客和云拾。","若不得惠泉，碧乳成枯涩。","何如莲花石，风露寒仍吸。","仙根自玉井，千年方结实。"]},{"t":"姑苏八景五言古有序 其七 桃花坞","f":"五言律诗","c":["谁言城市近，别是一仙源。","不用闷深洞，扁舟自到门。","今时异秦世，六合共乾坤。","已见吴门卒，揶抡笑绮园。"]},{"t":"姑苏八景五言古有序 其八 莲花荡","f":"五言律诗","c":["六月廿四日，倾都出游戏。","彼美赛洛神，空江客愁思。","鸳鸯各有偶，何预傍人事。","戏水溅莲花，元来不著水。"]},{"t":"葑门城楼","f":"七言律诗","c":["独上高楼起晚愁，蒹葭衰柳绕长洲。","征徭偏有三吴苦，杼柚真伤万井秋。","失侣孤鸿翻北叫，背人寒水自东流。","忧时叹逝心俱折，露草蛛丝尚未收。"]},{"t":"锡山驿秋晓","f":"五言律诗","c":["旅食愁无寐，推蓬问驿亭。","峰明斜抱月，河侧倒漂星。","日跃鸡先觉，钟残世渐醒。","独怜枫树色，倏忽换丹青。"]},{"t":"江阴支河","f":"五言律诗","c":["江近潮偏急，喧声滚洳沙。","河回刚没胫，水浅不胜槎。","两岸多修竹，三秋见落花。","还从鸡犬里，错认武陵家。"]},{"t":"秋夜西园","f":"五言古诗","c":["秋夜夜何长，鹤梦破风竹。","此时西园意，偏赏在幽独。","日来万事扰，挥汗动盈掬。","散衙假片闲，拍月兼水浴。","冰纱帐似烟，湘簟纹如縠。","平头供笋茗，事事各不俗。","神清未渴睡，心期白云宿。","潇散脱形骸，迂疏去桎梏。","据梧窅天真，且鼓便便腹。","晓来问朝餐，三嗅东篱菊。"]},{"t":"修西园菊篱毕酌客漫赋","f":"七言律诗","c":["爱惜孤芳谨护篱，搴英片片沥寒卮。","乾坤逆旅谁为主，风物惊心有所思。","幽赏未逢桃李笑，后时宁遗蝶蜂知。","一官牢落令如此，与尔高歌倒接䍦。"]},{"t":"治平寺梅花","f":"七言律诗","c":["寺僻云深车马稀，踏来残雪弄芳菲。","参禅香色怜俱淡，迟日风花莫乱飞。","拂□宝幡春袅袅，隔林清磬夕微微。","老僧剩有孤山兴，放鹤湖边尚未归。"]},{"t":"阳澄湖歌有序","f":"楚辞体","c":["虹拖飓母龙吼云，巨浪直上翻高旻。","扁舟系缆不敢发，须臾雨霁浪全歇。","雷声隐隐度远山，霞气盈盈漾轻碧。","挥杯酹河伯，为尔笑大方。","来牛去马不复辨，论蛙语鳖聊相忘。","雄风怀袖里，三啸棹歌起。","洞庭缥缈七十峰，片片芙蓉立仙子。","酒酣命客吹玉箫，青翳玄鹤不待招。","遥忆吴王歌舞后，锦帆天外落归潮。","归潮已没鸱夷革，此中怨结潮头白。","昔日曾闻市井喧，千年忽变鲛人宅。","为我诅河伯兮何不仁，荒田满目兮愁吾人。","萑苇丛生鹅鹳喜，打鱼供税多酸辛。","代民请命胡为者，欢息湖滨泪潸下。","阳城能复作宣房，县令自甘沉璧马。","精卫徒劳心血枯，沧桑何止历阳都。","功成却羡扁舟客，落日归心寄五湖。"]},{"t":"芦中谣并序","f":"五言古诗","c":["今岁秋成好，家家足稻粱。","问侬稻安在，菇芦水一方。","共道江南美，江南信都会。","闲田倩袅耕，白水能供税。","场工十月毕，击鼓赛田神。","吴侬争祭肉，可念未归人。","荷锄肌入霜，挥锄汗成雨。","但愿有田锄，不惜锄田苦。","鱼龙睡秋水，寡妇哭秋原。","数家逃散后，萧索不成村。","豪家艘四橹，索负无鸡犬。","流亡今稍归，嗟尔好焚券。","长吏午未铺，问侬曾苦饥。","侬言不苦饥，昨日幸晨炊。","县胥夜半至，柴门不用敲。","子孙今卖尽，秪有一丛茅。","芦荻拥篱根，空场无鸟雀。","寒风四壁入，敝裤不堪著。","云深江路黑，三星夜在笱。","为听田家言，不觉归来久。"]},{"t":"倚竹歌","f":"古风","c":["主人好种玉，绕屋森琅玕。","青青不避三冬雪，摵摵能生五月寒。","丛底可宜喧啅雀，枝头犹欲伫鹓鸾。","瑶琴抱出西园里，翛然四面清风起。","似随流水到潇湘，水碧沙明映妃子。","湘江妃子绿罗裳，嫩粉初凝解箨妆。","谁道柯亭堪制笛，试听清韵一登床。","细雨龙孙争迸出，须臾个个干云长。","倚竹林、消永日，棋局对壶觞，意态何真率。","直节休论隐士竿，虚心且应郎官笔。","竹声戛戛发浩歌，金尊沸沸扬洪波。","糟丘麴垒护篱落，七贤豪饮酣天和。","醉余梦卧伶伦谷，醒来散发晞新沐。","自占园中数步阴，渭川千亩翻嫌俗。","怪底主人诗骨瘦，为对此君不食肉。"]},{"t":"姑苏春情五首 其一","f":"七言律诗","c":["望中佳气满吴门，青帝行春入广原。","柳眼渐醒蝴蝶梦，条风初返杜鹃魂。","娇歌急管随车度，袨服新妆映日翻。","共道丰年多乐事，球场先已选名园。"]},{"t":"姑苏春情五首 其二","f":"七言律诗","c":["笳鼓喧阗引土牛，汉官冠盖若云浮。","铜街玉勒看调马，绣户珠帘尽上钩。","词客别裁新乐曲，华筵初换小俳优。","万钱不羡何家侈，七贵堂中列五侯。"]},{"t":"姑苏春情五首 其三","f":"七言律诗","c":["七宝香车斗侠斜，褰帷一笑尽良家。","晴光自暖风前玉，春色先催胜里花。","舞袖拂钗轻化燕，行云落鬓滑翻鸦。","不知宴罢消春夜，谁并阊门萼绿华。"]},{"t":"姑苏春情五首 其四","f":"七言律诗","c":["骚客乘春日半臐，翩翩步障散红云。","柔桑陌上逢秦女，青翰舟中见鄂君。","芳树莺声偷玉笛，远郊草色上罗裙。","春深预约兰亭饮，肯信流觞属右军。"]},{"t":"姑苏春情五首 其五","f":"七言律诗","c":["堪叹年华漏箭催，东君邀客且徘徊。","谁家巧黛传新柳，有女怀春待标梅。","十里香尘迷下市，千重芳思在层台。","兴来须赴高阳会，休动江南庾信哀。"]},{"t":"闻同年王淑明何充符因忤税监被逮作四首 其一","f":"五言律诗","c":["逼侧徒伤汝，乾坤孰爱才。","忤人偏傲骨，对吏已寒灰。","剑抱曲城怨，霜飞燕地哀。","谁传黄雀语，为雪冶长猜。"]},{"t":"闻同年王淑明何充符因忤税监被逮作四首 其二","f":"五言律诗","c":["宦途随燕雀，苦海更豺狼。","蜴吐阴云合，雷轰白日藏。","八厨元不愧，三木任为囊。","万一皇恩转，春生到夜郎。"]},{"t":"闻同年王淑明何充符因忤税监被逮作四首 其三","f":"五言律诗","c":["圣人临北阙，君子叹南冠。","骥病思千里，途穷恨一官。","忧时双鬓白，恋主寸心丹。","万国皆涂炭，谁非行路难。"]},{"t":"闻同年王淑明何充符因忤税监被逮作四首 其四","f":"五言律诗","c":["中宵兴浩叹，明月入梁虚。","有梦疑颜色，无人脱槛车。","更裁穷鸟赋，好授狱中书。","李杜齐名在，千秋孰尔如。"]},{"t":"送袁广文迁藩僚不就归安庆","f":"七言律诗","c":["收尽吴门桃李春，图书归箧未全贫。","小山好客能招隐，野鹤摩空耻傍人。","秋月乘舟堪咏史，空斋卧雪任闲身。","怜君漉酒无长物，聊赠清风一葛巾。"]},{"t":"送萧丞罢官归大庾","f":"七言律诗","c":["几年吏隐共微官，九折悲歌行路难。","老去哦松堪自寄，归来弹铗好谁看。","剑横丰水双龙杳，马散吴门匹练寒。","何事东风将别恨，嘤嘤啼鸟属春阑。"]},{"t":"陆丹徒年兄招饮甘露寺","f":"七言古诗","c":["古来北固号吴关，云水楼台罨画间。","主人风流美为政，暇日携客同登攀。","长洲仙令罗浮子，喜往名山洗心耳。","蹑屐高冲宿雾收，振衣长啸雄风起。","此时春日丽春台，桃花杏花次第开。","山头莺鹤不避客，眼底鱼鸟皆迎杯。","江胥出游群龙舞，湘妃挟瑟冯夷鼓。","命句愁翻鲛室珠，挥巾恐挂珊瑚树。","春台长日坐氤氲，下界喧嚣寂不闻。","冯阑洒酒来空翠，击节征歌伫白云。","半酣遥措金陵城，六代兴亡似醉醒。","连天江水千重碧，隔岸扬州一片青。","江水东流达海门，烟波渺渺得仙源。","金焦何必誇名胜，蓬岛犹闻列上尊。","两腋雄风将羽化，半生傲骨终难下。","便可三山跨凤皇，谁堪五斗呼牛马。","携来甘露满冰壶，一滴灵芽永不枯。","主人已傍山阴住，为问门前旧镜湖。"]},{"t":"拟古杂体十九首并序 其一 古思边","f":"古风","c":["边马渴长嘶，夜过长城窟。","欲饮嫌水腥，其中多胔骨。","昨日鸣战鼓，今宵闻鬼啼。","生入玉门他日事，深闺且慢梦辽西。"]},{"t":"拟古杂体十九首并序 其二 古别离","f":"古风","c":["悲来不数斑竹血，愁来不数青冢月。","人心咫尺有别离，床前忽自成胡越。","君不见相如已受长门金，茂陵欲娶成哀吟。","道旁一顾停五马，蛾眉相遇黄泉下。"]},{"t":"拟古杂体十九首并序 其三 折杨柳","f":"七言绝句","c":["杨叶开时学妾眉，杨条折处正伤离。","杨花乱舞撩春思，况罥东风百尺丝。"]},{"t":"拟古杂体十九首并序 其四 远期篇","f":"古风","c":["远期共携手，百年未为久。","君看貌如花，倏忽成老丑。","蓬山仙子金银台，坐见蟠桃几度开。","为报看棋烂柯客，子孙不识好归来。"]},{"t":"拟古杂体十九首并序 其五 关山月","f":"古风","c":["关山随地阔，明月万里同。","莫言万里同，更有雨兼风。","嫦娥好独处，玉兔还为侣。","闲庭月落尚捣衣，乞将灵药学轻飞。","不然吹晕翻成缺，待与边城一解围。"]},{"t":"拟古杂体十九首并序 其六 艾如张曲","f":"古风","c":["萧萧蓬与艾，稚子张罗戏。","黄口动成擒，焉知青鸟志。","高飞远食玉山禾，机械篱边奈尔何。"]},{"t":"拟古杂体十九首并序 其七 钓竿歌","f":"七言律诗","c":["古人钓国复钓名，严滩渭水未全清。","美人修竿生自直，和烟砍却还青青。","连举六鳌笑不取，桂舟浅浦何容与。","寄语悠悠世上儿，江月江风本无主。"]},{"t":"拟古杂体十九首并序 其八 陌上桑","f":"古风","c":["当春绿桑柔，怀春女出游。","不及秦氏女，百媚娇且羞。","使君来，一何愚。","停道侧，久踟蹰。","使君不念立马疲，妾自归去怜饥。"]},{"t":"拟古杂体十九首并序 其九 昭君辞","f":"七言古诗","c":["嫖姚北伐军声起，左贤祭马擐弓矢。","汉胡格斗沙场里，伏尸如山一千里。","不及明妃西入胡，胡庭美女皆羞死。","翻将汉曲奏琵琶，雪碛穹庐冬见花。","万古惟悲青冢月，谁怜诸将骨如麻。"]},{"t":"拟古杂体十九首并序 其十 王子乔","f":"古风","c":["人道迩，仙道遐。","不见王子乔，千年一去不还家，寂寥笙鹤令人嗟。","彭祖巫咸前后死，玉棺何处葬仙子。"]},{"t":"拟古杂体十九首并序 其十一 东门行","f":"古风","c":["出东门，临大道。","道上来往人，一行一回老。","莫嫌相对贫，相对贫亦好。","将进酒，强牵衣。","云离山，几岁归。","车轮未转肠先转，万行涕下风吹断。","君去郊送归郊迎，黄金斗印莫相轻。"]},{"t":"拟古杂体十九首并序 其十二 鞠歌行","f":"古风","c":["年年上巳与清明，九衢车马嬉春晴。","琼楼弄琵琶，故作断肠声。","何人传此曲，曲罢春郊遍青绿。","踏青女儿年十五，纤腰如柳向人舞。","蹴鞠蹴鞠夜忘归，归来庭畔月移午。"]},{"t":"拟古杂体十九首并序 其十三 虾䱉篇","f":"五言律诗","c":["不识三神山，乃在六鳌背。","任公一举钓，失水翻成脍。","谁知尔虾䱉，乃在蹄涔内。","鄙夫营七尺，达士期方外。"]},{"t":"拟古杂体十九首并序 其十四 乌生八九子","f":"楚辞体","c":["君不见古时九日烧天红，乌生九子巢日中。","飞上天门尾毕捕，落翅徒伤后羿弓。","乌乃叩阍诉天帝，后羿何不念其妻。","窃药一入月，弯弓不射还嗟别。","兔何德兮乌何辜，世间贞女多狂夫。"]},{"t":"拟古杂体十九首并序 其十五 箜篌引","f":"古风","c":["弹箜篌，声正扬。","河之水，流汤汤。","被发之叟学吕梁，有身反向鱼腹藏。","传语此公无渡河，渡河当更奈公何，人间平地多风波。"]},{"t":"拟古杂体十九首并序 其十六 日出行","f":"古风","c":["世上何碌碌，名利驱人不遑宿。","君看日亦无闲时，东海西山转如毂。","誇父誇父何其愚，与日竞走胡为乎。"]},{"t":"拟古杂体十九首并序 其十七 双桐生空井","f":"古风","c":["井不吸，虚银床。","桐易老，思鸾凰。","削桐为琴扬哀音，秋思千重如井深。","邻姑听琴夜独语，井鲋孑孑谁与处。"]},{"t":"拟古杂体十九首并序 其十八 善哉行","f":"古风","c":["百年何蠢蠢，少女看木槿。","一朝失顾盼，红颜零落尽。","来日苦短去日长，麻姑金母发如霜。","蓬莱山下水，已种数株桑。","感此芳时春将晚，酒朋棋伴郊游远。","牵落日，倩游丝。","黄鹂唤东风，为我停须斯。","杖头休道酒价乏，隔岸榆钱飞策策。","借问海上仙，何如此欢伯？","歌善哉，醉方归。"]},{"t":"拟古杂体十九首并序 其十九 当垆曲","f":"古风","c":["客来未饮酒，熏却东风醉。","胡姬十二试当垆，见客含羞翻欲退。","新教一曲能半能，歌喉娇涩水凝。","豆蔻枝头花未吐，芳心一点轻于露。","槽边㶁㶁滴酴醾，迷杀阳城下蔡儿。"]},{"t":"白龙祠祷雨有应喜作长句","f":"楚辞体","c":["阳山之溪幽且深，澄潭直下千万寻。","龙祠俯视潭之阴，彩云白雾时萧森。","神龙犹念所生处，岁鞭列缺归省姆。","回首吴民皆桑梓，喜霈甘霖溉吴土。","县官为民酬若龙，春秋祀事洁而丰。","何者肥■煽蕴隆，火旗焰焰烧天红。","江焦汤沸冯夷宫，龙兮睡醒怒气冲。","立檄九河与四渎，青虬黑蜧来趋风。","云将初列阵，雨师骤发箭。","忽虞山岳翻，乍觉乾坤战。","郊外商羊舞欲狂，垤中鹳鹤呜且翔。","古洞无劳击阴石，市廛何用燔巫尪。","九扈兴歌田畯喜，苗秀青青如栉比。","万户同欢大有年，催科幸免烦鞭棰。","雨珠雨玉贺升平，祠下宜添喜雨亭。","大泽不忘功德水，年年岁岁荐芬馨。"]},{"t":"阳山坞内小溪","f":"五言律诗","c":["小溪缘密条，茅屋岸东西。","野老鸥为侣，孤松鹤并栖。","避喧今几世，入洞昔人迷。","坐爱烟霞晚，回桡返照低。"]},{"t":"春日泛舟四首 其一","f":"五言律诗","c":["棹歌翻渌水，击汰复夷犹。","吴越春江合，东南王气浮。","鸣榔遥向若，岸帻不惊鸥。","渺渺五湖客，烟波如可求。"]},{"t":"春日泛舟四首 其二","f":"五言律诗","c":["江练晴堪染，汀兰静自芳。","已宜君子佩，不倩好风扬。","折采香盈把，怀人水一方。","轻桡徐转去，春望浩茫茫。"]},{"t":"春日泛舟四首 其三","f":"五言律诗","c":["洗耳疑仇俗，怀沙怅独清。","岂知簪绂内，不异薜萝情。","舒啸沧浪晓，观空水月明。","乘流无住著，自在玉壶行。"]},{"t":"春日泛舟四首 其四","f":"五言律诗","c":["闻道蓬瀛外，鲸波若拔山。","秦皇空望幸，方士去无还。","纵有金银阙，其如风浪艰。","静观濠上理，心与广川闲。"]},{"t":"赠渔父并序","f":"七言律诗","c":["野老歌传欸乃清，和风淡荡漾仙声。","烟波不杂市朝态，鼓枻非关去住情。","奏急鱼龙号绝浦，响回莺鹤下层城。","吏情未觉沧洲远，倩汝微澜为濯缨。"]},{"t":"姑苏元夕集诸词客得朋字排律二十六韵","f":"五言古诗","c":["吴门歌舞地，乐事日相仍。","况遇千金夕，遥临片月澄。","条风吹凤野，新暖解鲛冰。","绣陌香尘匝，铜街瑞气凝。","楼台甲第敞，裘马少年矜。","赵李皆连戚，金张各引朋。","春思方浩荡，逸兴寄冯陵。","共庆瑶天爽，同欣玉烛登。","蚖脂明绛蜡，豹髓隔红缯。","兢斗丁谖巧，争誇万毕能。","鳌山浮陆海，星彩避华镫。","火树家家灿，骊珠颗颗升。","祗须惊绚耀，未易辨名称。","锦席九枝满，兰殽百味蒸。","初筵心已醉，列炬目为瞢。","实从纷轮至，徘优次第征。","鱼龙翻角觗，杆索互缘乘。","士女写交错，笙歌鼎沸腾。","欢声摇地轴，高响遏云层。","蹴鞠丸随足，秋千凫度縆。","登场重选伎，催曲迭酬绫。","良夜真堪赏，幽怀若不胜。","可怜花满面，岂吝酒如渑。","虬箭停寒漏，鸡人报旭升。","横桥无铁锁，归骑踏金绳。","相约留馀兴，来宵更倍增。"]},{"t":"西园听客弹琴","f":"五言古诗","c":["尝怪古人愚，临流偏洗耳。","耳中本清虚，更无物可洗。","谁为扬天籁，自入清虚里。","此时冷冷意，片片随流水。","曲罢两无言，林间竹风起。"]},{"t":"临高台","f":"古风","c":["临高台，好风淡荡从东来。","朔鸿已去燕未返，坐令春信空相猜。","台前秋千兼蹴鞠，千门嫩柳如新沐。","白马雕鞍轻薄儿，春游倦入谁家宿。"]},{"t":"春思二首 其一","f":"五言绝句","c":["芳树临清沼，红颜落镜中。","催花惟丽日，莫怨雨兼风。"]},{"t":"春思二首 其二","f":"五言绝句","c":["梦破纱窗晓，西园乌乱啼。","春情纵摇荡，犹胜听莎鸡。"]},{"t":"牡丹四绝 其一","f":"七言绝句","c":["纷纷红紫战春场，叵奈东风掠阵狂。","谁道青皇不解事，故将后劲属花王。"]},{"t":"牡丹四绝 其二","f":"七言绝句","c":["绣幄珠帘护宝栏，露华犹自怯朝寒。","呼童暖酒浇檀晕，春色偏怜带醉看。"]},{"t":"牡丹四绝 其三","f":"七言绝句","c":["共道名花肯让花，后于桃李殿韶华。","寄言二八楼头女，不必先窥宋玉家。"]},{"t":"牡丹四绝 其四","f":"七言绝句","c":["轻盈似入昭阳掌，浓艳堪回照夜车。","朱鸟池边传资讯，好将颜色付红蕖。"]},{"t":"芍药","f":"七言律诗","c":["幸与花王为近侍，承恩偏得倚芳丛。","赵家姊妹低昂里，杨氏诸姨顾盼中。","掩袖自惭当国色，向人如语怨东风。","香车宝马春游晚，寄赠多情有蝶通。"]},{"t":"倦夜","f":"五言律诗","c":["行云逆流月，惨淡有无间。","世态谁能定，浮名好是闲。","倦来凭碧簟，梦去绕青山。","侧想沉冥子，经年长闭关。"]},{"t":"独游上方三首 其一","f":"七言律诗","c":["上方兰若逼诸天，有客乘飙弄紫烟。","悟入忘言遣玉麈，坐观无相得金仙。","三花洞里浑金古，朝菌人间自岁年。","谁道漆园非傲吏，逍遥吾拟远游篇。"]},{"t":"独游上方三首 其二","f":"七言律诗","c":["重来风日正宜人，山色湖光淡淡分。","象外烟霞闲处得，仙家鸡犬静中闻。","空虚法界依双树，流浪尘踪付片云。","寄语山灵非逋客，相过何必更移文。"]},{"t":"独游上方三首 其三","f":"七言律诗","c":["长日风林坐玉壶，凭栏千里散平芜。","扁舟湖上今能否，匹练吴门问有无。","缥渺野心凫共远，凭陵侠骨剑同孤。","休誇作赋登高者，元是高阳旧酒徒。"]},{"t":"偶读东坡海外寄人书云某到贬所半年百凡粗遣更不能细说大约似灵隐天竺和尚退院后却住一个小村院于折足铛中糙罨米饭吃便过一生也得令人绝倒戏成三绝以效希调 其一","f":"七言绝句","c":["海外仙人兴不孤，烟波东去即蓬壶。","青童能供胡麻饭，肯问铛中米有无。"]},{"t":"偶读东坡海外寄人书云某到贬所半年百凡粗遣更不能细说大约似灵隐天竺和尚退院后却住一个小村院于折足铛中糙罨米饭吃便过一生也得令人绝倒戏成三绝以效希调 其二","f":"七言绝句","c":["野鹤横江化羽人，德云元说是前身。","人闲一谪无长物，最爱先生彻底贫。"]},{"t":"偶读东坡海外寄人书云某到贬所半年百凡粗遣更不能细说大约似灵隐天竺和尚退院后却住一个小村院于折足铛中糙罨米饭吃便过一生也得令人绝倒戏成三绝以效希调 其三","f":"七言绝句","c":["小吏红尘耻折腰，王乔葛令待相招。","偶看海外谈天竺，自笑莱无甑尚饶。"]},{"t":"暮春寄同社","f":"七言律诗","c":["子胥门外水空波，春事阑跚感慨多。","对酒东风啼越鸟，怀人子夜听吴歌。","漆园傲吏殊无赖，竹里狂生近若何。","寄语揖仙楼上月，年来清梦数回过。"]},{"t":"春晓","f":"五言律诗","c":["旭日明虚室，流光鉴薄帏。","梦回迷晓蝶，忘却换春衣。","百卉频开落，年华有是非。","片云天际淡，可比宦情微。"]},{"t":"暮春舟中","f":"七言古诗","c":["沉水之香通太灵，虎丘新茶云乳青。","烹茶晓汲惠山水，焚香卧读黄庭经。","江南春暮已如此，花落清流成锦水。","燕语莺啼大著忙，素心不寄春光里。","一缕轻烟起博山，清风习习满怀间。","江皋倘遇天随子，应共扁舟去不还。"]},{"t":"苦雨己亥有水","f":"七言律诗","c":["不畏沙崩损药栏，遥邻麦秀落风湍。","海童有意迎神女，暴雨何曾避灌坛。","薄暮回飙吹野哭，深更哀角动春寒。","临流欲洒疮痍泪，祗恐偏增浊水澜。"]},{"t":"落花二绝 其一","f":"五言绝句","c":["舞片辞蜂嘴，馀香到马蹄。","燕回休太息，好去探春泥。"]},{"t":"落花二绝 其二","f":"五言绝句","c":["金谷香尘散，楼头逐晓风。","莫言春有暮，总是色皆空。"]},{"t":"月","f":"五言律诗","c":["枕簟起秋思，夜深群动歇。","斜倚桂树枝，徘徊望秋月。","风吹晕渐破，露洗光仍发。","遥念广寒人，天空云水阔。"]},{"t":"晓","f":"五言律诗","c":["聊寄一枝宿，起来何所思。","西山对高阁，爽气入支颐。","累牍怜多事，三竿出每迟。","夜来虚室梦，似与白云期。"]},{"t":"寄袁伯益望江","f":"五言律诗","c":["五斗堪春酿，愁来几醉眠。","谁能柔绕指，一任直如弦。","风雨寸心折，闲忙两地偏。","怜余甘拙宦，相念一潸然。"]},{"t":"忧谗寓言","f":"五言律诗","c":["问影何所为，愀然浑不语。","共为天地客，暂与尔俦侣。","孤灯对不疑，皓月还同步。","勿逢沙中蜮，半路失相顾。"]},{"t":"悲火葬","f":"七言律诗","c":["夜雨啼乌黯自怜，何人忍断蓼莪篇。","肯将儿女千行泪，尽付郊原一片烟。","洞劫已甘投火宅，清凉无路到罗天。","年年寒食清明节，徒向江边酹纸钱。"]},{"t":"阊门春望","f":"七言律诗","c":["王孙愁见草萋萋，客里逢春意转迷。","几处艺兰依浅浦，谁家拾翠上平堤。","荒台旧苑孤烟外，流水闲云野日西。","欲写春来无限恨，东风时倩一鹃啼。"]},{"t":"赠谢曰可年丈","f":"七言律诗","c":["江练平铺彩笔飞，何人不识谢玄辉。","袖中谏猎书犹在，门外张罗客渐稀。","李白夜郎今更远，贾生宣室几年归。","浮尘扰扰豺狼满，奏罢离歌易湿衣。"]},{"t":"久客","f":"五言律诗","c":["梁上喧双燕，逢春亦解归。","往来看旧垒，岁月老乌衣。","得食众雏长，窥帘傍母飞。","吴门馯久客，对尔泪长挥。"]},{"t":"阊门观竞渡戏作长歌","f":"楚辞体","c":["端阳新雨涨平堤，柳暗长桥莺乱啼。","万户楼台如镜里，千门弦管喧于市。","五丝系臂醉蒲觞，争看龙舟戏江水。","红帘彩鹢木兰桡，锦缆牙墙奏玉箫。","簇簇黄头歌欸乃，重重翠扇伫娇娆。","楼船画舫纷停泊，别上江亭开水阁。","两岸游人似堵墙，绮罗耀日相交错。","游人开处使君来，伐鼓填填响若雷。","屏帐駊騀张巨舫，琼筵乐部递相催。","使君重文兼好客，当筵载笔皆词伯。","未许丰容斗艳妆，直从险峻看标格。","梨园曲罢报诗成，江上游龙急瞲声。","鳞甲翻波风雨恶，江胥河伯避霓旌。","输嬴未决雌雄队，垒鼓催桡浪花碎。","锦标夺得快先登，两岸千人齐喝采。","输者惭兮嬴者矜，回舟赌胜更凭陵。","江波咫尺分吴越，往事千年感废兴。","越兴吴废付东流，南国烟花恣浪游。","谁向澄潭伤屈子，空余兰杜结离忧。","湘兰沅杜长江隔，吴门还有鸱夷革。","日暮潮来天地青，剑光袍铠如银白。","江南士女自嬉嬉，话及前朝总不知。","嬴输兴废浑闲事，莫怪山公倒接䍦。"]},{"t":"夏清夜吟","f":"古风","c":["世上仅三乐，人间止百年。","羲和何太苦，朝暮不停鞭。","峥嵘火云连赤阪，入夜惟愁日车返。","冰纱为帐扇轻纨，竹气梧风清更远。","此时煮茗在虚亭，剥笋还窥玉札经。","为鲧烛龙聊税驾，来朝微雨待人醒。"]},{"t":"冰盘瓜藕","f":"五言律诗","c":["热思寒水玉，更忆葛仙方。","忽对片冰皛，能生六月凉。","甘瓜翻几滑，脆藕拂盘香。","坐听莲歌晚，青门意更长。"]},{"t":"江村吟 其一","f":"五言律诗","c":["吴会繁华地，淳风在野村。","桑麻连户牖，禾黍散鸡豚。","茅屋还堪赋，江亭好避喧。","壶觞依浅草，真乐满田园。"]},{"t":"江村吟 其二","f":"五言律诗","c":["稚子捉杨花，呼群更打鸦。","嬉游忘帝力，耕凿任农家。","野径飞晴蝶，平畴噪乱蛙。","陶然上皇世，不道武陵遐。"]},{"t":"江村吟 其三","f":"五言律诗","c":["新月带斜辉，江村动夜扉。","笛残知牧返，歌扬识渔归。","薄雾笼波淡，疏灯隔竹微。","孤舟同鹭宿，尘梦夕来稀。"]},{"t":"江村吟 其四","f":"五言律诗","c":["畚锸如云集，周防为水区。","今朝勤妇子，他日变荒芜。","敝裤宁堪著，新租未易逋。","一劳真永逸，尚胜北山愚。"]},{"t":"拟吴宫行乐词五首并序 其一","f":"七言古诗","c":["阵扫东南一敛收，水犀十万日椎牛。","君王气盖百二州，锦帆龙舸江中流。","吴歈子夜风傅曲，台上栖乌不得宿。"]},{"t":"拟吴宫行乐词五首并序 其二","f":"七言古诗","c":["苏台高出浮云外，吴越诸山几案对。","美人舞罢王半醉，丝管啁啾滴空翠，珠帘卷却吴江水。"]},{"t":"拟吴宫行乐词五首并序 其三","f":"七言古诗","c":["斗鸡陂西走狗塘，云芽露蕊红兰芳。","美人拾翠行采香，珠璎宝衱摇琅琅。","归来响屟香风绕，月娥西镜森相照，天鸡不报吴宫晓。"]},{"t":"拟吴宫行乐词五首并序 其四","f":"七言古诗","c":["乌啼集菀不集枯，越王行酒妻与夫。","东南半壁开霸图，烟沉烽净一事无，今不行乐胡为乎。"]},{"t":"拟吴宫行乐词五首并序 其五","f":"古风","c":["茂苑花，阊门柳。","万石钟，千日酒。","醉杀吴儿小垂手。","采莲夜渡消夏湾，鱼龙听曲沧波间。","谁解浣纱裁白纻，岁岁年年呈妙舞。"]},{"t":"伤吴宫绝句","f":"七言绝句","c":["馆娃宫畔暮烟迷，响屟廊中返照西。","莫话吴王当日事，恐惊寒鸟一时啼。"]},{"t":"拟竹枝词四首 其一","f":"七言绝句","c":["溪女蓬鬟日召负，担头十指尚纤纤。","路逢年少轻调笑，连袂清歌望酒帘。"]},{"t":"拟竹枝词四首 其二","f":"七言绝句","c":["狂夫一去动经秋，日日祈神锦水头。","每下鸣机逢七夕，几回肠断为牵牛。"]},{"t":"拟竹枝词四首 其三","f":"七言绝句","c":["剑阁连云欲插天，人心险恶更堪怜。","凭君寄谢临邛女，又被风吹过别弦。"]},{"t":"拟竹枝词四首 其四","f":"七言绝句","c":["薛涛坟畔尽桃花，犹忆新笺锦作霞。","云雨竟随巫峡散，空余明月落谁家。"]},{"t":"秋山","f":"七言绝句","c":["秋山丛桂暗松门，黄菊西风酒一尊。","莫问闲房幽径里，向来离合敢重论。"]},{"t":"斋居","f":"五言律诗","c":["休沐缘多病，西园春雨馀。","戒荤扶药饵，列菹当鲑鱼。","喧杂非吾性，清羸合道书。","真成香案吏，已伴玉皇居。"]},{"t":"塘上行","f":"五言绝句","c":["水落银塘净，芙蕖飒已秋。","可怜枯叶上，乃有绿龟游。"]},{"t":"灵岩琴台畔松径遇吴师因赠","f":"五言古诗","c":["琴台出石径，三月松花黄。","好风从东来，散落皆天香。","野老行茯苓，白石煮琼浆。","扫花春酿熟，醉饱能休粮。","萝薜洞门古，闭关春昼长。","谁知灵岩畔，已到蓬山乡。","野老竟为谁，恐是汉张良。"]},{"t":"吴门七夕三首 其一","f":"七言绝句","c":["银汉轻波漾月华，桥边灵鹊护鸾车。","未知天上情多少，秋思人间遍万家。"]},{"t":"吴门七夕三首 其二","f":"七言绝句","c":["吴门巧女世应稀，看罢双星更上机。","绣出鸳鸯宫锦灿，为他人作嫁装衣。"]},{"t":"吴门七夕三首 其三","f":"七言绝句","c":["楼头乞巧夜将阑，五彩朱丝落玉盘。","不见倡家金屈膝，何曾身傍绣床看。"]},{"t":"归兴七首并序 其一","f":"五言律诗","c":["懒性宜高枕，途危畏及秋。","非无溟北翼，自薄陇西游。","葛令求丹药，江生笑黑头。","凭谁解馀意，试一问沙鸥。"]},{"t":"归兴七首并序 其二","f":"五言律诗","c":["尘容聊一洗，发垢正新梳。","药里开蛛网，芸编走蠹鱼。","调希弦可解，意到竹堪书。","寄谢劳劳客，无烦问索居。"]},{"t":"归兴七首并序 其三","f":"五言律诗","c":["岂避弓蛇影，生憎凫胫添。","闲看稚子戏，未怪老夫潜。","粳稻馀三釜，蚕桑具一缣。","谁云吏情淡，盘有水晶盐。"]},{"t":"归兴七首并序 其四","f":"五言律诗","c":["微禄不果腹，浮生堪息机。","空囊吾已惯，丛桂旧相依。","失路行偏远，回头未觉非。","秋风病百草，正长北山薇。"]},{"t":"归兴七首并序 其五","f":"五言律诗","c":["竹林真玩世，金马伪逃名。","达士期朝彻，高人贵夜行。","寒蝉秋自急，凉露饮逾清。","天下滔滔是，吾将学偶耕。"]},{"t":"归兴七首并序 其六","f":"五言律诗","c":["匡坐适禅心，西风入爽襟。","归存压舟石，不用买山金。","溟渤万千顷，罗浮四百岑。","冷然如可禦，汗漫托知音。"]},{"t":"归兴七首并序 其七","f":"五言律诗","c":["对妇品茶谱，呼儿检药经。","一区虚白室，半亩草玄亭。","浊酒堪埋照，东篱笑独醒。","放歌元自解，歌竟若为听。"]},{"t":"感遇 其一","f":"五言古诗","c":["太虚干元化，圜转固无端。","茫茫大千界，劫火或已然。","谁持石五色，更为补皇天。","堂上乐方宴，杞国空忧煎。","山中抱黄犊，归去种春田。"]},{"t":"感遇 其二","f":"五言律诗","c":["索居曾几何，夏火忽改木。","夜露凄已白，桂枝自含绿。","幽香好暗持，不为旁人馥。","嗟彼园中葵，逢秋不卫足。"]},{"t":"感遇 其三","f":"五言律诗","c":["君平既弃世，犹复在市廛。","简圭出垢石，淤土生红莲。","观化洞无始，不为买卜钱。","大隐正在兹，授老垂空帘。"]},{"t":"感遇 其四","f":"五言律诗","c":["鲁国尽若狂，钟鼓拜爰居。","获麟不善保，反为尼父吁。","皇风代沦煽，大道日丘墟。","试问道傍者，何如沮溺愚。"]},{"t":"感遇 其五","f":"五言古诗","c":["吾爱桃源洞，幽居绝世氛。","子孙忘晋代，衣服自秦人。","宁知镐池壁，久遗祖龙君。","招魂长城下，不来早问津。","愿将鸡犬去，永与麋鹿群。"]},{"t":"感遇 其六","f":"五言古诗","c":["此亦一是非，彼亦一是非。","人具曰予圣，乌能辨雄雌。","所以古达人，一哂皆孩之。","遐想鸿荒前，衣服乃毛皮。","凿窍混沌死，吾将杜德机。"]},{"t":"感遇 其七","f":"五言古诗","c":["翩翩汉飞将，射虎真空群。","驭下闲刁斗，连营岂薄恩。","罢来逢醉尉，不识故将军。","梁燕兼门雀，飘如陌上尘。","玉壶有天地，养晦以全真。"]},{"t":"感遇 其八","f":"五言古诗","c":["精卫一何愚，衔尽西山石。","东溟波万里，力微岂能敌。","独怜帝女灵，芳魂或重溺。","仲尼浮海心，李叟流沙迹。","知不可柰何，安命甘踵息。"]},{"t":"感遇 其九","f":"五言律诗","c":["邵平瓜已熟，五色绚田畴。","人知瓜美好，讵识东陵侯。","地近心偏远，路旁自悠悠。","好扫秦坑灰，为他粪垄头。"]},{"t":"感遇 其十","f":"五言律诗","c":["静坐心无事，幽居日觉长。","明窗与净几，扫地更焚香。","秋色已如此，浮云怪底忙。","吟成聊抱膝，世路付亡羊。"]},{"t":"感遇 其十一","f":"五言古诗","c":["一破名利关，觉非如不及。","设膻游蚁聚，张烛飞蛾集。","得嗜性所便，近死乃逾疾。","何如五彩囊，采露华山室。","无事风尘眼，仙童坐相失。"]},{"t":"感遇 其十二","f":"五言律诗","c":["嗷嗷誇毗子，自谓挈瓶智。","达者笑观场，翻同傀儡戏。","君王怒偃师，手触歌声碎。","谁知造化心，塞翁以为识。"]},{"t":"感遇 其十三","f":"五言古诗","c":["我登苏台上，怀古生百忧。","霸气已沦没，草深麋鹿游。","锦帆落天外，孤月照长洲。","彼美五湖子，翛然不系舟。","功成耻受爵，亮节激千秋。"]},{"t":"感遇 其十四","f":"五言古诗","c":["三五明月满，二八明月缺。","大钧忌常盈，至人贵藏哲。","犬出东门怨，鹤向华亭咽。","梁鸿与德耀，赁春自埋没。","千载阜庑下，令人想遗烈。"]},{"t":"感遇 其十五","f":"五言古诗","c":["家本罗浮下，萧然木石亲。","扶桑东不远，勾漏亦为邻。","学道炼金骨，三山期问津。","岁星耻被谪，强之观国宾。","矫矫野鹤性，饮啄惭向人。","一迷红尘眼，五别青萝春。","缑山倘相接，归揖云中君。"]},{"t":"感遇 其十六","f":"五言古诗","c":["陶令一以醉，柳春不复知。","谁持千日酒，为息百年机。","蛮触国蜗角，流血斗离披。","蚩蚩名利间，所争亦如之。","汉阴有遗老，岁暮可同归。"]},{"t":"感遇 其十七","f":"五言古诗","c":["傲吏坐漆园，悟得逍遥理。","想像南华仙，似假北溟翅。","鶤鹏息六月，天地乃一指。","觉与蝶同蘧，梦随髅共语。","嗟余竟内累，愧彼云中志。","胡不瓠浮江，甘同鸱嚇鼠。","平生大侠骨，岂是折腰具。","拊髀友鸿蒙，据梧齐惠子。","清风入修竹，洒尽诸苦趣。","凉露可濯缨，不借西江水。"]},{"t":"送林坦之垂之兄弟上春官二首 其一","f":"七言律诗","c":["据地酣歌笑四豪，诗情酒态忆吾曹。","坐来夜雨衙斋冷，望去春风马首高。","白眼未清游侠骨，朱弦宁向众人操。","燕台重价需千里，莫问囊中金错刀。"]},{"t":"送林坦之垂之兄弟上春官二首 其二","f":"七言律诗","c":["旅食西风几问津，丈夫行李未全贫。","怀来白壁聊披褐，袖有苍精岂傍人。","痛饮且歌燕市筑，振衣休染洛京尘。","安危异日须吾辈，折得名花不当春。"]},{"t":"秋夕闺怨二首 其一","f":"七言律诗","c":["永夜西风减带围，凉回谁为寄征衣。","楼前泪迸双星落，客子蓬随一叶飞。","袖里有书裁锦字，梦中无路到金微。","平生幸未偷灵药，斜月何心入绛帏。"]},{"t":"秋夕闺怨二首 其二","f":"七言律诗","c":["露浸重帘知夜长，啼残银烛吊寒螀。","坐深错认身为石，愁绝翻惊雨变旸。","鸿雁天边音更杳，蘼芜山下径全荒。","木兰誓欲从军去，不信军中气不扬。"]},{"t":"偕常熟赵明府游惠山秦氏园 其一","f":"五言律诗","c":["禦去风泠泠，长廊次竹亭。","云晴还复湿，泉酌更宜听。","池上论茶谱，林间检鹤经。","几年尘土梦，今日始全醒。"]},{"t":"偕常熟赵明府游惠山秦氏园 其二","f":"五言律诗","c":["山灵邀上客，鸡犬类秦馀。","洞里忘年月，人间笑簿书。","清谈容谷答，梵呗度松虚。","坐对沧波叟，持竿不取鱼。"]},{"t":"静女诗","f":"五言律诗","c":["静女心如水，空闺淡岁华。","晚来惟倚竹，春尽不看花。","芳草连淇上，游人隘若耶。","良媒元有待，耻问宋西家。"]},{"t":"秋思","f":"七言绝句","c":["昨夜西池玉露清，红妆临水若为情。","莫言秋尽芙蓉老，犹可萧萧作雨声。"]},{"t":"观刈示村中父老","f":"七言律诗","c":["田家十月竞场工，杼柚东南幸岁丰。","片片霜镰桑柘外，村村云碓水烟中。","黄鸡紫蟹宜新酒，伐鼓行歌拥醉翁。","寄语吴侬莫狼戾，好将淳俭学豳风。"]},{"t":"江上吟 其一","f":"五言绝句","c":["坐对蒹葭晚，遥悲水国秋。","鱼书长不达，江上怨阳侯。"]},{"t":"江上吟 其二","f":"五言绝句","c":["宝雁带星霜，南来关塞长。","杜兰零落甚，客意属沅湘。"]},{"t":"江上吟 其三","f":"五言绝句","c":["南天云水阔，秋望杳无端。","谁道新霜冷，能烧枫树丹。"]},{"t":"孙建侯邀饮观韩湘子传奇席上赋时","f":"七言律诗","c":["啸有孙登响凤鸾，更携秋色入琼筵。","歌回暗觉梁尘起，星聚应占剑气连。","风急黄花催短鬓，夜长青女下遥天。","挥杯莫讶逡巡酒，葛令元来号稚川。"]},{"t":"夜","f":"五言绝句","c":["锁印远钟歇，钩帘新月起。","欲知吏隐心，铜瓶贮清水。"]},{"t":"九日孙建侯贻诗讯余病兼约登高赋此之二首 其一","f":"五言律诗","c":["久宦逢秋懒，多愁与病兼。","高斋闻捣药，半月食无盐。","忍负龙山会，因耽鹤萝恬。","新诗如七发，傲骨若为砭。"]},{"t":"九日孙建侯贻诗讯余病兼约登高赋此之二首 其二","f":"五言律诗","c":["宿业应难忏，禅宗试一参。","舄传飞阙北，人尚滞周南。","吾破三生界，方知七不堪。","东篱聊徙倚，犹忆菊花潭。"]},{"t":"避署小憩","f":"五言律诗","c":["沐发西园里，闲持贝叶书。","地幽能却扇，心远似悬车。","赤日焰偏赫，高云迥自如。","回溪饶美竹，风至忆吾庐。"]},{"t":"除夕二首 其一","f":"五言律诗","c":["今夕是何夕，开尊不厌频。","乾坤翻阅世，儿女暗催人。","守岁更声尽，迎年乐事新。","谁持树柏酒，一寄岭梅春。"]},{"t":"除夕二首 其二","f":"五言律诗","c":["黯黯灯前语，愁来发浩歌。","河清不待我，日落几挥戈。","任路嗟薪积，劳生信隙过。","丹砂灵洞閟，归思绕云萝。"]},{"t":"寒食虎丘","f":"五言律诗","c":["正喜宦无能，春山试一登。","野村皆禁火，此地独传灯。","空谷闻幽鸟，流云傍定僧。","晚归休待月，人已踏金绳。"]},{"t":"雨后上方寺","f":"五言律诗","c":["客驾长虹至，龙归古洞春。","山门新霁雨，石路净纤尘。","得句先呈佛，长歌不属人。","所嗟山下径，来往入迷津。"]},{"t":"人有饷余潇湘八景画册者退食之暇逐景分题空同子先有此作余其为妇乎加七言以别之 其一 渔村夕照","f":"七言绝句","c":["晒网柴门返照新，桃花流水认前津。","买鱼沽酒湘江去，远吊怀沙作赋人。"]},{"t":"人有饷余潇湘八景画册者退食之暇逐景分题空同子先有此作余其为妇乎加七言以别之 其二 山寺晚钟","f":"七言绝句","c":["绝顶高僧未易逢，禅床长被白云封。","残钟已罢寥天远，锡杖时过紫盖峰。"]},{"t":"人有饷余潇湘八景画册者退食之暇逐景分题空同子先有此作余其为妇乎加七言以别之 其三 平沙落雁","f":"七言绝句","c":["阵断衡阳暂此回，沙明水碧岸莓苔。","相呼正喜无缯缴，又被孤城画角催。"]},{"t":"人有饷余潇湘八景画册者退食之暇逐景分题空同子先有此作余其为妇乎加七言以别之 其四 江天暮雪","f":"七言绝句","c":["蓑笠无踪失钓船，同云黯淡混江天。","湘妃独对君山老，镜里修眉已皓然。"]},{"t":"人有饷余潇湘八景画册者退食之暇逐景分题空同子先有此作余其为妇乎加七言以别之 其五 潇湘夜雨","f":"七言绝句","c":["大王长啸起雄风，又逐行云入梦中。","想像阳台环佩湿，令人肠断楚天东。"]},{"t":"人有饷余潇湘八景画册者退食之暇逐景分题空同子先有此作余其为妇乎加七言以别之 其六 洞庭秋月","f":"七言绝句","c":["李白曾称月下仙，烟波秋醉洞庭船。","我来更欲骑黄鹤，直向高楼一醉眠。"]},{"t":"人有饷余潇湘八景画册者退食之暇逐景分题空同子先有此作余其为妇乎加七言以别之 其七 远浦归帆","f":"七言绝句","c":["汉江游女石榴裙，一道菱歌两岸闻。","估客归帆休怅望，闺中红粉正思君。"]},{"t":"人有饷余潇湘八景画册者退食之暇逐景分题空同子先有此作余其为妇乎加七言以别之 其八 山市晴岚","f":"七言绝句","c":["乱峰空翠晴还湿，山市岚昏近觉遥。","正值微寒堪索醉，酒旗从此不须招。"]},{"t":"为刘恒甫年兄悼亡","f":"七言律诗","c":["客子悲秋已惘然，那堪更著悼亡篇。","独怜窃药人犹在，颇恨鸿都术未传。","归梦夜悬巫峡雨，孤鸿声断太湖天。","素琴已悟无弦意，慢取鸾胶与续弦。"]},{"t":"为张孟奇悼亡","f":"七言律诗","c":["怜君犹在四愁中，泪浇新秋一叶风。","神女云妆珠佩寂，画眉人老锦屏空。","鹊分金镜桥先断，星隔银河水未通。","谁解招魂如宋玉，江南哀怨结青枫。"]},{"t":"赠樊山明府以父病解官归黄州","f":"七言律诗","c":["强项从来说董宣，王阳回驭更称贤。","轻舟独载惟卷石，遮道犹闻却一钱。","勾漏已馀丹灶药，鲤庭应献紫霞编。","怀人不见衡阳雁，岁晏音书谁与传。"]},{"t":"与周主簿茶会","f":"七言律诗","c":["小隐吴门老岁华，为君弹剑一长嗟。","共传仙尉逢梅福，谁识名驹出渥洼。","秋至任教尘满甑，梦回犹觉笔生花。","年来宦况甘如水，相对同烹顾渚茶。"]},{"t":"九日同吴县曾明府游灵岩望太湖","f":"七言律诗","c":["登台人共鹿麋群，锦石黄花对夕曛。","屐底湖山吴混越，江南风物水连云。","壮游未遂扁舟去，往事徒伤落叶纷。","杼柚雕残非昔日，村砧寥廓不堪闻。"]},{"t":"秋杪同阮坚之年丈集皇甫氏园夜饮","f":"七言律诗","c":["名园水木淡秋容，曲径幽轩紫翠重。","发兴正须搴晚菊，寻盟偏爱对寒松。","青缃旧丛推玄晏，白眼悲歌有嗣宗。","明月留人良夜永，醉归应待景阳钟。"]},{"t":"侍大中丞曹公关武作三首 其一","f":"七言律诗","c":["肃肃百僚瞻独座，翩翩诸将列连营。","胜风暗结鱼丽阵，杀气先传草木兵。","戈拂西山回落日，剑横东海倚长城。","白猿黄石余曾学，慷慨军前欲请缨。"]},{"t":"侍大中丞曹公关武作三首 其二","f":"七言律诗","c":["吹角千群寂不喧，传呼屋瓦尽皆翻。","不观灞上同儿戏，安识条侯将令尊。","气肃金天开组练，烟销铜柱定乾坤。","东南半壁浑无恙，锁钥还应问北门。"]},{"t":"侍大中丞曹公关武作三首 其三","f":"七言律诗","c":["天上文昌居上将，人间武库动兵符。","雷霆风雨谁能料，沧海鲸鲵立可屠。","江石虚闻传八阵，水犀曾见沼三吴。","书生更愿敷文德，归马欣看王会图。"]},{"t":"余课农水乡张钱二山人移花载酒并乐部夜集舟中","f":"七言律诗","c":["载酒荒村二妙来，名花入座对尊开。","江皋暂辟羊求径，暑气先消河朔杯。","棹发鱼龙皆起舞，人闲鸥鹭总忘猜。","当歌未解疮痍恨，为报繁□且莫催。"]},{"t":"题张氏园白乐天遗石","f":"七言律诗","c":["白傅豪吟片石知，风流馀韵使人思。","当年樱柳繁华尽，此日蓬蒿世代疑。","卧处岂无醒酒力，移来犹有野云随。","主人不洒江州泪，对石空歌长庆诗。"]},{"t":"人日对梅花忆江阴明府余才伯年丈","f":"七言律诗","c":["人日晴阴暖半还，寒梅早已破春颜。","陇头消息谁为寄，槛外风花懒独攀。","隔岁暗惊双鬓改，百年能见几人闲。","兴来欲鼓江阴柁，共坐春申邑后山。"]},{"t":"吴趋春五首 其一","f":"五言古诗","c":["步出西城陌，香车满狭斜。","鹿台今日草，娃馆旧时花。","江畔多游女，纷纷学浣纱。"]},{"t":"吴趋春五首 其二","f":"五言古诗","c":["王孙芳草意，士女踏青心。","袜罗隔微波，随风溯玉音。","目成日已暮，惆怅吴江深。"]},{"t":"吴趋春五首 其三","f":"五言古诗","c":["千门细雨中，落花三月节。","春思浩茫茫，不与芳菲歇。","谁言貌似花，莫遣花成雪。"]},{"t":"吴趋春五首 其四","f":"五言古诗","c":["驰道方调马，高楼正品箫。","游缰惜不发，遗响落空寥。","听罢一挥手，骄嘶过板桥。"]},{"t":"吴趋春五首 其五","f":"五言古诗","c":["侵晨挟弹去，薄暮垂鞭归。","堂上歌钟发，迎门换舞衣。","生来豪侠地，不道冶游非。"]},{"t":"闲居七咏孙建侯赋 其一 映雪","f":"五言绝句","c":["开窗临积雪，片玉坠遥天。","鹤氅相辉映，人如姑射仙。"]},{"t":"闲居七咏孙建侯赋 其二 闭户","f":"五言绝句","c":["却扫谢时流，秘书卧常把。","谁知不出户，可以见天下。"]},{"t":"闲居七咏孙建侯赋 其三 枕流","f":"五言绝句","c":["风泉清午梦，高揖颍川人。","冷冷从人耳，欲洗本无尘。"]},{"t":"闲居七咏孙建侯赋 其四 漱石","f":"五言绝句","c":["松□烹白石，绝粒漱云根。","齿敝舌长在，深思老氏言。"]},{"t":"闲居七咏孙建侯赋 其五 长啸","f":"五言绝句","c":["昔读成公赋，曾登阮籍台。","半空闻逸响，疑有凤飞来。"]},{"t":"闲居七咏孙建侯赋 其六 作赋","f":"五言绝句","c":["锦囊行处得，彩笔梦中辉。","赋就金声起，严霜尽倒飞。"]},{"t":"闲居七咏孙建侯赋 其七 酒楼","f":"五言绝句","c":["大江如鸭绿，荡漾对糟丘。","座上客常满，何如孙楚楼。"]},{"t":"赠刘军 其一","f":"七言律诗","c":["马如匹练到吴门，虎橐萧萧蒯缑存。","醉尉岂能知李广，曳裾何处向平原。","途穷转觉诗怀壮，金尽翻令侠骨尊。","世路悠悠君莫问，待逢国士一酬恩。"]},{"t":"赠刘军 其二","f":"七言律诗","c":["结客翩翩赋壮游，逢人肝胆片言投。","狂来且吊要离冢，兴到聊寻范蠡舟。","草檄从军谁跋扈，当歌横槊见风流。","自烧丹灶千年药，不羡黄金万户侯。"]},{"t":"赠刘军 其三","f":"七言律诗","c":["破虏平羌众共看，齐盟风雅更登坛。","酒酣说剑苍龙吼，夜静论诗白雪寒。","锁钥北门诸险尽，鲸鲵东海万家残。","赤松元待功成后，莫向江湖问□冠。"]},{"t":"茂陵二首 其一","f":"七言绝句","c":["王孙玉帐锦流苏，裘马夫君态甚都。","若料黄金能取酒，悔教红袖去当垆。"]},{"t":"茂陵二首 其二","f":"七言绝句","c":["冰弦初断泪痕新，玉轸潜窥别院春。","莫怪茂陵怜异色，文君元是薄情人。"]},{"t":"赋得枫桥流水五绝送孙建侯归金陵 其一","f":"七言绝句","c":["桥头枫叶自青青，客子离歌怅独醒。","夜半钟声出幽寺，依稀犹似昔年听。"]},{"t":"赋得枫桥流水五绝送孙建侯归金陵 其二","f":"七言绝句","c":["流水潺潺日夜闻，当年曾度水犀军。","临流莫话兴亡事，惊起啼乌片片分。"]},{"t":"赋得枫桥流水五绝送孙建侯归金陵 其三","f":"七言绝句","c":["枫响飕飕落暮潮，郎君且驻木兰桡。","桥边车马尘初静，明月新教白玉箫。"]},{"t":"赋得枫桥流水五绝送孙建侯归金陵 其四","f":"七言绝句","c":["浣纱人去冷姑苏，寂寞江枫怨夜乌。","好掬桥边如镜水，凭君西寄莫愁湖。"]},{"t":"赋得枫桥流水五绝送孙建侯归金陵 其五","f":"七言绝句","c":["桃叶渡头花似锦，枫林桥畔月如霜。","他时忽忆兴公赋，两地愁牵一水长。"]},{"t":"诅河豚戏作长句","f":"古风","c":["西施一入吴王宫，宫中粉黛颜无红。","锦帆遥向采香径，十万雄兵集甬东。","古来美色能倾国，更有轻生尝海错。","争誇异味出金盘，不惜捐躯同鼎镬。","君不见西施红粉沉东海，河豚犹号西施乳。","苧萝山上月轮高，越王进色嗤徒劳。","若将此物充吴膳，何异专诸鱼隐刀。"]},{"t":"又诅百舌","f":"楚辞体","c":["君不见蜀帝春魂托杜鹃，辽东有鸟能人言。","枝头百舌凭谁化，应是谗人口业冤。","东方旭日千门晓，花间莺啭闲庭悄。","燕语雕梁最有情，何来怪鸟杂春声。","春闺乍听疑残梦，啾啷咿哑历乱鸣。","轻扬旋转捷，范雎展辩仪。","秦舌险侧间和夷，曲房郑袖兼骊姬。","须臾百韵含宫征，一声悲兮一声喜。","易将白璧变青蝇，可畏歌喉藏虿尾。","自矜叶密可容身，自负枝高听转新。","但觉如簧生处巧，宁知挟弹死为邻。","一朝青皇恩永隔，朱鸟飞来啄其颐。","寂寞无言蒿下飞，寒蝉相对抱深枝。","借问响来调弄好，何如桃李自成蹊。"]},{"t":"仙鹤篇寿伯父慎思翁","f":"七言古诗","c":["青田奇鸟抱明姿，养就胎仙上界飞。","黄金灶畔传丹顶，白玉台边化羽衣。","洞天茫茫三十六，珠树三花几栖宿。","射的方闻取箭还，缑山更度吹笙曲。","群仙冉冉下烟霄，雪氅云缨可待招。","逸态耻随吴市舞，幻形犹傍酒人骄。","竹林老叟通仙术，丹丘紫府开灵笈。","养鹤常同和靖心，步虚已化卢耽骨。","有时跨去入罗浮，东海如环绕十洲。","人世蜉蝣堪一笑，还同龟鹿共千秋。","仙翁紫气连南斗，仙令吴门数回首。","梦入横江归思催，双凫能伴鹤归来。","作歌辽欲寄东语，为进南山酒一杯。"]},{"t":"林坦之夜集","f":"七言律诗","c":["几年踪迹叹沉浮，雪里逢君问敝裘。","傲吏能供千日酒，故人同醉百花洲。","专诸冢上堪谈剑，西子湖边好买舟。","直探吴门山水遍，乘春更作曲江游。"]},{"t":"周昆彦夜集","f":"七言律诗","c":["吴歌子夜劝君欢，秋老黄花尚未残。","别后歧途堪洒泪，到来容鬓各惊看。","微官转觉潘安拙，失意犹怜范叔寒。","词赋长杨谁得似，未应招隐问渔竿。"]},{"t":"闻砧","f":"五言律诗","c":["千门明月里，清响落云端。","谁道繁砧杵，皆经制绮纨。","无衣秋赋急，邻烛夜光残。","寄语琼楼妇，重帘未觉寒。"]},{"t":"题陈母贞烈卷","f":"七言律诗","c":["岁晏孤芳凛自持，柏舟堪俪古人诗。","镜分鸾影彤帏冷，心苦熊丸白发知。","草满青陵飞蛱蝶，水摇班竹映琼枝。","怀清不羡秦王筑，直揭吴山作道碑。"]},{"t":"秋夜怀友","f":"七言律诗","c":["回望寥天片月高，侧身今古忆吾曹。","西楼此夜闻长笛，南国归心折大刀。","搔首断鸿回绝塞，缄书双鲤落秋涛。","河阳漫道栽花好，潘岳于今有二毛。"]},{"t":"岁暮忆京华同籍旧游有感三首 其一","f":"七言律诗","c":["玉河桥畔柳如丝，尚忆鸣珂并马时。","午夜催诗分刻烛，深春赌酒竞弹棋。","青云天上怜高鸟，白眼人间耻皱眉。","试问同朝鸳鸯侣，宫袍零落有谁知。"]},{"t":"岁暮忆京华同籍旧游有感三首 其二","f":"七言律诗","c":["一行作吏在风尘，手板朝朝祗向人。","偶入朱门誇骤贵，何须白首始如新。","要津道上无胶漆，阿堵丛中有鬼神。","傲骨从来倚松石，折腰终未称吾身。"]},{"t":"岁暮忆京华同籍旧游有感三首 其三","f":"七言律诗","c":["江湖岁暮天多风，龙蛇已蛰鸿雁空。","远书屡寄长不达，幽梦失路难为通。","弹冠结绶浪相许，工竽好瑟将无同。","庭前扫雪且煮茗，疏竹影外月出东。"]},{"t":"三月三日","f":"七言律诗","c":["新晴堤柳净年芳，修禊溪边锦绣香。","胜日管弦元上国，冶游风俗自吴王。","江南四姓谁争长，曲水□贤几擅场。","遥望会稽思往事，兰亭霞气晚苍苍。"]},{"t":"同曾淡夫夜集王百谷园亭","f":"七言律诗","c":["柳堤兰径翳青萝，步月虚堂得并过。","客子问奇还载酒，主人长啸更征歌。","吹笙忽下浮丘鹤，挥笔休惊道士鹅。","吏隐今逢白衣宦，岩泉幽兴较谁多。"]},{"t":"钱山人功甫斗室","f":"七言律诗","c":["吴门甲第自连云，斗室萧然见此君。","几隐乌皮无俗客，庭垂绿树有清芬。","荆扉雪满时餐柏，土锉烟□懒卖文。","屈指江南高士传，独怜孤鹤在人群。"]},{"t":"花朝集山人钱简栖宅夜饮王百谷同赋","f":"七言律诗","c":["风袅游丝系玉瓶，花朝卜夜敝云屏。","雄谭清夺吴趋曲，列宿光连处士星。","山简狂来聊寄傲，铜鞮归去醉宜听。","春深修禊期同往，荏苒红尘厌独醒。"]},{"t":"秋夕同阮坚之潘景升泛月胥门江上","f":"七言律诗","c":["出郭清尊散夕阴，蒹葭凫雁自萧森。","德星正聚真人气，明月如窥吏隐心。","对酒雄风舒阮啸，悲秋良夜称潘吟。","仙槎一水堪乘兴，此际扁舟意转深。"]},{"t":"中秋再泛胥江","f":"七言律诗","c":["良宵歌管动千门，得似空江酒一尊。","月绕鹊枝低拂席，水摇鸥梦远浮村。","洞箫瑶瑟非今世，鲈脍蒪丝且对论。","风物江南殊不恶，悠悠作客信乾坤。"]},{"t":"秋声弹剑歌","f":"楚辞体","c":["美人拾得破愁物，中山一饮醉千日。","丈夫气逐秋风高，何事摧残肮脏骨。","搔头不寐揽吾裳，巡檐中夜星琅琅。","斗边紫气摇古狱，腰间老剑啼干将。","此剑手之二十年，千金燕赵未许前。","吹毛雨落惜开匣，铅刀世上何纷然。","长啸倚天聊自宝，破山精力岂草草。","剑兮持汝斩楼兰，漠南庭空刁斗闲。","燕然野碑久剥落，阴山妖血愁斑烂。","剑兮持斩佞臣头，摇天封豕正炰炰。","一夫九首拔大木，当筵未许说庄周。","剑兮持汝向侠客，易水萧萧虹已白。","秋风客散信陵门，夜雨人耕孟尝宅。","徘徊弹剑且高歌，延津龙吼扬雄波。","鬼母秋郊何处哭，猿公竿杪时相过。","起舞拔击盘莲花，星辰夜落乱如麻。","风胡薛烛皆肉眼，倾秦指晋君休誇。","古来神物待知己，吾欲赠之有张华。"]},{"t":"夏日过赵凡夫定山别业 其一","f":"五言律诗","c":["宦海嗟无岸，名山别有春。","遥从栖隐处，再觅姓庞人。","野鸟时窥客，幽花不笑贫。","坐邻支遁宅，今古并劳尘。"]},{"t":"夏日过赵凡夫定山别业 其二","f":"五言律诗","c":["自辟东南境，谁誇十九泉。","四围山作国，一线路通天。","龙性难降俗，猿心入定禅。","石田无陇亩，种药本耕烟。"]},{"t":"夏日过赵凡夫定山别业 其三","f":"五言律诗","c":["元同蒋诩径，浪拟习家池。","鸡犬云中静，藤萝户外垂。","磴荒松自扫，客到鹤先知。","隐映香台上，如闻紫凤吹。"]},{"t":"夏日过赵凡夫定山别业 其四","f":"五言律诗","c":["天池当面卓，仙茗有云芽。","麋鹿随双屐，图书足五车。","论诗疑白社，叩诀秘丹砂。","借问愚公谷，何如此地嘉。"]},{"t":"夏日过赵凡夫定山别业 其五","f":"五言律诗","c":["过雨沾山翠，淙淙万玉流。","重檐飞瀑布，五月可披裘。","返照衔珠阁，残雷度石楼。","坐餐霞气晚，如入赤城游。"]},{"t":"夏日过赵凡夫定山别业 其六","f":"五言律诗","c":["不畏莓苔滑，松阴晚更晴。","举杯酬桂父，拂镜走山精。","对牖莲初吐，前峰天与平。","莫愁归路黑，赵璧向人明。"]},{"t":"夏日过赵凡夫定山别业 其七","f":"五言律诗","c":["清斋忘肉味，断酒见天真。","羡尔伊蒲俎，调从举案人。","山中非索价，庑下实藏珍。","次第征幽事，冥鸿叹此身。"]},{"t":"夏日过赵凡夫定山别业 其八","f":"五言律诗","c":["自寻襄野驾，可息汉阴机。","蹑屐犹虚往，逢君已实归。","泉声如咽别，云气故随衣。","他日投簪绂，相从掩石扉。"]},{"t":"送吴县广文王道锡之马平令六首 其一","f":"五言律诗","c":["官冷名逾重，同推郑广文。","范人金在冶，作赋气淩云。","刃试全牛解，星占列宿分。","脂车须夙驾，人吏待神君。"]},{"t":"送吴县广文王道锡之马平令六首 其二","f":"五言律诗","c":["马平非叶县，仙令即王乔。","好抱阳和去，无忧瘴疠饶。","湘兰秋可佩，桂水晚停桡。","坐见双凫起，相期在紫霄。"]},{"t":"送吴县广文王道锡之马平令六首 其三","f":"五言律诗","c":["策马冲炎塞，开衙对瘴沙。","无田堪种秫，有县岂栽花。","溪洞虽殊俗，车书本一家。","日高惟卧治，蒲挂一鞭斜。"]},{"t":"送吴县广文王道锡之马平令六首 其四","f":"五言律诗","c":["丈夫期报国，不为一微官。","愿学莱芜甑，毋忘苜蓿盘。","征徭诸洞急，矿税几家残。","无限烹鲜意，循良在静安。"]},{"t":"送吴县广文王道锡之马平令六首 其五","f":"五言律诗","c":["柳子留遗庙，颓垣满野蒿。","此行将雨露，亦复继风骚。","墨绶淹丛棘，青云想凤毛。","京华重聚首，马骨羡君高。"]},{"t":"送吴县广文王道锡之马平令六首 其六","f":"五言律诗","c":["登高临象郡，匹练望吴门。","神气存双剑，平生重片言。","有官空岁月，无力正乾坤。","慷慨忧时意，非君孰与论。"]},{"t":"吴门秋月十五首 其一","f":"七言律诗","c":["枫落吴江夜有霜，旅怀何以对秋光。","谁将碧海一轮满，浪拟琼楼七宝装。","奉使未须论博望，游仙还欲学裴航。","曾闻灵药非难□，今夜遥传不死方。"]},{"t":"吴门秋月十五首 其二","f":"七言律诗","c":["秋色平分一镜开，恍疑身世在瑶台。","虚弓倚塞初惊雁，环壁沈池已辨灰。","漫道骊龙方睡稳，忽看神女弄珠来。","夜阑莫负杯中物，明日阴晴未易猜。"]},{"t":"吴门秋月十五首 其三","f":"七言律诗","c":["东海潮生带月高，谁驱雪屋驾银鳌。","人间波浪嗟千顷，镜里山河祗一毫。","幽思未忘秋浦夕，壮心遥寄广陵涛。","那堪节序逢摇落，搔首西风问大刀。"]},{"t":"吴门秋月十五首 其四","f":"七言律诗","c":["桂殿云屏风露侵，广寒应有辟寒金。","怪将灵兔千年杵，散作秋声万户砧。","团扇歌残金屋冷，玉箫吹去凤楼深。","从来人意同天上，碧海青天夜夜心。"]},{"t":"吴门秋月十五首 其五","f":"七言律诗","c":["溟海银潢一脉通，微茫大地入轮空。","何须天柱浮云外，自坐冰壶碧落中。","梦后不知人化鹤，歌回犹觉气成虹。","遥怜缑岭吹笙子，今在蓬莱第几宫。"]},{"t":"吴门秋月十五首 其六","f":"七言律诗","c":["人天遍放白毫光，魍魉妖蟆静自藏。","露泛紫兰偏映酒，云遮红蕊更移床。","楼头人倚今宵笛，雁足书封昨夜霜。","怀土自伤留滞久，愿随流影到吾乡。"]},{"t":"吴门秋月十五首 其七","f":"七言律诗","c":["白纻声悲露满衣，寻源谁复问支机。","霓裳歌舞无消息，蓬海桑沧有是非。","河转漂星皆北向，风高惊鹊尽南飞。","秋来若忆罗浮侣，翘首天边指少微。"]},{"t":"吴门秋月十五首 其八","f":"七言律诗","c":["琼宫高卷紫霞绡，冉冉诸仙降节朝。","星佩声摇双凤曲，云车香度六龙镳。","银河似隔天孙语，瑶瑟谁将帝女招。","更忆乘流过采石，骑鲸无处问归潮。"]},{"t":"吴门秋月十五首 其九","f":"七言律诗","c":["几度悲欢叹缺圆，镜台相对两婵娟。","同衾正喜金风爽，捣练空伤玉箸悬。","歌动昭阳灯似昼，漏残长信夜如年。","秋期三五休相误，青鸟多情为寄笺。"]},{"t":"吴门秋月十五首 其十","f":"七言律诗","c":["月转西廊夜渐幽，坐深河汉傍人流。","狂飙偏逐桓伊笛，皓魄先侵庾亮楼。","光射潜虬号远浦，响回嫠妇泣孤舟。","寒深忽念无衣子，懒向秋窗理敝裘。"]},{"t":"吴门秋月十五首 其十一","f":"七言律诗","c":["空闺蟋蟀应鸣机，泪满流黄忆授衣。","晕绕白登围正合，轮圆青海马初肥。","徵兵处处防秋急，插羽年年报捷稀。","寄语卢家新少妇，玉关能得几人归。"]},{"t":"吴门秋月十五首 其十二","f":"七言律诗","c":["帘下吹灰倒入霜，谩劳仙术试淮王。","可怜青女云鬓湿，坐对黄花客鬓苍。","词赋千年誇赤壁，琵琶终夕怨浔阳。","参横未肯停缃管，犹忆前身是谢庄。"]},{"t":"吴门秋月十五首 其十三","f":"七言律诗","c":["午夜歌钟彻晓闻，姑苏弦管岁时新。","重帘不畏三秋冷，一笑能回四座春。","娃馆尚留吴苑月，冰轮曾伫梦里人。","太湖万顷金波阔，欲驾扁舟再问津。"]},{"t":"吴门秋月十五首 其十四","f":"七言律诗","c":["坐来疏漏已三更，屈指流光百感生。","五斗微名虚寄迹，千秋吾道竟何成。","升沈总付当空鉴，放浪如游不夜城。","谁识闲心同白月，踏歌羞逐众人行。"]},{"t":"吴门秋月十五首 其十五","f":"七言律诗","c":["秋至缄书付鹡鸰，犹怜风木冷虚庭。","关山迢递多离合，岐路艰危任醉醒。","且把茱萸浮绿蚁，更弹莲锷倚青萍。","谁言星月遥相妒，此夜还须让酒星。"]},{"t":"赠高影逸","f":"七言律诗","c":["大隐吴门吏亦仙，丈夫宁受俗人怜。","玄经有待期知己，白壁无因孰至前。","阅世淡交情似水，看君得趣意忘弦。","汉家元礼谁堪禦，怅望清光北斗边。"]},{"t":"西湖排律三十一韵","f":"五言古诗","c":["名湖天水阔，游客驭双凫。","出郭纷弦管，登舟俨画图。","湖山无俗吏，文物果仙都。","楼台云外出，鱼鸟镜中趋。","白波披縠练，红蓼湛珊瑚。","青雀兰为楫，黄头锦作襦。","列羞皆海错，奏曲半□吴。","缥缈十洲近，微茫三岛孤。","棹歌催掷雉，鸟语劝提壶。","烟景浓疑淡，岚光有乍无。","西施宁比丽，苏小亦名姝。","放鹤波逾迥，攀梅萼未敷。","柳堤张帐幕，花岸簇氍毹。","芳杜闲堪采，轻鸥狎可呼。","莲筒初泻酒，蒪菜适逢鲈。","妙舞盘氍毹，新声唱鹧鸪。","菱舟喧妓女，翠袖映菇蒲。","洛浦看留佩，阳台欲解繻。","情同开合蕊，惯宿去来乌。","晚眺吐山月，还如照夜珠。","琉璃浮万顷，金碧晃千区。","鲛室冰绡灿，蜃楼彩幄殊。","冯夷来击鼓，龙女出吹竽。","佳丽风方盛，英雄世与徂。","金舆嗟暗徙，铁马想长驱。","坐对岳坟泣，因悲宋殿芜。","山川非异境，兴废岂同涂。","吊古余双泪，匡时耻一株。","笙歌虽扑地，豺虎正交衢。","泽国动摇易，长城俊杰须。","莫随游冶子，饱食类侏儒。"]},{"t":"专诸墓仄调排律十二韵将","f":"七言古诗","c":["椒浆一奠吴门豪，感恩捐命如鸿毛。","荒坟惨惨依古郭，白杨萧萧满黄蒿。","不知千年碧血化，犹闻昔日苍鹰高。","地下风雷缠侠骨，天边星斗盘鱼刀。","游魂夜过朱亥里，浩气秋壮伍胥涛。","舞阳死灰笑怯懦，要离燔子无勋劳。","吊君应击铅中筑，挥涕合赋湘流骚。","辽东仙鹤久寂莫，江南杜鹃长叫号。","黄金结客觅死士，赤胆若辈真吾曹。","吴下少年无意气，阊门竟日空游遨。","肥肉大酒浪相集，探丸喋血纷先逃。","可勒哀些表抔土，丰碑百尺为君褒。"]},{"t":"聚星行","f":"七言古诗","c":["主人已解青铜章，召客邀欢夜未央。","文星炯炯当空长，清淡辉映玉琅琅。","词人者谁钱与王，曹生角敌能擅场。","横飞彩笔森开张，雅歌方罗杂伎将。","俳优小伫列成行，妙舞法曲梁尘扬。","泠泠天籁中清商，何必蛾眉出洞房。","有酒如蝇琥珀光，更看鸭绿类鹅黄。","蒪丝鲈脍佐飞觞，百壶万斛谁禁当。","鲸吞灵擘乐且康，况兹携手限河梁。","酒徒遥忆旧高阳，离怀应以醉为乡。","嗟余作令六载忙，攒眉折腰贵人傍。","谁云单父不下堂，戴星空自惭踉跄。","今夕何夕华灯煌，一洗尘梦付黄粱。","仰面长歌问彼苍，肯容豪客发清狂。","便当散发游扶桑，上朝三十六玉皇，下笑金母鬓如霜。","谁能局趣待含香，更筹边障事戎羌。","古来佳兵戒不祥，荒服不至归白狼。","万年王道本金汤，玉门长辟甲士藏。","欲进此策排天阊，圣人垂拱寿无疆。","徐征墨客侍御床，来仪威凤鸣高冈。","劝君聊暂依东墙，会见鹤书出上方。"]},{"t":"初发舟二首 其一","f":"五言律诗","c":["祖帐群贤并，三杯起棹讴。","六年淹茂苑，他日忆并州。","童稚应相候，田园已梦游。","不知猿鹤意，肯与隔年留。"]},{"t":"初发舟二首 其二","f":"五言律诗","c":["暂奉潘舆乐，宁违汉署香。","行舟狎渔父，濯足爱沧浪。","旧事吴门远，归心粤峤长。","独怜衙宇寂，东壁冷胡床。"]},{"t":"别惠山","f":"五言律诗","c":["天池真若友，新茗试春泉。","山客和云汲，衙斋带月煎。","松风虚飒尔，宦况与泠然。","此别重回首，清声入梦边。"]},{"t":"金焦","f":"五言律诗","c":["金焦郁相望，佳气晓森森。","烟水开天镜，鱼龙识梵音。","垂纶任氏意，鼓楫谢公心。","悟得忘机理，鸥盟尚可寻。"]},{"t":"仪真阻风","f":"五言律诗","c":["客行贪利涉，旅泊阻风潮。","月苦更含晕，星稀祗乱摇。","邮签江路杳，乡思海天遥。","不及南飞鹊，迎风雨自骄。"]},{"t":"燕子矶","f":"七言古诗","c":["布帆破浪疾如矢，逆十盘涡旋且止。","燕子矶头石林立，水势建瓴走千里。","怪石齿齿斜衔舟，老鼋含呷柁师愁。","百篙挺折不得力，一缆岂合牵奔流。","风号涛怒如交战，层崖观者皆色变。","危樯欹侧不可支，同舟众命悬轻线。","谁将鈇索置崖间，挽索齐呼济险艰。","错探骊龙离虎口，愁胡冷面开春颜。","人言滟滪大如襆，五月瞿塘不可触。","燕矶之险胜瞿塘，静想可为三日哭。","垂堂遗训慎风波，世路风波今更多。","吴门回首浑如梦，且向清尊一醉歌。"]},{"t":"有所思","f":"五言律诗","c":["浮云西北驰，逝水东南去。","有客正伤离，佳人在何处。","烟消江练阔，湛湛青枫树。","日暮眇愁予，疏钟度微雨。"]},{"t":"睡","f":"七言律诗","c":["石枕绳床午梦闲，簿书迎送不相关。","簟纹净滑摇湘水，炉气氤氲起博山。","六载劳薪翻自哂，百年倦鸟亦知还。","夷犹孤棹便疏懒，岂合追随玉笋班。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其一 相逢行","f":"古风","c":["客从东北来，皮裘类燕朔。","紫髯环碧眼，英风何磊落。","笑出吴钩光照人，更怀七首欲投秦。","相逢下马饮君酒，跪赠平生一片心。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其二 结袜子","f":"七言律诗","c":["寒江一清深见底，壮士肝肠照秋水。","隐隐风雷起铁锤，萧萧杀气横千里。","感德轻将身命酬，抱关屠者更何求。","一言不合辄投袂，说甚千金不掉头。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其三 缓歌行","f":"七言古诗","c":["长绳系日日渐移，大药不就朱颜非。","问君何事常羁眉，丈夫堕地当雄飞。","乌鸢嚇鼠浪自喜，众鸟羡之凤皇耻。","蓬山元是巨鳌簪，我欲从之东海深。","六载坭涂衣可浣，秋园松菊尚知心。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其四 陇头吟","f":"古风","c":["磨刀呜咽水，肝肠如中刀。","回头语徒侣，脉脉不得语。","双眼迸泪同泉流，风悲鬼啸声啾啾。","遥望秦川烟雾里，悔拚战骨觅封侯。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其五 战城南","f":"七言律诗","c":["城南荒地今耕破，遗镞半锈骨交卧。","借问何年此溃兵，野老无声泪潜堕。","怨气凄凄结黑云，城头吹角不堪闻。","城南寥落无人迹，犹听城中新募军。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其六 舞衣曲","f":"七言古诗","c":["游丝百丈袅春天，新机漠漠看如烟。","织成霞锦天孙妒，剪破云衣玉女怜。","纤飞蝶粉轻蝉翼，柳腰试著娇无力。","出房垂手初入拍，洛水湘波隔罗袜。","回节身随急管声，半空摇曳游龙惊。","飘风飞雪浑无态，燕懒莺慵叵柰情。","佳人者谁石城女，惯向上宾呈楚舞。","举袖春生鸲鹆姿，敛眸汗湿阳台雨。","绝缨豪客散兰堂，金鈪沉沉夜漏长。","可叹倾城犹逐队，不随秦帝卷衣裳。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其七 白词","f":"七言古诗","c":["交州剪刀裁匹练，掌上飞来如白燕。","苔色秋深长信宫，歌声夜绕昭阳殿。","珠错华灯列万星，玉床半醉倚娉婷。","舞回似恨秋衿薄，侍寝琼房晓未醒。","铜龙咽咽天河水，牛女佳期岁如此，席敝铅销勿轻弃。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其八 宛转词","f":"七言绝句","c":["独独漉漉辘轳声，札札戛戛机杼鸣。","咄咄恻恻离人情，惨惨淡淡天难明。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其九 蜀国弦","f":"古风","c":["蜀道鸟难飞，蜀中人未归。","垆头花似女，江水锦为衣。","潇潇急雨来巫峡，苦竹秋声怨行客。","几回梦里听猿啼，不觉朝来头尽白。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其十 霹雳引","f":"古风","c":["愁人苦病暍，炎峤只闻雷。","渴想阴宫餐积雪，狂思散发临高台。","南来有客抱琴至，泠泠色挟清商气。","调轸林生少女风，扣弦指下奔丰隆。","镗鎝砰駖声震野，疾可破山缓堕瓦。","四座横飞赤电光，堂坳潦涨恨无梁。","火龙抑首下西陆，风雨潇潇一榻凉。","罢琴云气犹缠指，壮士闻之按剑起。","直当叱咤驰千里，翻身暍病霍然已。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其十一 邯郸少年行","f":"七言古诗","c":["邯郸才人善歌舞，门前车马纷如雨。","城南年少游侠儿，赠锦缠头不知数。","坐来意气自豪雄，剑文秋水湛芙蓉。","珊瑚不避铁如意，腰䮍半啮金盘龙。","酒酣拔剑起相视，报仇结客城南市。","杀人十步不留行，居间椒房偏赦死。","五侯七贵竞繁华，侠骨犹怜貌似花。","归去香风吹满路，路傍掷果尚盈车。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 芳树二首 其十二","f":"古风","c":["忆妾初归日，芳树齐蛾眉。","如何三两岁，已长拂檐枝。","春风初入洛阳道，芳树含花笑春早。","夫婿朝回千骑喧，玳筵召客满西园。","红衫半拭朱弦柱，青菜新传白玉盆。","翩翩蜂蝶闲来往，投辖呼卢恣欢赏。","共道筵前日未斜，谁知树底已飞花。","花飞乱落清池里，明镜容华宛相似。","寄言夫婿晚留春，转眼风光不待人。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其十三","f":"五言古诗","c":["春树沐轻烟，芳菲倚琼阁。","朝日照新彩，转觉花妍灼。","美人谨护持，攀条入珠箔。","墙阴有怨草，怅恨春风薄。","愿回旭日光，一为到葵藿。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其十四 城傍曲","f":"七言律诗","c":["边城健儿好身手，金铃掣马如雷吼。","平原猎去疾于飞，快犬豪鹰皆向后。","鼻尖出火耳生风，狐兔么么不入弓。","却月回身翻射汉，旄头夜落塞垣空。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其十五 乌栖曲","f":"古风","c":["何事城头树，惯栖来去乌。","介楼二八女，邀客独当垆。","乌啼渐缓歌声悄，锦帐春融不知晓。","香风摇曳绣罗衣，笑杀□姑夜上机。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其十六 后乌栖曲","f":"古风","c":["乌哑哑，知返哺。","子从军，母为虏。","空房糠籺久饥妻，独对城乌夜夜啼。","啼残玉箸双流血，飞乌惊去城崩裂。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 襄阳曲二首 其十七","f":"古风","c":["春蚕眠，春蝶举。","紫燕飞来黄鹂语，春深堤上多游女。","过曲桥，逐前侣，踏青拾翠知何许。","大堤之水锦为波，倒映新妆写翠娥。","欲解明前致赠，盈盈罗袜星河。"]},{"t":"舟中无事戏拟古乐府杂体遗意十八首 其十八","f":"古风","c":["襄阳儿，齐拍手。","打鸳鸯，呼鹰狗。","看看欲前翻向后。","眼底迷离不为花，心中长醉非关酒。","自遇临风汉掌轻，归来厌却齐宫丑。"]},{"t":"避暑铜陵留滞二旬暇同黎明府登天王寺乘凉三首 其一","f":"七言律诗","c":["天王台殿俯城隅，江色平开岛屿孤。","金界凉生离火宅，玉山颓处浸冰壶。","诸天转觉成空相，三伏谁能定有无。","最爱琴声清且好，南熏欠去万家苏。"]},{"t":"避暑铜陵留滞二旬暇同黎明府登天王寺乘凉三首 其二","f":"七言律诗","c":["美人为政自忘机，舌底千重尽翠微。","漉酒暂同陶令醉，飞凫终傍子乔归。","参禅已破三生妄，叹世空伤万事非。","笑指大江波浩浩，浮名争似钓鱼矶。"]},{"t":"避暑铜陵留滞二旬暇同黎明府登天王寺乘凉三首 其三","f":"古风","c":["卧病铜官客未还，风林蝄?对江湾。","深杯始信千愁失，数局能消半日闲。","欲礼空王为弟子，更携长策遍名山。","他年解绂谁同往，潇洒如君可共攀。"]},{"t":"铜陵执热书怀十首，时苦旱 其一","f":"五言律诗","c":["悲秋谁作赋，病客反思秋。","赤日高如许，金风不可求。","闻雷空望霈，过雨黯然收。","时著芒鞋去，临江倚竹楼。"]},{"t":"铜陵执热书怀十首，时苦旱 其二","f":"五言律诗","c":["火云连赤阪，永日苦如年。","转恐金成溢，翻忧海变田。","商羊何处舞，阴石更须鞭。","愿得仙公术，端居在冷泉。"]},{"t":"铜陵执热书怀十首，时苦旱 其三","f":"五言律诗","c":["峨眉多积雪，冬夏不曾消。","野鼠甘寒冷，长松荫泬㵳。","科头思绝巘，赤脚望层霄。","缩地安能到，因期白鹤招。"]},{"t":"铜陵执热书怀十首，时苦旱 其四","f":"五言律诗","c":["回思童稚岁，转忆舞雩凉。","散发夏终日，持竿水一方。","长为冠带束，辄苦应酬忙。","内热非关暑，无何有是乡。"]},{"t":"铜陵执热书怀十首，时苦旱 其五","f":"古风","c":["纵有冰纨扇，难消大块炉。","玄霜何日致，肺病几时苏。","河朔须豪饮，肥?立可屠。","铜陵多洞穴，怪不类宜都。"]},{"t":"铜陵执热书怀十首，时苦旱 其六","f":"五言律诗","c":["吴牛犹喘月，阴鸟未呼风。","直苦炎难度，虚疑日再中。","冷然期列子，挥手问鸿蒙。","更有清凉宇，徒思沧海东。"]},{"t":"铜陵执热书怀十首，时苦旱 其七","f":"五言律诗","c":["吾家有丛竹，下映碧潭幽。","过夏疑无午，含风早觉秋。","茶瓜时可禦，童冠日同游。","一别红尘远，星霜已八周。"]},{"t":"铜陵执热书怀十首，时苦旱 其八","f":"五言律诗","c":["铜陵虽执热，犹胜在吴门。","已脱簿书累，而无车马烦。","下帘成小隐，对客祗清言。","悟得逍遥理，凉风满北轩。"]},{"t":"铜陵执热书怀十首，时苦旱 其九","f":"五言律诗","c":["忽忆弹清角，呼儿理素琴。","弦长知调古，夜静觉堂深。","山水千秋意，鸾皇此夜心。","客愁连玉轸，早已变南音。"]},{"t":"铜陵执热书怀十首，时苦旱 其十","f":"五言律诗","c":["新茶烹顾渚，寒簟展湘波。","睡破一床月，清消午夜魔。","暑深秋气近，帘静砌虫多。","节序催乡思，临风发浩歌。"]},{"t":"久旱戏柬黎明府","f":"七言绝句","c":["云拥奇峰暑未残，江焦石烂几时安。","望中雷雨过傍邑，仙令元来是灌坛。"]},{"t":"山城","f":"五言律诗","c":["返照落平芜，山城晚眺孤。","岚光藏雾豹，江影舞樯乌。","远屿涛声壮，层台暑气无。","松楸归思急，不是为莼鲈。"]},{"t":"暑朝","f":"七言绝句","c":["琴书静扫一虚堂，短榻临阶月浸床。","怪底朝来肌骨冷，微风昨夜入清商。"]},{"t":"同黎明府南楼玩月","f":"七言律诗","c":["云物迎秋暑力微，大江高阁对清辉。","光翻贝阙龙初醒，轮度银河鹊欲飞。","渔浦寥寥闻远笛，村砧片片急寒衣。","谁怜王粲伤留滞，作赋荆门尚未归。"]},{"t":"又同黎明府游铜官山二首 其一","f":"五言律诗","c":["美人如玉树，作令得铜官。","望气千峰紫，清谈六月寒。","讼庭多暇日，幽境洽馀欢。","归路澄湖晚，仙城隔水看。"]},{"t":"又同黎明府游铜官山二首 其二","f":"五言律诗","c":["山水元同调，烟霞引兴长。","杯从莲社合，人似竹林狂。","醉倚山公马，衣分荀令香。","独怜离思促，蒹葭欲苍苍。"]},{"t":"别黎明府却寄","f":"七言绝句","c":["棋局壶觞日往还，怜君卧治别来闲。","寄声江上天王岭，何异城头姑射山。"]},{"t":"皖城逢立秋","f":"七言律诗","c":["乡程迢递杳难期，又见江亭一叶飞。","日月不饶孤客鬓，烟霞长护钓鱼矶。","杜蘅远望愁堪结，鸿雁南还喜并归。","欲挽银河洗残暑，夜来凉露湿征衣。"]},{"t":"秋夜鸣榔歌","f":"七言古诗","c":["天上白榆历历光，夜深倒种江中央。","骚人散发歌沧浪，鸣榔一啸雄风长。","河转漂星低可摘，寻源忽忆乘槎客。","挥手高攀织女机，不须更问君平宅。","丹枫红蓼怨秋容，秋思人间几万重。","借问横江徒梦鹤，何如天上跨茅龙。","茅龙缥缈入空飞，云水高寒冷客衣。","自有明霞裁玉女，更将江练剪湘妃。","仙家不羡人间乐，素心一片秋寥廓。","厌听江州商妇弦，还羞河畔看灵鹊。","已知去住本随缘，一任秋江淹旅泊。"]},{"t":"过望江赠袁伯益二首 其一","f":"五言律诗","c":["为忆陈蕃榻，能回叔夜车。","交情千里外，往事十年馀。","暂聚惊分手，凭谁慰索居。","秋江新雁过，莫惜数行书。"]},{"t":"过望江赠袁伯益二首 其二","f":"五言律诗","c":["相逢成一笑，惜别转凄然。","客鬓西风里，离亭落木边。","班荆同此日，结社更何年。","仕路迷津久，相期早著鞭。"]},{"t":"出伏","f":"五言律诗","c":["江行逢出伏，枫叶早知秋。","霞带新鸿去，帆拖片两收。","浮生空复尔，大药竟难求。","莫道金风爽，萧萧起旅愁。"]},{"t":"马当","f":"五言律诗","c":["共讶马当险，行来自觉平。","风波不起处，鹳鹤两和鸣。","柁背吴天杳，帆冲楚塞晴。","遥听崖叶堕，淅淅助秋声。"]},{"t":"小姑二首 其一","f":"五言律诗","c":["过雨延新爽，秋江正耐看。","小姑初沐罢，一镜晓妆残。","霞佩摇空翠，云衣怯早寒。","淩波朝复暮，独立尔应难。"]},{"t":"小姑二首 其二","f":"五言律诗","c":["化石照江心，空山若有人。","帘栊收宿雨，罗袜不生尘。","青鸟频通信，蓬山几问津。","寄言作赋客，休拟楚台神。"]},{"t":"湖口逢故人之蜀","f":"七言律诗","c":["江湖落魄竟何如，昔别十年无尺书。","苍龙袖里涩古色，碧草岭外怨离居。","停舟把臂回白眼，秉烛酌酒脍神鱼。","明朝解缆各南北，看月峨眉一望予。"]},{"t":"浔阳江闻笛","f":"七言律诗","c":["西风瑟瑟吹寒莎，野笛如啼又似歌。","砍竹定遇武昌老，抆泪尚咽湘江蛾。","鱼龙欲睡移深浦，鸿雁惊飞掠远波。","试问当年白司马，琵琶幽怨较谁多。"]},{"t":"望匡庐戏作五老歌","f":"古风","c":["天边五老匡庐友，冥冥呼吸通南斗。","掀髯箕星忽箕扬，长风吹落彭湖傍。","湖上落星石，箕星化下□。","群仙诉帝帝不怒，犹遣白龙驱瀑布。","飞流一洗南箕羞，更与老人清杖屦。","锦屏之下置香炉，俨若仙家祝寿图。","为问泰山丈人石，近时书信有耶无。"]},{"t":"鄱湖七夕","f":"七言古诗","c":["箕星好风喧上都，帝呵一夕谪鄱湖。","谪来骄蹇犹狂粗，横鞭屏翳驱天吴。","浪头高蹴银河水，乌鹊成桥忽倾圯。","织女妆残愁不理，支机有石自难支。","巧既莫施将乞谁，脉脉洪波徒尔为。","西方月蛾窥冷笑，玉蟾香桂森相照，风波不到琼房悄。"]},{"t":"南昌即事","f":"七言律诗","c":["江湖襟带洪都郡，食鼎鸣钟几万家。","彭蠡涛声摇铁柱，匡庐晴色映龙沙。","云霞楼阁今犹壮，宾主东南昔共誇。","遥望丰城知不远，更携雄剑问张华。"]},{"t":"续梦","f":"五言律诗","c":["旅榜依牛渚，清风满葛巾。","澄江空对月，咏史更何人。","酹酒唁狂客，燃犀辟水神。","名高前后事，同是梦中身。"]},{"t":"江上行三十首 其一","f":"五言绝句","c":["断虹呼飓母，津吏笑相迎。","且慎风涛险，维舟缓去程。"]},{"t":"江上行三十首 其二","f":"五言绝句","c":["挂帆鸣越榜，击汰奏吴歌。","休讶江行险，人间孰不波。"]},{"t":"江上行三十首 其三","f":"五言绝句","c":["寒潮销铁锁，浪打石头城。","莫问隋堤柳，徒伤远客情。"]},{"t":"江上行三十首 其四","f":"五言绝句","c":["江白郎如练，江青好染衣。","不须施粉黛，隔浦见湘妃。"]},{"t":"江上行三十首 其五","f":"五言绝句","c":["夜静客帆稀，渔舟尚未归。","问君何泛泛，浮宅本无依。"]},{"t":"江上行三十首 其六","f":"五言绝句","c":["罗袖倚青荷，新妆映碧波。","声从香里度，知是采莲歌。"]},{"t":"江上行三十首 其七","f":"五言绝句","c":["最爱曲无毒，偏怜蟹有螯。","舟中无所事，痛饮读离骚。"]},{"t":"江上行三十首 其八","f":"五言绝句","c":["孤棹迎风退，鹢人何日归。","船头虽画鹢，犹作宋都飞。"]},{"t":"江上行三十首 其九","f":"五言绝句","c":["万树带鸣蝉，秋思满暮天。","东流无尽日，不与驻华年。"]},{"t":"江上行三十首 其十","f":"五言绝句","c":["停桡惜余景，晚泊烟波静。","颇怪行汲者，动摇山水影。"]},{"t":"江上行三十首 其十一","f":"五言绝句","c":["一带江村好，柴门水竹居。","主人招海鸟，僮仆厌溪鱼。"]},{"t":"江上行三十首 其十二","f":"五言绝句","c":["江上闻长笛，能吹出塞声。","衰杨秋折尽，孤客若为情。"]},{"t":"江上行三十首 其十三","f":"五言绝句","c":["月落西风急，秋萤点点流。","却疑江上女，半夜弄珠游。"]},{"t":"江上行三十首 其十四","f":"五言绝句","c":["擘破双莲子，冰肌抱苦心。","搴芳何限意，肠断为知音。"]},{"t":"江上行三十首 其十五","f":"五言绝句","c":["舟楫几时闲，乘潮日往还。","欲知潮尽处，咫尺是蓬山。"]},{"t":"江上行三十首 其十六","f":"五言绝句","c":["连日江云暗，今朝眼倍明。","酒徒非爱酒，倩作斩愁兵。"]},{"t":"江上行三十首 其十七","f":"五言绝句","c":["宿桨依村落，颇闻农者言。","秋檐鸡黍熟，真乐在田园。"]},{"t":"江上行三十首 其十八","f":"五言绝句","c":["江上逢渔父，今时几逐臣。","遥传一掬泪，为我吊灵均。"]},{"t":"江上行三十首 其十九","f":"五言绝句","c":["隔船弦索响，人说到江州。","司马当年泪，犹分九派流。"]},{"t":"江上行三十首 其二十","f":"五言绝句","c":["彭蠡雨霏霏，匡庐隐翠微。","不知瀑布落，错认白龙飞。"]},{"t":"江上行三十首 其二十一","f":"五言绝句","c":["片雨过孤村，晚溪晴洗马。","复有如花人，浣纱明月下。"]},{"t":"江上行三十首 其二十二","f":"五言绝句","c":["浦溆人家少，柴门白屋贫。","年来增矿税，多作异乡人。"]},{"t":"江上行三十首 其二十三","f":"五言绝句","c":["野村无犬吠，夜哭绕秋云。","处处诛求尽，哀声不可闻。"]},{"t":"江上行三十首 其二十四","f":"五言绝句","c":["秋裳堪制芰，午醉亦餔糟。","孰识乾坤意，往来半反骚。"]},{"t":"江上行三十首 其二十五","f":"五言绝句","c":["雁回应蛩吟，萧萧落叶暮。","谁知天籁鸣，尽是秋声赋。"]},{"t":"江上行三十首 其二十六","f":"五言绝句","c":["缥缈顺风舟，玲珑倚岸楼。","思归与望远，两意各悠悠。"]},{"t":"江上行三十首 其二十七","f":"五言绝句","c":["泊滩樵且爨，晚兴倚芳洲。","秋色行看老，芦花已白头。"]},{"t":"江上行三十首 其二十八","f":"五言绝句","c":["夕阳生晚愁，杜蘅秋浦阔。","欲采寄远人，可望不可掇。"]},{"t":"江上行三十首 其二十九","f":"五言绝句","c":["冉冉江上枫，丹青向来变。","不信有炎凉，请看秋后扇。"]},{"t":"江上行三十首 其三十","f":"五言绝句","c":["社近燕怀归，呢喃逐队飞。","能无怜旧垒，故国在乌衣。"]},{"t":"宫词四首 其一","f":"七言律诗","c":["禹甸尧封乐太平，芳年淑气满神京。","璇霄日映龙文合，宝幄兰销瑞雾清。","上苑预催游猎宴，西场初歇打球声。","夜来谁得君王宠，舞马妖鸡尽赐名。"]},{"t":"宫词四首 其二","f":"七言律诗","c":["万国时康赐大酺，六宫仙酒引醍醐。","华清浴后摇红玉，香径人归步锦铺。","南内歌声传晓漏，东方日影散啼乌。","犹闻别院留王母，绛雪玄霜近到无。"]},{"t":"宫词四首 其三","f":"七言律诗","c":["元夕鳌山烂熳游，蹙金奇服异宸旒。","广寒移下随龙仗，玉女飞来集凤楼。","星错华灯迷陆海，风吹仙曲满皇州。","彩云更指维扬路，传诏文成已拜侯。"]},{"t":"宫词四首 其四","f":"七言律诗","c":["玉蝀金鳌别有春，上元遥泛碧桃津。","霞遮龙舸翻成幄，香度琼楼散作尘。","纨扇暗题班氏女，绛帏空忆李夫人。","妆残更学侯门巧，堕马啼眉事事新。"]},{"t":"豫章寄楚中故人","f":"七言绝句","c":["湘水浮云望转迷，离情一片楚天低。","衡阳已恨无来雁，况在衡阳又更西。"]},{"t":"十八滩","f":"五言律诗","c":["危滩十八名，浮客转多惊。","水性岂知险，人心自不平。","垂堂须止足，洗耳喜同清。","更忆吕梁叟，长歌散发行。"]},{"t":"滩上人家","f":"五言律诗","c":["鸟道云生石，人家水绕门。","滩淙时乱听，鸡犬不闻喧。","沙蜮窥渔网，山魈啸猎原。","畏途逢九折，归思逐波翻。"]},{"t":"赣江","f":"五言律诗","c":["章贡分危濑，孤城控合流。","野桥穿虎穴，云碓落龙湫。","地热清砧少，田肥晚稻稠。","山川连楚粤，幕府借持筹。"]},{"t":"度梅关","f":"五言律诗","c":["扰扰嗟行役，风尘老客颜。","车从叱驭度，人是□□还。","鸟道千岩合，羊肠一径攀。","粤天南望尽，云际认乡关。"]},{"t":"梅关道上古松歌","f":"楚辞体","c":["梅关夹道多古松，老龙鳞鬣争摩空。","怪鸟时呼幽壑风，涛声万派山汹汹。","客行八月方病暍，萧瑟对此如寒冬。","苍颜可入韦偃画，行者息肩骑者下。","亭午飕飕竽籁清，太阴黯黯云雷挂。","日轮月驭回高枝，木魅山精避深夜。","君不见泰山顶、徂徕巅，栋梁剥落大夫老，至今芳誉流青编。","何如岭外冲南斗，粤天浩荡开元后。","传闻植自曲江手，嶙峋气节俱不朽。","神明呵护当再拜，仰止高山几回首。","松上悬丝下有苓，花香叶苦通仙灵。","谁能筑室依岩扃，花可酿兮苓可烹。","科头箕踞烟霞里，下看度岭人如蚁。","往来名利空老死，投簪服食果宿诺，我欲从之赤松子。"]},{"t":"英州道中","f":"七言律诗","c":["丹岸锦石映行舟，水碧沙明散旅愁。","几处刈禾依夕浦，谁家吹笛倚江楼。","川回日暖犹含暑，山晚岚昏始觉秋。","久客归心催落叶，榜歌乘月下中流。"]},{"t":"倦客","f":"五言律诗","c":["奚囊无长物，孤剑倚空镡。","已厌宦途恶，方知野兴甘。","入门童稚喜，一径蝶蜂酣。","莫问王程急，山中且结庵。"]},{"t":"展二亲墓","f":"七言律诗","c":["酹酒荒阡草色殷，愁云苦雾结哀颜。","痛将满掬风前泪，洒向他年梦里山。","霜露渐看秋又老，松杉宁有鹤飞还。","栖乌昨夜号寒月，不觉朝来鬓已斑。"]},{"t":"同旧社中诸子集揖仙楼有感畴昔","f":"七言律诗","c":["六载微官叹陆沉，开尊真见故人心。","归来尚有陶潜菊，燕喜惭无陆贾金。","夜雨短檠伤往事，虚堂尘榻对沾襟。","存亡更切山阳感，含笛休教助苦吟。"]},{"t":"扫旧日山房","f":"七言律诗","c":["寂寂幽斋半草莱，北山逋客正归来。","江头渔父休相笑，海上鸥群莫浪猜。","荒径松篁宜晚对，故人鸡黍得重陪。","含香襆被浑闲事，五柳惟知浊酒杯。"]},{"t":"秋日过尹昆璧小瀛洲同周昆彦谭永明林坦之垂之兄弟脍酌得乡字","f":"七言律诗","c":["暑残河朔尚飞觞，暇日招携乐未央。","望去仙居环弱水，坐来人意满沧浪。","丝垂芳饵红鳞出，庖奏銮刀白雪扬。","共道秋江鲈正美，季鹰今已暂还乡。"]},{"t":"秋夜同林坦之垂之元声元韬兄弟周昆彦谭永明曾资铭茅溪泛舟对月赋","f":"七言律诗","c":["月色江光称赏心，水天上下动豪吟。","飞飞乌鹊南来急，黯黯星辰北望深。","狂客残尊堪共卧，羽衣中夜莫相寻。","蒹葭他日仙舟隔，霜露何妨入爽襟。"]},{"t":"辞先墓","f":"七言律诗","c":["草绿平原狐兔骄，墓门松柏冷萧萧。","荣亲不及三牲养，去国空嗟万里遥。","往日皋鱼心更苦，他年寒食泪先飘。","从今归梦知多少，夜夜关山度海潮。"]},{"t":"春夜与社中诸君凤台言别因留赠","f":"七言律诗","c":["把酒高台叹羽翰，侧身天地共凭栏。","到门谁敢题凡鸟，诸子何为尚鹖冠。","楚客狂来歌转逸，玉箫吹去月偏寒。","天涯聚散怜今夕，莫怪千金一刻看。"]},{"t":"别家","f":"五言古诗","c":["忽忽意不乐，客行春尚寒。","仆夫已在门，慈母犹授餐。","长跪缄缝衣，问我何时还。","前途多风水，青衫得无单。","抆泪向母言，此行非苦艰。","丈夫既乘传，宁作敝貂看。","不须母烦忧，但愿母常安。","宦薄虽食贫，菽水聊足欢。","回头顾妻孥，人生聚合难。","明知离别悲，莫破名利关。","他乡久索居，何以慰我颜。","有便常寄书，念我双鬓残。","竭力奉高堂，弄雏以自宽。","征人视芳草，客梦仍故山。","恐伤骨肉意，蓄泪不敢弹。","登车路悠悠，凄恻摧心肝。"]},{"t":"金鳌洲观灯歌","f":"古风","c":["君不见金鳌海上泛神洲，缥缈蓬壶相对浮。","佳气三天来皓鹤，人家两岸映红楼。","东官圆沙古有兆，已见鳌头标石峤。","宝塔能将瑞霭笼，桃津定占春江晓。","谁持玉尺及青鸟，幻出金茎在画图。","集事群工来若子，九仞巍峨此经始。","成梁不籍祖龙鞭，奠磉实环功德水。","万户烟花近上元，溶溶新浪起雷门。","六鳌忽驾三山至，总向洲前劝绿樽。","银灯火树春宵合，蚖脂豹髓纷照灼。","玳瑁筵中醉使君，同游才子气如云。","登龙共是仙舟客，更和青莲五色文。","万艘千舸相鳞次，妙工名讴欢动地。","醉来休问夜何其，但觉钧天异人世。","斗转参移玉漏稀，火城遥送使君归。","留连诸子犹浮白，立望征帆彩鹢飞。","曲江红杏入袍新，鳌禁犹悬隔岁春。","握兰傲吏沽千石，迟尔看花第一人。"]},{"t":"早发庾岭","f":"七言律诗","c":["烟笼星月递微明，晓发愁冲宿瘴行。","人迹暗惊连虎迹，鸡声遥听带樵声。","利名未了残更梦，南北空伤倦客情。","休向关门嗟险绝，行藏吾已任浮生。"]},{"t":"通远驿","f":"七言律诗","c":["驿路烟岚虎豹含，微官真愧远游身。","谁怜三万六千日，半作东西南北人。","芳草故随行客马，啼莺犹似故园春。","门前五柳堪招隐，回首柴桑独怆神。"]},{"t":"登匡庐排律二十韵","f":"五言古诗","c":["半划青天上，平临朱鸟旁。","雄吞彭蠡阔，势压楚云长。","九江纷缭绕，五岳互低昂。","帝座通呼吸，神功接混茫。","星辰分翼轸，宫观自隋唐。","天池春浸月，瀑布昼飞霜。","灵草三花秀，云屏九迭张。","名山天地在，隐士姓名扬。","披画昔神往，扶筇今兴狂。","登临穷绝顶，顾盼尽遐荒。","遥酹五老峰，累举千琼觞。","回头近北斗，抗手揖东皇。","杏林思董奉，丹灶忆旌阳。","仙驭日来游，香炉气飘扬。","吹笙黄鹤下，倚剑赤龙翔。","小憩远公社，因寻李白堂。","白莲全草没，彩笔半苔藏。","感叹千年事，行回九折肠。","浮生如梯米，幻界总沧桑。","愿向山灵道，相传不死方。"]},{"t":"东林寺二首 其一","f":"五言律诗","c":["策马寻精舍，东林非旧师。","池空莲社散，塔坏墓门疑。","地忆羁眉处，桥怜笑度时。","远公犹幻迹，人世总堪悲。"]},{"t":"东林寺二首 其二","f":"五言律诗","c":["教衍三天竺，门当五老峰。","人烟行处僻，幽意坐来重。","篱落闻猿挂，溪沙阅虎踪。","唯余池畔水，一为洗尘容。"]},{"t":"琵琶亭歌","f":"七言古诗","c":["九江之下通杨子，九江上接潇湘水。","湛湛青枫江上愁，春心极目伤千里。","湘北朝霏巫峡云，湘南秋色洞庭分。","白蘋暗结三闾骨，班竹轻摇帝女裙。","湘波迢递长沙眇，逐客千年几相吊。","漫道怀王恶直臣，宁知汉主轻年少。","骚人遗泪落浔阳，司马琵琶更断肠。","哀音似倩江流咽，彩笔长悬日月光。","有客扁舟楚水湄，琵琶亭下重相思。","荻花枫叶长如旧，红袖朱颜又一时。","渡江北望长安路，逐客江南近无数。","零落天涯杳不闻，摧残何异商人妇。","古往今来共寂寥，感时怀古旅魂销。","便欲吹笙骑皓鹤，匡庐五老坐相招。"]},{"t":"早雨杏花","f":"七言律诗","c":["万缕千条羃丽华，非烟非雾带朝霞。","妆成乍传何郎粉，墙角如窥宋玉家。","旭日溟蒙迷镜匣，香魂缥缈隔窗纱。","那堪恼乱春心处，语燕啼鹃又噪鸦。"]},{"t":"旅夜书怀","f":"七言律诗","c":["马首东风弱柳垂，关山迢递杳难期。","谁知游子中宵饭，正是闺人掩泪时。","红豆不须携满袖，江南何处寄相思。","巡檐夜步空庭月，宿鸟双栖自一枝。"]},{"t":"观行取疏目有感","f":"五言律诗","c":["天涯多逐客，阙北又抡材。","共待螭头笔，谁甘溺后灰。","赐环他日事，折槛几人来。","伫望新颁诏，阳和遍九垓。"]},{"t":"王庄驿寄长洲父老 其一","f":"七言律诗","c":["清梦频年到水区，近时圩岸尚存无。","几家茅屋荒村静，一水横塘片月孤。","谁念逃亡新复业，遥闻恩诏已蠲租。","寄言父老勤修筑，莫遣春深长绿芜。"]},{"t":"王庄驿寄长洲父老 其二","f":"七言律诗","c":["六载吴门岁月长，别来今又易星霜。","乱余机杼宁堪税，旱后田畴莫更荒。","千里湖山劳梦寐，百年耆旧问存亡。","谁云宦迹同传舍，回首并州是故乡。"]},{"t":"宿州清明三首 其一","f":"五言律诗","c":["忆昔少年日，芳辰恣浪游。","呼鹰横北郭，走马出长楸。","七贵轻调笑，千金不掉头。","谁怜念载后，郎署尚淹留。"]},{"t":"宿州清明三首 其二","f":"五言律诗","c":["墓田犹宿草，墟里已新烟。","野哭人如此，伤春客泫然。","离魂交舞蝶，洒血染啼鹃。","后岭平山路，微茫落远天。"]},{"t":"宿州清明三首 其三","f":"七言律诗","c":["芳草连天客转迷，清明风日自晴辉。","攀桃簪柳有何意，越鸟燕鸿各异飞。","过眼物华看改火，感时儿女倍沾衣。","劳劳薄宦非吾事，一叹浮生欲息机。"]},{"t":"清明日又忆吴门胜事","f":"七言律诗","c":["吴会春光属虎丘，倾都此日竞春游。","莺花世界吴王苑，箫鼓帘栊范蠡舟。","歌沸剑池催送酒，幕张鹤涧笑藏钩。","别来胜事堪肠断，茅屋荒烟度宿州。"]},{"t":"孟尝君养士处","f":"古风","c":["不知天下士，浪说客三千。","堂中食客已散尽，荒村鸡犬犹依然。","可怜意气今谁见，可惜豪华若飞电。","曲沼高台翳短蒿，遗碑断碣封残藓。","雄风不及朱亥椎，侠气终输鲁连箭。","当年三窟意何深，岂料坟崩狐兔侵。","一曲雍门空洒泪，千秋泉户罢鸣琴。","我行访古长叹息，西照东流浩无极。","于今竟少市义人，休言养士不得力。"]},{"t":"孟庙","f":"五言律诗","c":["瞻拜三迁地，松杉古殿阴。","大刚千古气，仁义七篇心。","王□分自昔，见闻传至今。","宫墙勤仰止，翘首泰山岑。"]},{"t":"渡易水歌","f":"古风","c":["饮马临易水，清波照客心。","平生仗侠骨，谊重轻千金。","匣中剑动苍龙气，化作白虹光烛地。","万古荆轲不死魂，拍手哀歌招复起。","昔日燕图在掌中，宁知草泽无英雄。","逢人争博多目摄，风色萧萧心欲折。","击筑时从市上游，劝君须向酒徒求。"]},{"t":"京华元夕诗 其一","f":"七言律诗","c":["香尘十里骛华轩，新敕金吾放九门。","云外仙游星作佩，殿中春酌斗为樽。","华夷不隔清光远，玉帛来朝胜事繁。","动地欢声喧彻夜，太平何以报君恩。"]},{"t":"京华元夕诗 其二","f":"七言律诗","c":["破虏平羌铁马闲，春风遥度玉门关。","冠绅退食无封事，士女雍容拥佩环。","良夜醉残清漏水，明朝休问紫宸班。","遥知步辇优游处，只在昭阳燕尾间。"]},{"t":"京华元夕诗 其三","f":"七言律诗","c":["大内烟灯起北台，五云缭绕望蓬莱。","芳林不借金刀剪，花胜全因火树栽。","万户羊车争待月，半通羯鼓暗闻雷。","侍臣载笔承明里，谁是清平雅调才。"]},{"t":"京华元夕诗 其四","f":"七言律诗","c":["华月新成七宝妆，纷纷戚畹过平阳。","传筹坐拥三千客，错舄筵开十二行。","梅柳傍檐窥竹叶，鱼龙翻戏入球场。","茫茫陆海今何夕，疑到蓬山不死乡。"]},{"t":"京华元夕诗 其五","f":"七言律诗","c":["击筑悲歌集酒徒，至今燕市重当垆。","休誇长袖弹卢女，已见诸郎匿念奴。","象管声随琼月满，凤箫台隔彩云孤。","相逢莫论新丰价，报导君王欲赐酺。"]},{"t":"京华元夕诗 其六","f":"七言律诗","c":["烟景皇都别有春，珠玑陌上散鲛人。","蚖脂豹髓光如昼，万毕丁谖巧入神。","午夜歌钟连晓漏，半天冰镜暗游尘。","况逢偕计多词客，曲调年来事事新。"]},{"t":"京华元夕诗 其七","f":"七言古诗","c":["铜街金埒紫游缰，蹀躞寻春夜未央。","燕蓟昔称游侠窟，绮罗争擅少年场。","□□□□□□□，□□□□□□□。","谁道千金销一刻，呼卢百万恣豪狂。"]},{"t":"京华元夕诗 其八","f":"七言律诗","c":["董贤夜过小平津，不羡秦官百态新。","花月影重宜子夜，管弦声缓惜芳辰。","绝缨醉后还投辖，骂座狂来任吐茵。","何事鲛冰浑未破，金盘飞脍进银鳞。"]},{"t":"京华元夕诗 其九","f":"七言律诗","c":["绣幕珠帘斗丽华，青牛白马半良家。","无人不掷潘安果，何处堪停卫玠车。","看去传奇非旧曲，行逢解语有新花。","素娥此夕银屏掩，云水苍茫想自嗟。"]},{"t":"京华元夕诗 其十","f":"七言律诗","c":["酒态同推阮步兵，谁论中圣浊和清。","六街金界开黄道，一夜瑶京变赤城。","朋辈连镳堪玩赏，风光转眼几阴晴。","柏浮且尽杯中物，身后休誇百代名。"]},{"t":"京华元夕诗 其十一","f":"七言律诗","c":["纡徐明月夜偏停，对酒高吟怕独醒。","烂漫长干馀堕珥，辉煌复道缀繁星。","落梅秾李随行帐，迭鼓凝笳发从伶。","晋室风流今更盛，清谈谁复数宁馨。"]},{"t":"京华元夕诗 其十二","f":"七言律诗","c":["年芳璧月自重轮，万道金光涌玉津。","仙乐飞来疑佛国，祥光散处识天人。","莲生鸡足流苏暖，灯簇鲸鳞采胜新。","咄咄春游多怪事，九衢偏现洛川神。"]},{"t":"京华元夕诗 其十三","f":"七言律诗","c":["太乙淫祠起汉家，至今灯火兴逾赊。","南油西漆皆腾贵，青玉文螭敢浪誇。","味道吟成尘逐马，江淹赋就笔生花。","太平文物繁都会，不用东京纪梦华。"]},{"t":"京华元夕诗 其十四","f":"七言律诗","c":["酒满金尊月满楼，谁云夜市在杨州。","六鳌似涌神京动，七日如听广乐游。","士女春心飞锦带，儿童闲剧蹴星球。","更阑玉漏斜珠斗，犹见香车若水流。"]},{"t":"京华元夕诗 其十五","f":"七言律诗","c":["少小看灯短鬓侵，老狂元不异童心。","梦归南国烟花迥，恨入东风嶂塞深。","名利登场看傀儡，路歧回首忆云林。","岁星待诏金门久，莫怪酣歌笑陆沉。"]},{"t":"古别离","f":"七言律诗","c":["苍梧云散班竹枯，黄陵庙口啼鹧鸪。","妾家住近洞庭湖，十年夫婿西击胡，衡阳回雁一字无。","金钱卜尽迷生死，妾身愿化随妃子，君归君归自为理。"]},{"t":"古意","f":"七言古诗","c":["宫漏微茫夜深浅，长门弃置如秋扇。","柳幕无风惯锁眉，花房宿露羞啼面。","昨来买赋叹金空，不怨君王怨画工。","赋中凄惋谁能识，图内丹青自可通。","含情欲说防鹦鹉，脉脉伤春向谁诉。","好谢昭阳殿里人，新衣粲粲还当故。"]},{"t":"闲斋对雨","f":"五言古诗","c":["秋雨匝旬馀，苔痕满虚室。","斜风一卷幔，雨气翻萤入。","端居念往事，百感中夜集。","寒蛩伏草根，似与丛兰泣。","点点滴乡心，离人空伫立。"]},{"t":"午日愁坐","f":"七言律诗","c":["芳辰风物倍堪怜，艾叶榴花入眼鲜。","去国王孙空怅望，出郊芳草懒留连。","魂招湘水伤蘅杜，命续朱丝感岁年。","竟日愁来浑未破，高斋真觉酒无权。"]},{"t":"宿禅房","f":"七言绝句","c":["浮云逆旅本空虚，寄宿僧房夜漏徂。","欲识禅心无住处，青莲露叶走明珠。"]},{"t":"汉苑行二首 其一","f":"七言绝句","c":["昨夜春风入未央，竞将新月试涂黄。","自从玉辇看梅去，万户千门尽淡妆。"]},{"t":"汉苑行二首 其二","f":"七言绝句","c":["纷纷红叶落深宫，敢恨恩无日再中。","自是君王稀校猎，非缘贱妾怯当熊。"]},{"t":"忆往日","f":"七言绝句","c":["往事流年恨不同，依然羸马浪西东。","闲来屈指长安陌，一笑浮生是梦中。"]},{"t":"偶忆竞渡有感","f":"七言绝句","c":["箫鼓喧喧兴欲浮，夺标浪底美龙头。","闲观流水心无竞，叹世翻思莲叶舟。"]},{"t":"嘲燕","f":"七言绝句","c":["玳梁绣幕拂轻埃，侍寝昭阳几度回。","莫怪双栖好华屋，前身元是玉钗来。"]},{"t":"瑶瑟怨","f":"七言绝句","c":["明月窥人隔绛绡，楚云湘水两迢迢。","含情欲奏冰弦冷，肠断西风忆玉箫。"]},{"t":"友人边游回二首 其一","f":"七言绝句","c":["瘦苦真同塞草腓，敝衣犹带朔云飞。","李陵台上曾回首，昔日怀归今始归。"]},{"t":"友人边游回二首 其二","f":"七言绝句","c":["怪底风沙老客颜，百年行役几人闲。","不须扼腕封侯事，犹得生还入玉关。"]},{"t":"宫柳","f":"五言律诗","c":["宫坦绕咫尺，天上异人间。","黛拂金塘晓，丝低辇路闲。","深宫春自远，正殿昼长关。","何日沾旗影，千官再侍班。"]},{"t":"祝江西饶太夫人兼颂其诸郎丛桂四首 其一","f":"七言绝句","c":["龙沙旧谶岂空傅，膝下文星总列仙。","不用飞书向南岳，麻姑山水本相连。"]},{"t":"祝江西饶太夫人兼颂其诸郎丛桂四首 其二","f":"七言绝句","c":["桂树琼宫大十围，仙郎频折斗芳菲。","素娥有意供金母，灵药犹教满袖归。"]},{"t":"祝江西饶太夫人兼颂其诸郎丛桂四首 其三","f":"七言绝句","c":["云璈清乐遍人天，小住桃花五百年。","画荻堂前多暇日，殷勤常注紫霞编。"]},{"t":"祝江西饶太夫人兼颂其诸郎丛桂四首 其四","f":"七言绝句","c":["宫袍纷舞彩衣轻，婺突光连百里星。","已羡延年多秘箓，更看世业有韦经。"]},{"t":"流莺","f":"七言律诗","c":["柳幕高张花作茵，宫莺衔出上阳春。","金衣绣色怜公子，锦字机声咽美人。","斗酒双柑听未足，东城南陌韵逾新。","多情已叶笙簧奏，啼夬枝头莫更频。"]},{"t":"题道人房","f":"五言律诗","c":["长廊陷曲房，入院已闻香。","阶下彩云驻，垆头姹女藏。","吹笙遥跨鹤，驱石尽成羊。","何处寻归路，蓬山不死乡。"]},{"t":"雨","f":"五言律诗","c":["好雨濯枝清，天涯尽洗兵。","夭乔看物理，淡荡适予情。","莫问商羊舞，欣听戴胜鸣。","农人得珠玉，万国贺升平。"]},{"t":"春宴三首 其一","f":"五言律诗","c":["长筵罗墨客，佳句答芳菲。","莫怪行觞促，应怜舞片飞。","池亭堪共醉，鱼鸟亦忘机。","明日携馀兴，东郊更典衣。"]},{"t":"春宴三首 其二","f":"五言律诗","c":["酒量角沧溟，谈锋落斗星。","竹林真小饮，河朔未全醒。","鼓为催花急，杯从斗草停。","谁看朱似碧，转觉眼逾青。"]},{"t":"春宴三首 其三","f":"五言律诗","c":["射鸭绿毛散，呼莺锦翅骄。","物情供笑语，身世本逍遥。","丹药何时就，青春未肯饶。","无如醉乡里，暮暮与朝朝。"]},{"t":"闻笛二首 其一","f":"五言律诗","c":["横吹高楼发，月明清露间。","风前怨梅柳，曲里度关山。","陇水声同咽，沙场客未还。","西邻有思妇，坐叹损朱颜。"]},{"t":"闻笛二首 其二","f":"五言律诗","c":["胡床聊一弄，秋思已千重。","萧瑟吟寒叶，微茫韵远钟。","叫云天似水，裂石夜惊龙。","莫奏单于曲，旄头照夕烽。"]},{"t":"送人游吴越二首 其一","f":"五言律诗","c":["送君南骋望，吴越我曾游。","风物时时胜，湖山处处幽。","新声余子夜，往事付春秋。","若问扁舟客，烟波未易求。"]},{"t":"送人游吴越二首 其二","f":"五言律诗","c":["风流推二陆，蕴籍想诸王。","虎阜春犹在，兰亭草未荒。","徘徊南陌女，半学浣纱妆。","客思秋偏好，蒪鲈兴不忘。"]},{"t":"送人入蜀","f":"五言律诗","c":["远客孤舟夜，啼猿度峡时。","阳台自芜没，云雨至今疑。","栈险鬼神泣，城春锦绣披。","峨眉山下月，几度重相思。"]},{"t":"长门怨二首 其一","f":"五言律诗","c":["一种宫中月，愁人独夜看。","光辉流别殿，歌舞未曾阑。","妾妒矜新宠，君恩落旧欢。","素娥青桂里，相对两同寒。"]},{"t":"长门怨二首 其二","f":"五言律诗","c":["昔日黄金屋，秋来遍网丝。","佳人掌上舞，薄命镜中知。","砌冷蛩声急，庭空雁影悲。","白头吟更苦，词客亦相欺。"]},{"t":"灵济宫会饮分韵得天字","f":"五言律诗","c":["松柏深无暑，经堂静法筵。","谈玄壶里趣，浮白酒中仙。","棋罢妨柯烂，诗成有鹤传。","醉归休觅路，人已到罗天。"]},{"t":"暮相思","f":"五言律诗","c":["明月澄兰沼，金波漾水纹。","微微写秋色，朗朗至宵分。","不寐嗔乌鹊，佳期怨碧云。","相思今夕里，木落一鸿闻。"]},{"t":"弹筝女","f":"五言古诗","c":["春风醉客心，二八弹筝女。","十唤不回言，六弦将手语。","高调本西秦，流音翻激楚。","落花天上来，行云无处所。","日暮泛舟归，盈盈隔河渚。"]},{"t":"后庭隙地莳花草毕灌园成趣稍破岑寂","f":"五言律诗","c":["谁言粉署客，更作灌园翁。","入静知生意，抽新见化工。","开窗摇碧色，褰幌引香风。","地僻心偏远，烟霞想像中。"]},{"t":"铜雀妓","f":"五言律诗","c":["玉衣知不举，铜雀若为登。","漳水歌同咽，浮云势共崩。","高枝无挂剑，石椁岂铭滕。","独有台前月，光连汉帝陵。"]},{"t":"蹴鞠行","f":"古风","c":["蹴鞠蹴鞠，落花随轴。","上巳清明，新妆袨服。","醉脱红锦靴，倦入青楼宿。","射堂走马回鸡，一入场日易西。","高足遥过飞鸟上，游丝飘絮却嫌低。"]},{"t":"蟋蟀篇","f":"七言古诗","c":["城南思妇娇无力，蟋蟀环轩促人织。","秋至寒衣空旧箱，夜深冷泪徒沾臆。","闻此虫声意转忙，买丝典却双明珰。","既从邻女求残烛，更向天孙乞七襄。","织才半匹犹未了，床下喓喓似相笑。","借问裁衣寄阿谁，停梭不语自迟迟。","衣成又恐晨炊乏，塞外狂夫那得知。"]},{"t":"送韩孟郁三首 其一","f":"五言律诗","c":["来贵长安纸，归雕季子裘。","豪怀君自豁，高咏孰能酬。","易水风吹马，淮河叶洒舟。","西斋听夜雨，别后倍悲秋。"]},{"t":"送韩孟郁三首 其二","f":"五言律诗","c":["自怜羁客久，几度送人归。","况是同心友，分为断雁飞。","途危孤剑在，天远片帆微。","想到家园日，鲈鱼晚正肥。"]},{"t":"送韩孟郁三首 其三","f":"五言律诗","c":["寥寥千古意，谁与更论文。","别泪悬燕树，离心隔海云。","空囊知有舌，破釜始能军。","行矣君须勉，毋为世故棼。"]},{"t":"婕好怨","f":"七言绝句","c":["纨扇偷开故箧看，秋风落叶鬓同残。","错疑香魄曾奔月，但觉深宫似广寒。"]},{"t":"促织歌","f":"古风","c":["促织复促织，锦纹机上愁无力。","长夜那堪络纬啼，思牵千里肠应直。","皎皎庭前秋月白，月华偏照长城客。","梦去不知能作云，坐来却恐身为石。"]},{"t":"野田黄雀行","f":"古风","c":["唶唶碌碌，舍田而屋。","虽有斗珠，不如掬粟。","群集营营，日暮空城。","催科更急，闻鞭朴声。","引妇呼雏，何田不飞。","既投君家，应怜我饥。","未怜我饥，柘弹在手。","伊我无知，哀此黄口。","遗秉滞穗，回念丰年。","噫嘻，此人无良，环上诉苍天。"]},{"t":"三峡","f":"五言律诗","c":["荆门控三峡，六六见巫山。","往事余林壑，幽情想佩环。","云归无处所，梦去杳难攀。","宋宅同台没，悲秋一怆颜。"]},{"t":"夜坐","f":"五言律诗","c":["夜静群动息，明河低度檐。","香销连暮霭，露重湿寒蟾。","岁觉容华异，名难吏隐兼。","闲情原有寄，看取水中盐。"]},{"t":"莲曲二首 其一","f":"五言绝句","c":["蛾眉迷叶翠，龙脑乱花香。","两岸肠堪断，伊人水一方。"]},{"t":"莲曲二首 其二","f":"五言绝句","c":["湖上雨来急，兰舟并著归。","谁怜花解语，水鸟亦依飞。"]},{"t":"渔父词","f":"古风","c":["澄潭摇绿树，百丈见游鳞。","垂钩新月随孤艇，荷笠闲云伴老身。","春来无限桃花水，懒问仙源碧山里。","鱼肥酒美笑自斟，草暖沙暄常晏起。","休论生计近如何，吹笛鸣榔发棹歌。","大隐不须加帝腹，太平宁用把周戈。","颇怪儿童呼系缆，洲前清浅静无波。"]},{"t":"细雨斋居","f":"五言古诗","c":["边风吹雨来，萧疏满城阙。","高斋一沾洒，叶底蝉声歇。","盆鱼纷唼藻，园卉芽渐茁。","听雨淡幽虑，观物神自悦。","闭门人事少，吏散养吾拙。","烹葵兼烧笋，清供堪一啜。","呼童蓄旨酒，有待期华月。"]},{"t":"晨起","f":"七言律诗","c":["扫地焚香任此身，斋居孤兴在清晨。","参禅已断三生想，漱齿能消五浊尘。","眼底风花随气改，夜来蕉鹿辨谁真。","片云作对晴丝卷，方信虚空不属人。"]},{"t":"观演西施歌舞席上赋","f":"五言律诗","c":["绿酒对芳辰，红妆倚绣茵。","可怜花月夜，再见苧罗人。","大小双垂手，轻盈百媚身。","不知歌舞散，幽意定谁亲。"]},{"t":"观云篇","f":"五言律诗","c":["片云停高空，微风忽相扇。","白衣与苍狗，恍惚须更变。","持将比世情，百态今可见。","谁能决浮云，银汉弄清浅。"]},{"t":"湘妃曲","f":"五言古诗","c":["搴芳徒欲荐，仙佩杳难期。","湘水无情极，行舟唱竹枝。","君山湖上好，清镜映修眉。"]},{"t":"夏朝凉","f":"五言绝句","c":["细雨夜来收，高斋爽气浮。","朝凉疑过夏，远客易惊秋。"]},{"t":"闻黄河又决","f":"七言律诗","c":["驱驰河上泣迷津，亲见冠裳尽负薪。","本谓宣房无穴蚁，岂知河伯又劳人。","铜龙未解蟠堤堰，璧马谁云奠鬼神。","物力东南虚百万，况惊西北报胡尘。"]},{"t":"问张维成病兼邀夜话","f":"七言律诗","c":["交游漫说半中原，十载知心独尔存。","眼底寒暄同逆旅，病中风雨易黄昏。","著书徒益相如渴，罗雀谁过翟氏门。","便可支愁共沉醉，短檠犹足照青尊。"]},{"t":"客子","f":"五言律诗","c":["客子庖厨薄，日来蝇鼠稀。","自知心更远，敢谓俗能违。","上客无回辙，呼童莫掩扉。","宦情今可见，已息汉阴机。"]},{"t":"晴","f":"七言律诗","c":["衣桁熏蒸上绿苔，新晴初报鼓钟催。","当阶穴蚁翻相贺，隔柳流莺怅未回。","缥缈断虹拖过雨，朦胧斜日映轻雷。","久阴顿觉晴光好，花底何辞浊酒杯。"]},{"t":"暑日","f":"五言律诗","c":["褦襶休经过，闲门绿树中。","衣裁南地葛，枕待北窗风。","换水新浇钵，焚香试小童。","浊醪聊一酌，更截碧荷筒。"]},{"t":"暑夜","f":"五言古诗","c":["入夜暑气微，轻云如递浪。","滔滔漾星月，转觉银河涨。","秋期水更阔，牛女亦惆怅。","乌鹊若精卫，危桥将安傍。","余家云海边，万里遥相望。","夜夜归梦劳，杂波涛峦嶂。","一为别鹤吟，僮仆悲自向。","寄语停梭子，人间亦天上。"]},{"t":"紫骝马","f":"五言古诗","c":["人好马亦好，翩翩美少年。","挫金兼喷玉，逐电不劳鞭。","长楸蹀躞去，草色碧如烟。","徒矜呼鹰手，更胜斗鸡钱。","边城烽火急，肯为向幽燕。"]},{"t":"赋得蜀中佳胜赠顾桐柏","f":"七言律诗","c":["蜀川形胜称佳丽，朱夏峨眉带雪明。","水浣鱼笺巴作字，花浓鸟道锦为城。","琴中听曲千重意，梦里行云一片情。","屈指近时词赋客，怜君独擅马卿名。"]},{"t":"燕京早秋","f":"七言律诗","c":["旅食京华且岁时，西风又报入桐枝。","积薪宦况秋逾冷，落叶惊心鬓易丝。","朔气近边闻雁早，岭云临海得书迟。","忧时寄远俱无赖，惆怅新停浊酒卮。"]},{"t":"家报举次子志喜","f":"七言律诗","c":["乡心秋思满瑶京，忽报添丁慰旅情。","岂谓双珠能照乘，且看凡鸟亦和鸣。","劬劳转忆亲恩重，生养欣逢圣世平。","到日祗堪供笑语，傍人休浪拟徐卿。"]},{"t":"妖雹歌","f":"古风","c":["君不见女娲补天今更裂，纷纷白石飞成屑。","共工触倒西域山，纷纷积雪落燕关。","人传涿鹿尤死，岁久游魂招复起。","气结荆轲贯日虹，银甲白袍临易水。","初闻诸怪屯雷风，更闻翻却鲛人宫。","跳珠挟弹奔万马，水天一日消炎夏。","马头鸡子古有之，阳愆阴伏谁所为。","去年坛槐已偃仆，龙神无声老蛟怒。","中原怨气连虎豺，休疑蜴蜥成阴霾。","宋君片语能移灾，但愿皇天斩妖孽，香云甘露开日月。"]},{"t":"秋早口号","f":"五言律诗","c":["看扫盈阶叶，因惊昨夜风。","曙光晞早露，帘影隔残蛩。","潦倒形骸外，羁栖旅病中。","越吟欣得句，不拟作书空。"]},{"t":"送陈秘书还楚","f":"七言律诗","c":["登山临水远将归，木叶萧萧四牡騑。","五两浮湘秋浦阔，三杯把袂故人稀。","秘书夜冷燃藜阁，芳杜晴熏书锦衣。","醉罢楼头跨黄鹤，几时还向帝城飞。"]},{"t":"闲说","f":"七言律诗","c":["沉吟不语向秋云，仰面晴空数雁群。","忽尔叩门来衲子，朗然闲说至宵分。","橘中未辨谁赢局，蜗角曾闻已覆军。","自觉豪华如梦里，不须金偈更排棼。"]},{"t":"秋月吟","f":"五言律诗","c":["长安万古月，偏爱向秋明。","冷逼怜砧急，光浮塞角清。","狂涛翻瀚海，孤照落龙城。","侧想征人意，堪听牧马鸣。"]},{"t":"中秋月食二首 其一","f":"五言律诗","c":["黄衢成黑道，灵兔惑妖蟆。","祗恐琼宫女，随风落别家。","霓裳中夜歇，鼓角万方嗟。","铅粉轻磨镜，清光应更加。"]},{"t":"中秋月食二首 其二","f":"五言律诗","c":["露华澄月色，可爱是中秋。","岂料清光夕，翻成秉烛游。","水轮初掩匣，玉帐乍悬钩。","试问停杯客，何如风雨愁。"]},{"t":"闻陈九吾楚中讣 其一","f":"五言律诗","c":["几年淹薄宦，怜汝在长沙。","赋鵩日斜里，哀湘天一涯。","掀髯看意气，梦笔想才华。","纵化辽东鹤，归来岁月赊。"]},{"t":"闻陈九吾楚中讣 其二","f":"五言律诗","c":["未起双凫舄，先惊白玉棺。","岂虞终客死，翻恨有微官。","素旐秋猿泣，舟枫楚水寒。","诸姬帏帐冷，班竹泪同残。"]},{"t":"闻陈九吾楚中讣 其三","f":"五言律诗","c":["忆昔论文夜，西垣片月高。","形骸非俗态，天地只吾曹。","魂返关山远，船回雁鹜号。","广陵孤调绝，玉轸向谁操。"]},{"t":"九日书怀","f":"五言律诗","c":["怀归心正苦，九日懒登高。","旧恨缠孤剑，新霜入二毛。","松揪悬远梦，岐路念绨袍。","不作悲秋赋，抽毫漫续骚。"]},{"t":"冬至前三日对雪时值圣母万寿与陈裕所同赋禁用雪套","f":"七言律诗","c":["黯黯严寒旅思催，香醪兽炭对衔杯。","慈云偏向蓬莱绕，宝雨遥从佛国来。","六管浮灰将变律，千门残笛暗惊梅。","欲观净土琉璃界，更上西风百尺台。"]},{"t":"至日即事二首 其一","f":"七言律诗","c":["开阁迎长半捲帘，开尊空对水精盐。","天心暗逐微阳转，华发新随一线添。","岁晏龙蛇藏冻浦，雪晴鸦雀下虚檐。","苍茫杀气缠辽左，台上书云莫浪占。"]},{"t":"至日即事二首 其二","f":"七言律诗","c":["江湖霜雪绝飞鸿，迢递乡书杳未通。","万里授衣思履袜，十年羸马叹西东。","闭关行旅萧条后，吹律回春想望中。","谁道省方当息驾，君王元只在深宫。"]},{"t":"送梁书之年丈以大参提兵霸州","f":"七言律诗","c":["纷纷将吏候朱轓，清佩初辞左掖垣。","焚草夜悬霜匣冷，登坛星拥节旄尊。","长城胡马防南牧，圣主宵衣问北门。","锁钥安闲多暇日，好看游骑猎秋原。"]},{"t":"送别同社太史汤嘉宾奉使册封便道省祝两尊人寿","f":"七言律诗","c":["千仞龙门昼不启，论诗对酒眼逾青。","新持汉节虚莲社，喜奉潘舆入鲤庭。","称庆金茎浮瑞露，延年玉札秘仙经。","白云谣后人难和，何日逢君得再听。"]},{"t":"送冯太学还粤","f":"七言律诗","c":["入洛才名众所尊，翩翩清誉满桥门。","朅来自挟风云气，归去谁同水竹村。","漫唱离歌催客子，独怜芳草怨王孙。","送君忽起罗浮思，猿鹤秋山欲断魂。"]},{"t":"午日雨阻郊游同韩孟郁集张孟奇斋头得枝字","f":"七言律诗","c":["踏青郊外负前期，浮白斋头对故知。","燕草断肠还细雨，湘兰无路寄哀词。","辟兵处处闻鼙鼓，绩命年年长鬓丝。","休咏四愁添旅思，越禽偏爱向南枝。"]},{"t":"问讯区用孺谪居滁阳囧寺","f":"七言律诗","c":["谁读遗骚怨谪居，风烟南望眇愁予。","怀人不隔三湘水，经岁难逢尺素书。","世往亭荒空对酒，卧中山色尽环滁。","遥怜苜蓿秋原满，天马歌残意有馀。"]},{"t":"新制冰纱梅花帐张孟奇题额多丽词赋以戏之","f":"七言律诗","c":["帐底梅花度暗香，炎天霜雪午生凉。","初唏短发风敲竹，半卷疏帘月到床。","度岭寄来人更远，罗浮归去梦偏长。","清斋已比寒梅瘦，怪尔新词恼太常。"]},{"t":"夏夜同李伯远张孟奇韩孟郁小斋听雨","f":"七言律诗","c":["蓊郁庭槐待濯枝，虚堂爽气转秋姿。","翻灯洒幕声交响，促漏遥钟夜暗移。","万里羁栖同逆旅，百年怀抱对传卮。","月华合在层阴上，天柱峰头起远思。"]},{"t":"集米仲诏湛园分得松关花径戏作长歌二首 其一 松关","f":"七言古诗","c":["巨灵驱山作平地，徂徕移在名园里。","倒茑垂萝倚牖翻，夜夜波涛聒人耳。","龙鳞马鬃浩呼汹，萧森转觉秋原空。","有时风静横挂月，鹤梦渐醒露华发。","残钟远磬度林迟，坐来谡谡凊肌骨。","换骨求仙待■苓，更携灵笈阅丹经。","叩门恐有赤松子，为报云关且莫扃。"]},{"t":"集米仲诏湛园分得松关花径戏作长歌二首 其二 花径","f":"七言古诗","c":["乘风一夜催春锦，帝女天孙忙不寝。","晓来札札听莺梭，绀紫绯红千万品。","石家步障座中园，香雨霏微乱扑衣。","风枝露芷争相倚，照槛凭轩矜百媚。","曾迷下蔡惑阳城，好倩游蜂作花使。","径底淹留日易西，从来桃李自成溪。","主人已诧花生笔，上客何妨醉似泥。"]},{"t":"张孟奇招同谭汝丽韩孟郁坐月论诗得新字","f":"七言律诗","c":["促膝丛谭玉漏频，虚襟灵籁两鲜新。","河山不碍当空镜，风露偏怜倚桂人。","望去婵娟堪换骨，吸来沆瀣净无尘。","论诗已会泠泠意，舍筏何须更问津。"]},{"t":"立秋日张园荷亭社集三首 其一","f":"七言律诗","c":["名园载酒共夷犹，水木凄清宿雨收。","正对白莲堪结社，俄惊碧树已迎秋。","亭虚玉笛缠风急，夜静银河倒槛流。","遥想海潮乘月满，江南蘅杜动离忧。"]},{"t":"立秋日张园荷亭社集三首 其二","f":"七言律诗","c":["坐久凉生白夹衣，叶翻乌鹊自飞飞。","休誇雨霁蟾偏皎，又恐秋高马正肥。","几处传烽催晓角，谁家罢杵上残机。","年年芳草看摇落，惆账王孙未易归。"]},{"t":"立秋日张园荷亭社集三首 其三","f":"七言律诗","c":["曲入清商调转高，醉乡今已属吾曹。","闲披爽气窥飞镜，懒向西风问大刀。","谈笑幸逢三语据，遨游真愧五陵豪。","当筵共是悲秋客，岂独潘安叹二毛。"]},{"t":"送冯元成公祖提兵高肇道 其一","f":"七言律诗","c":["羊城蓬岛坐相连，冠有神羊识列仙。","北阙才名推十万，南溟风力起三千。","洗兵时雨飞关外，度岭梅花满笛前。","方信词人多胆气，鲸鲵东望静无烟。"]},{"t":"送冯元成公祖提兵高肇道 其二","f":"七言律诗","c":["牙璋朝捧出彤廷，露洒炎方塞草青。","开幕论兵兼课吏，登坛作赋更谈经。","溪边砚美晴摇笔，湖畔岩空倒挂星。","览胜崧台几题品，他年应比岘山亭。"]},{"t":"燕台南望寄见日山人","f":"七言律诗","c":["南极星遥海气阴，有人高卧在云林。","青山合是藏收地，白发难销壮志心。","鸿雁春还无一字，鱼龙秋老几孤吟。","忆君更厌风尘色，梦绕梅花四百岑。"]},{"t":"送张冀度下第还吴门","f":"七言律诗","c":["客泪西风易湿巾，行行何处是通津。","需时玄豹聊藏雾，失意黄花解笑人。","阮籍途穷终任达，马卿游倦岂长贫。","吴门烟月还如旧，别后思君入梦频。"]},{"t":"镜园篇为刘百世赋园傍湖水故名","f":"古风","c":["谁家池馆好乘凉，正忆临流一漱芳。","骑马红尘元市郭，入门绿野变江乡。","江乡乱水侵花径，淡扫明湖开晓镜。","河伯轩窗忽倒翻，鲛人帘户相辉映。","空阔望霏微，盘龙昨夜归。","彩鸾云外舞，金鹊影中飞。","地为玉匣天为盖，雾幌霞绡无粉绘。","宝靥平分杨柳眉，菱花半罥芙蓉带。","一片寒光散夕阴，四规气色自萧森。","夷则会闻沉井底，玄冥今见出江心。","井底与江心，依希通贝阙。","玳瑁高台能□风，珊瑚小架偏横月。","澄明天水两相和，黛敛亭亭洛浦波。","雨过似经神女照，烟消恍被仙人磨。","御沟流出帝城东，知有清辉接魏宫。","已占湖光燕市外，何须敕赐剡川中。","季真风调如之子，水镜先生差可拟。","炯炯虚襟照胆肝，泠泠雅韵无尘滓。","留宾杯酒泛涟漪，风急台高冷浸肌。","座上恐逢苍水使，檐前休挂白龙皮。"]},{"t":"镜园社集得凉字","f":"七言律诗","c":["花外明湖带草堂，泠泠水镜漾清光。","蓬池不乏洪波咏，河朔宜传避暑觞。","人倚高台遥倒影，虹拖片雨送微凉。","兴剩来有搴芳意，处处蘅兰杜若香。"]},{"t":"汤嘉宾太史招同诸名公社集南郊草桥别墅三首 其一","f":"五言古诗","c":["京陌多嚣尘，出郊旷遐瞩。","城南得名园，物物胜韦曲。","阴森水木会，微径连幽竹。","朝光早露晞，百卉如新沐。","浮香四面至，积翠团成屋。","舒啸凭虚槛，心赏惬所欲。","谈回川响答，歌罢莺声续。","客子憺忘归，流觞休太促。"]},{"t":"汤嘉宾太史招同诸名公社集南郊草桥别墅三首 其二","f":"五言古诗","c":["似关江南景，兼葭绕回塘。","怅望停觞处，仙□水一方。","鱼鸟来亲人，濠上坐蒙庄。","平生漱芳意，此日觉偏长。","乐事当自知，清言亦可忘。"]},{"t":"汤嘉宾太史招同诸名公社集南郊草桥别墅三首 其三","f":"五言古诗","c":["醉乡■何许，栗里与竹林。","古来贤达人，放旷犹视今。","陶然三杯后，浩气盈冲襟。","片言苟有会，木石尽知音。","君看抱瓮者，久矣息机心。"]},{"t":"清明日郊游二首 其一","f":"七言律诗","c":["管弦车马竞华年，客路看春倍可怜。","十载衣冠还旧侣，一时榆柳又新烟。","晴郊日暖生芳草，故国花残怨杜鹃。","牢落王孙意无限，莫教长笛倚楼前。"]},{"t":"清明日郊游二首 其二","f":"七言律诗","c":["处处控春兼上坟，人歌人哭隔溪闻。","谁能不醉生前酒，肯信曾修地下文。","世远玉鱼终启柙，蓬深石马自眠云。","彭觞一笑无分别，且倒青尊对夕曛。"]},{"t":"举第三子韩孟郁辱赠诗赋得排律十韵酬之","f":"七言古诗","c":["金门待诏竟何如，吏隐馀闲得弄雏。","丽日莺花宜缓带，春风闺闼有悬弧。","征兰岂叶熊罴梦，剪朆聊同豚犬呼。","骨相未逢僧宝志，清芬谁拟谢封胡。","琴书世业欣堪托，戈印勋名敢浪图。","且命芳尊邀上客，更催歌鸟劝提壶。","筵前汤饼随燕俗，诗里琼瑶映锦襦。","逸调云翔丹穴凤，仙声掌动紫渊珠。","杜陵虚羡徐卿美，陶令应嗟众子愚。","凡鸟他年迎吕驾，题门肯入敝庐无？"]},{"t":"许玄佑载酒过小斋","f":"七言律诗","c":["吏散高斋学灌园，暑深褦襶少过门。","无人不厌嵇康懒，有客偏移竹下尊。","十载交情怜往事，千秋孤调可同论。","清谈静对垆烟袅，飒飒微凉起北轩。"]},{"t":"送黄敦柱太史册封楚王府","f":"七言律诗","c":["七泽平吞楚塞长，汉湘浩淼接天潢。","分茅玉册随星使，授简雄风起大王。","江上紫兰邀彩笔，楼头黄鹤引飞觞。","羡君已擅骚人调，况复经行屈宋乡。"]},{"t":"寄林坦之陈仪翔居庐之作","f":"七言律诗","c":["西风落叶满长安，微雨孤灯坐夜阑。","客里行藏秋又半，镜中勋业鬓将残。","梦回水竹沧江阔，谁倚松杉白兔寒。","拙宦十年同偃蹇，交游休浪说弹冠。"]},{"t":"凤池篇 为邓秘书荣赠尊人作","f":"七言古诗","c":["凤凰池上步夔龙，琼府仙居隔几重。","影泻鸡林清皎皎，光摇鹤御暖溶溶。","烟开金掌朝犹淡，柳拂银塘晚更浓。","有美一人骞凤羽，临池载笔翻垂露。","听乐已邻瑶水宴，逐群曾指瀛洲路。","涟漪春日动恩波，王母筵前乐事多。","忽有馀沾霏紫海，旋看大泽沛黄河。","龙宾直向墨池入，鲛绡更洒浮提汁。","海若俄惊凤诰新，波臣偏讶鸾笺湿。","望云无复泪涓涓，泉下重开日月天。","幸际来仪逢舜孝，好将游泳颂尧年。"]},{"t":"西郊社集赋得折荷缉寒袂","f":"五言古诗","c":["八月凉风至，骚人念授衣。","皎皎绮纨子，袨服有光辉。","幽性厌游冶，华躬与俗违。","嘉彼江中荷，亭亭出淤泥。","虚心兼直干，婀娜馀香披。","剪为君子裳，雅尚正相宜。","绿云浮巧染，白纻扬轻丝。","裁缝自洛女，制度倩湘妃。","飘飖鹤作骨，淡淡冰为肌。","长啸秋江上，应无维鹈讥。","松花晚餐罢，跨鹿翳华芝。"]},{"t":"又赋得鱼戏新荷动","f":"五言古诗","c":["江村昨夜雨，新水涨春潮。","纵步横塘曲，芙蕖冉冉娇。","浮钱青始缀，卓笔翠方翘。","嘉鱼群出游，队队互相招。","红鳞一跳掷，绿盖几飘飖。","翻珠落波心，恐湿鲛人绡。","彼美者谁子，临流驻兰桡。","采荷付鱼书，达寄到西辽。","并头与比目，脉脉两情遥。"]},{"t":"吴会湖山歌为中秘刘君寿","f":"七言古诗","c":["吴会诸峰何巑岏，湖水平吞震泽宽。","山光湖色摇倒影，青螺颗颗浮银盘。","余占花洲称傲吏，六年啸咏湖山里。","玩弄兰舟片月流，逍遥蜡屐雄风起。","手把芙蓉眼倍青，回望吴门气常紫。","岂徒授简召词客，直欲吹笙揖仙子。","别来燕月隔吴云，夜夜湖山入梦频。","涧中瑶草浑如旧，岛外琪花别有春。","姑苏才人刘玉受，笔端收尽湖山秀。","戏彩今看锦作衣，驱车更羡游方昼。","而翁官级近蓬莱，绿发青瞳本鹤胎。","湖水变成云液酒，君山遥捧紫霞杯。","岁岁人间多乐事，何须重去问天台。"]},{"t":"移鱼缸近卧床观避暑漫赋","f":"七言律诗","c":["赤日行天午赫曦，幽蜃沐发足逃虚。","榻临盆沼知鱼性，梦引江村到客居。","病酒懒酹河朔饮，仙丸长忆葛洪书。","年来正苦频消渴，敢望宫冰下玉除。"]},{"t":"初秋夜听雨","f":"五言律诗","c":["客思迎秋急，霪霖入夜听。","回风飘断杵，湿叶隔流萤。","莫涨银河水，应怜织女星。","梦归泥滑滑，敢问短长亭。"]},{"t":"新春送弟云龙南归","f":"七言律诗","c":["鸿雁南还人又归，离心不及雁齐飞。","长途野店谁同被，冷宦闲门尚掩扉。","上垄忍攀苍柏古，登堂应馔白鱼肥。","承家勋业深期汝，莫向沧江老芰衣。"]},{"t":"七夕同韩孟郁赋得雨霁吐新月二首 其一","f":"五言律诗","c":["长天新雨霁，正恐涨银河。","宝镜初开匣，残机晚挂梭。","蛾眉开潋滟，玉箸歇滂沱。","桂阙人相妒，休誇乐事多。"]},{"t":"七夕同韩孟郁赋得雨霁吐新月二首 其二","f":"五言律诗","c":["不用招乌鹊，横虹已架桥。","寒蟾明绛蜡，神女避龙镳。","来喜房栊皎，归嫌风浪消。","人间与天上，秋思雨萧萧。"]},{"t":"雪夜听鸡","f":"七言律诗","c":["欹枕听鸡旅病中，数声嘹亮带残钟。","雪深庭院知盈尺，梦绕关山隔几重。","绛帻希闻清漏报，黄扉长被白云封。","中宵起舞成何事，肠断梅花四百峰。"]},{"t":"暮春游高梁桥","f":"七言律诗","c":["柳荫清溪绕郭斜，寻芳游骑出平沙。","行随碧草看流水，欲访仙源问落花。","潦倒残春须纵酒，萧疏散吏若无家。","醉归渐觉红尘远，携得西郊一片霞。"]},{"t":"云来亭歌为王木仲太史赋","f":"七言古诗","c":["王君卜筑东海头，松关竹径林塘幽。","白日闲门无俗客，虚亭惟有片云留。","云从何来自泰岱，触石崇朝成沾䨴。","下覆重溟接蜃楼，上蒸寥廓翻鹏背。","主人呼吸元气通，岱宗渤海盘心胸，指挥列缺奔丰隆。","当年龙蛰且高卧，云物缭绕纷相从。","团团映户如车盖，玉叶金枝铺锦绘。","五色斜飞素凤笺，一綖摇曳博山烟。","已荣松竹褰萝牖，又送神仙到木天。","木天缥缈蓬莱里，三径难忘泉石美。","梦逐行云夜夜归，回首岱宗气常紫。","共道时来解作霖，谁知出岫本无心。","功成去问任公子，缘野平泉云更深。"]},{"t":"杪秋夜雨","f":"五言律诗","c":["一夜杪秋雨，离人万里心。","蛩声上砌急，烛影入帏深。","不为功名薄，翻愁年鬓侵。","清商无限意，试理壁间琴。"]},{"t":"赋得新安江水清寿毕年伯既元配孙夫人","f":"古风","c":["君不见新安江上水，千寻见底清。","俯视游鳞写乔树，冷冷空碧照心明。","人传脉接轩辕洞，又道源通婺宿精。","气佳地秀有如此，其中绰约多仙子。","磊落长松倚岸蟠，崔嵬怪石临江起。","松脂黑雾化龙宾，石角金星琢龙尾。","毕翁筑室江之干，二龙入管随驱使。","吏隐中年卧紫氛，细君贞淑并能文。","台上箫声调白雪，阶前玉树拂青云。","清水清门两辉映，花笺江练平铺净。","兴到风生班女毫，诗成影彻秦嘉镜。","郎君豸绣五云间，堂上椿萱鬓未斑。","岁汲清江酿春酒，朝看潮去暮潮还。","潮头东下蓬山近，子晋麻姑行问讯。","莫惜流霞劝羽觞，君家元醉瓮边郎。"]},{"t":"九日同王张二山人登白塔台书怀","f":"七言律诗","c":["冯高秋望杳无涯，表里河关拥汉家。","已倩白云扶落帽，更携黄菊散空花。","清砧出郭催寒近，返照衔山度鸟斜。","古往今来何日尽，大千世劫本恒沙。"]},{"t":"沈伯含社丈候左迁铨落凫都门投赠新诗赋答二首 其一","f":"七言律诗","c":["风雅千秋鼓待吹，谁云删后更无诗。","一时连社还高会，诸子兰亭总妙词。","倾盖喜逢天下士，放歌羞逐郢中儿。","羡君孤调真同调，已觉新知是故知。"]},{"t":"沈伯含社丈候左迁铨落凫都门投赠新诗赋答二首 其二","f":"七言律诗","c":["同病相怜各惘然，齐盟一日孰先鞭。","积薪愧我官仍拙，投杼悲君客更迁。","醉向金门堪据地，狂来碣石浪谈天。","他年人泛秦淮月，远忆江州夜泊船。"]},{"t":"闻姜将军讣","f":"七言律诗","c":["哭君犹忆六年前，抵掌相看各自怜。","归去灞陵无旧业，俄闻京兆又新阡。","蛇衔冷血鸣孤剑，星落游魂绕九边。","侠骨余香寄蘅杜，不须高冢象祁连。"]},{"t":"题项赠君乡贤册","f":"七言律诗","c":["赠君潜德竟何如，已见门高驷马车。","一代斗山归月旦，百年俎豆映籫裾。","占星不愧贤人里，列传应烦太史书。","欲探仙源拜遗像，双溪东去绕桐庐。"]},{"t":"丁未冬至朝罢登白塔台","f":"七言律诗","c":["宫漏微茫玉管催，骎骎车马散朝回。","阴阳应律终须转，天地无心未易猜。","暖入梅根遥待腊，寒冲竹叶且衔杯。","层台漫上休翘首，愁见云从故国来。"]},{"t":"送张孟奇督榷吴关余昔令吴颇兴旧感","f":"七言律诗","c":["吴门南望是并州，相送旗亭忆旧游。","物力已闻非昔日，度支何以佐持筹。","冰心合饮中冷水，彩笔平吞震泽秋。","自有蒪鲈供咏酌，季膺休更动乡愁。"]},{"t":"题报国寺老蟠松","f":"七言律诗","c":["不将鳞鬣舞高岑，怪尔低蟠双树林。","岂是毒龙能说法，偶闻真偈顿降心。","春深香粉横金界，夜静寒涛绕梵音。","借问师游何日返，数枝长偃到如今。"]},{"t":"侍御周荐师举遗腹子志感","f":"七言律诗","c":["七泽三湘白日昏，大招难起楚天魂。","台空骢马遗龙种，珠湿鲛绡迸泪痕。","蔡琰琴书还在箧，赵宣宾客几过门。","他年恸哭西州路，一剑犹惭国士恩。"]},{"t":"送陈原父年兄任广安学博","f":"七言律诗","c":["经年旅食共京华，别思寒风拥客车。","已叹弹冠兄弟少，遥怜把袂路岐赊。","琴书官冷淹黄绶，雨雪堂深隔绛纱。","闻道坛边多种杏，春来还作凤城花。"]},{"t":"天目歌送李伯远之临安学博","f":"古风","c":["越山高，越水长，越天万里吞南荒。","绝峤东西开两目，中天日月悬睛光。","照破鸿蒙视太古，转盼中原一抔土。","云霞明灭映天台，岩壑轩翔压天姥。","洞中仙鼠飞白鸦，玉芝茁茁森于麻。","流泉瀑布奔深涧，昭明翻经曾洗眼。","唐代琼宫结构存，汉皇龙简精灵远。","灏气微茫上太清，山麓下接临安城。","临安之城大如斗，不意近入李君手。","峰影澄明落泮池，支颐爽气当窗牖。","龙飞凤舞古记之，片毡携去休攒眉。","勿论桃李待时雨，喜得烟景迎新诗。","君来已贵长安纸，君去佳名满人耳。","洒笔振衣第一峰，可念同盟者诸子。","君不见马融帐，非虚设，郑虔妙技称三绝。","丈夫垂名动万年，此心肯向傍人说。","青袍黄绶且夷犹，白雪阳春若与俦。","知君双目如天目，一笑山空水自流。"]},{"t":"送胡昌世比部转饷辽阳便道归五岭","f":"七言律诗","c":["夜夜旄头照海天，辽阳杀气镇相缠。","枕戈谁念三军苦，转饷俄腾万灶烟。","塞雪近关看破腊，岭梅迎马报新年。","相如拥传多光彩，岂羡乘槎到日边。"]},{"t":"送许玄秘书归省兼讯景阳君","f":"七言律诗","c":["归去班衣书锦看，新携赤管下翔鸾。","离亭折柳南枝尽，驿路驱车朔雪寒。","春到莺花连海峤，梦回阊阖在云端。","东山烟月烦相问，何事栖迟老谢安。"]},{"t":"狂歌行","f":"七言古诗","c":["同云如絮低压墙，北风刮地号枯杨。","滕六夜挟玄冥翔，寒威杀气排剑枪。","街鼓隆隆声镗鎝，万户人静漏微茫。","此夕旅思弥天长，有客将行宵具装。","雌雄分匣啼千将，飞霰片片搅离肠。","绨袍欲赠念无裳，主人延客开华堂。","月沉星暗烛代光，兽炭吐焰鳞甲张。","金鲸泻酒奔吕梁，有肉如陵兰椒芳，驱寒度暖邀青皇。","酒星元在玉帝旁，谪来人间号高阳。","尚书之期虽太忙，礼法不省瓮边郎。","问量若许吞八荒，舌尖已挂东西洋。","一吸瀛海沧为桑，河泊不敢向大方。","君家有秫千箱仓，酿来涓滴祗池塘。","我舔舕之未濡吭，尧钟髡石仅涤觞。","唾骂中山与杜康，何不伸手翻神浆。","糟天曲地尽汤汤，我辈拍浮其中央。","百万亿劫乐无疆，半酣浩歌声扬扬。","隆冬轰雷忽殷房，亲谑叫啸惊九阊。","帝遣六丁问豪狂，勿倾银汉入流黄。","我言下界多秕糠，臣身合在酒中藏。","是非毁誉沸如螗，升沉显晦俱亡羊。","蜗角有国蚁有王，真同傀儡夜登场。","嫫姆竟掩夷光妆，方朔不及侏儒囊。","拔兰斫桂佩艾香，轩鹤啄粟囚鸾凰。","粪丸进御却明珰，谁能与世相低昂。","朱门蓬户鬓皆霜，谓彭非寿亦非殇。","醉不必卧七宝床，醒不必游碎锦坊。","摆脱町畦而徜徉，大之乘风踞云庄，小之构巢蚊睫芒。","人生达命顺其常，懒作天问问彼苍。"]},{"t":"题归咏紫芝卷赠袁前洲南归","f":"七言律诗","c":["振衣轻拂帝京尘，南国烟霞有主人。","鹤■盈头归正好，图书满箧未全贫。","千金散尽门前客，三秀长留洞里春。","自笑劳劳淹薄宦，羡君黄绮不称臣。"]},{"t":"将进酒","f":"古风","c":["君不见提壶鸟，前生不饮酒。","遗恨东风怅落花，枝上提壶不停口。","羲和鞭日急如梭，春光九十元无多。","鹔鹴可典龟可换，但愿尊中日长满。","杯行到君君莫辞，禽声有意君当知。","休誇杏色如人颊，但恐杨花罥鬓丝。"]},{"t":"咏雪三首效西昆体 其一 一颂雪","f":"七言律诗","c":["岁阑遥报早春催，六出祥花拂曙开。","天女看梅摇玉佩，仙人骑鹤下琼台。","螟蝗北户寒应尽，田畯东皋首重回。","休问巡游怨黄竹，君王入骏在蓬莱。"]},{"t":"咏雪三首效西昆体 其二 二赏雪","f":"七言律诗","c":["水精帘卷对华觞，湛湛冰壶琥珀光。","四座宾朋梁国苑，一堂词翰谢家郎。","翻歌转觉银筝冷，逐舞轻随玉袖扬。","已俪幽兰裁楚调，不须更学寿阳妆。"]},{"t":"咏雪三首效西昆体 其三 三嘲雪","f":"七言律诗","c":["轻薄霏霏远趁人，敢同青帝斗芳春。","王恭鹤氅虽鸣玉，郑綮溪桥已作尘。","似絮岂曾窥柳眼，输香空自笑花神。","漫誇九陌铺银界，何事袁安彻底贫。"]},{"t":"丁未除夕书怀","f":"七言律诗","c":["守岁孤灯夜欲徂，冯唐郎署胡为乎。","寻常有愿非狂诞，四十无闻愧丈夫。","转觉风云多后进，空嗟犬马老长途。","年年牢落看人意，莫怪高歌击唾壶。"]},{"t":"人日暖阁红梅盛开","f":"七言律诗","c":["旭日明窗散曙光，一枝红玉濯温汤。","阁中彩笔邀何逊，檐下新妆点寿阳。","春早风霜还妒色，堂深帘幕暗留香。","凭君为寄罗浮梦，南国迢迢意倍长。"]},{"t":"元夕招吴梦旧游集小斋席上赋","f":"七言律诗","c":["一曲吴趋调转新，座中同是旧游人。","携来西子湖边月，散作荆卿市上春。","吏隐琴樽无俗侣，地偏车马隔流尘。","苍茫陆海三山近，好驾金鳌去问津。"]},{"t":"灯市篇","f":"古风","c":["众星环斗极，万国拱京华。","文物流殊俗，车书正一家。","马放白登闲汉戌，笳沉青海靖胡沙。","胡沙汉戍临荒服，尧封禹甸绵周箓。","雄关虎踞一百二，圣主龙飞三十六。","送腊玄霜散北郊，迎春青帝回东陆。","明堂元旦朝诸侯，仙乐遥传万井讴。","瑞日轻笼囗鹊观，卿云低抱凤凰楼。","六衢九陌饶佳气，击坏升平多燕喜。","宫中锦绣结熬山，陌上烟花满灯市。","灯市游人杂还来，交廛列肆两边开。","阵阵香尘萦晓雾，填填画毂度新雷。","香尘画毂华灯下，竞巧矜能高索价。","白凤斜飞螭口衔，黑龙倒舞麟须挂。","鸡踏红莲玉作台，鲸翻绛蜡金为架。","绮靡应同董偃奢，神奇肯在丁谖亚。","更有胡商碧眼悬，携来异宝气冲天。","黄金满斗真成土，彩帛如山不论钱。","披图若献河宗瑞，陆地忽涌波斯船。","制就九枝逾万万，装成四照讵千千。","谁家千万争豪侈，中贵侯门兼戚里。","横跨市上起歌楼，直倚云边奏声伎。","火树光摇洛洞羊，春樽色泛嶓山兕。","楼头弦管逐年新，楼底喧喧引看人。","歌声窃窕闻黄道，灯影荧煌彻紫宸。","紫宸黄道连双阙，银蟾皎洁银河没。","已讶仙人五色烟，旋看帝子重轮月。","月华星彩迥层层，马埒球场兴倍增。","望去九门开铁缫，行来十道界金绳。","妖姬解造千番曲，上客能酬几匹绫。","公子王孙徒妩媚，鸣钟列鼎浪骄矜。","良宵未觉欢娱毕，鼓声隆隆催晓日。","转眼风光又一时，人生宁有百年期。","冯唐白■遥相待，扬子玄经谁见知。","羞随轻薄空驰逐，繁华富贵风前烛。","潦倒堪为毕卓眠，升沉懒问君平卜。","燕市难逢击筑人，素衣愁染帝京尘。"]},{"t":"仲春周子围亭","f":"七言律诗","c":["纷纷蜂蝶为春忙，竹外春云隔苑墙。","芳草绿时风渐细，名花湿处雨皆香。","官闲转觉朝参懒，地僻真怜野趣长。","莫道园林无鼓吹，群蛙早已闹斜阳。"]},{"t":"送俞昌宗归吴","f":"七言律诗","c":["离亭新柳未含烟，谁道春归在客先。","侠气尚悬三尺剑，生涯应付五湖船。","闲云片片随孤鹤，芳草茫茫接远天。","寄谢百花洲上月，旧游回首一潸然。"]},{"t":"蒲涧歌为潘年伯寿","f":"古风","c":["君不见白云东去接罗浮，白云之下蒲涧幽。","石上仙灵护九节，安期驾鹤常来游。","秦皇汉武岂不贵，方士远遣终难求。","何如潘翁自高介，葛巾藜杖轻王侯。","时登白云一啸傲，璇房处处成丹丘。","日采蒲花充午膳，身跨白鹿骑青牛。","郎君待诏金门外，窃桃不知经几秋。","长生已授仙人箓，纶綍犹传出殿头。","君家南望沧溟近，潮声岁岁为添筹。"]},{"t":"送刘觐国民部奉使关中便道游华山","f":"五言律诗","c":["婚嫁何须毕，羡君方妙年。","春风吹四牡，华岳到金天。","分陕凭栏尽，明星指掌悬。","浮槎休更问，且泛藕如船。"]},{"t":"长歌行送米仲诏年丈调六合令","f":"七言古诗","c":["主人闲斋对石丈，厌向尘容走俗状。","锦心壁上挂奚囊，风雅坛中称社长。","偶然捧缴寄微官，飞舄聊寻勾漏丹。","岂料瞿塘春水急，空嗟蜀道古来难。","去年曾理烟波艇，越水吴山探寥迥。","芒鞋竹杖苦未竟，梦寐常到东南境。","谒选翻为六合游，片帆遥指石城秋。","观涛好试枚乘笔，沽酒应登孙楚楼。","六朝词赋无标格，庭花玉树何萧索。","他年迟我泛秦淮，长啸一声江练白。"]},{"t":"壮游歌送民部刘觐国转饷关中便道游华山归上太夫人寿","f":"楚辞体","c":["君不见醯鸡在瓮鹏搏天，蜉蝣朝菌笑龟年。","丈夫七尺岂徒然，三山五岳在屐前。","子长足迹半天下，千秋史笔悬高价。","谁道向平贤达人，区区何必论婚嫁。","刘君刘君天下奇，片言可使山岳移。","皇华直向关中道，明星白帝纷前导。","车箱不容幰箭筈，仅通天人疑金粟。","佛已坐，玉池莲，到时祝融暖登后。","西风壮，人非承露盘，翻在仙人掌。","渴则倾玉女浆，倦则卧希夷床。","秦陵汉阙不可辨，渭泾清浊空茫茫。","为我寄言函谷吏，青牛西去知何意。","更问瑶池戴胜人，周王八骏何逡巡。","玄霜绛雪携满袖，归向北堂舞春昼。","为君歌壮游兮，当云璈之雅奏。"]},{"t":"梁比部卓卿乘使传归祝尔尊人寿赋赠","f":"七言律诗","c":["芙容阙下望庭闱，乘传争看四牡騑。","南极星连三岛近，西曹人逐片云归。","尧阶实命承天语，汉署香风入彩衣。","试问鹿门同隐处，何如萧史凤双飞。"]},{"t":"赋得春风芳草篇送比部梁卓卿转饷边镇便道归粤东","f":"古风","c":["凤野三阳转，燕山二月时。","韶光明似锦，新草细于丝。","羃䍥王孙萦别绪，微茫游子动乡思。","乡思别绪何超忽，使星驿骑明朝发。","屈指长亭复短亭，马蹄到处自青青。","輶轩直入将军幕，谈笑能空老上庭。","边庭不似长安陌，草芽欲茁寒难坼。","望塞云深稍变黄，近关沙远翻为白。","去岁严冬草尽枯，三军庚癸夜传呼。","转饷有人将雨露，枕戈谁复怨靡芜。","清明渐近新烟起，士饱马腾共欣喜。","辕门吹角宴嘉宾，草色侵阶簇绣茵。","已向北门承驻节，还随南国送归人。","归人归兴更萧萧，庾岭山高粤水遥。","行盖浮青牵弱带，征袍摇绿上轻绡。","弃繻休问当关吏，题柱重过旧日桥。","关前桥畔山斋路，莺啼燕乳知春暮。","曲水流杯似有情，落花点草应无数。","社老争分陆买金，里儿近识张骞辂。","山中桂树漫留连，回首长安在日边。","都门草绿遥迎客，仙署兰香已隔年。","独有羁人归未得，春风送别片心悬。"]},{"t":"送赵幼安还吴参谋幕府","f":"七言律诗","c":["滇南烽火起边声，又报辽阳议益兵。","拊髀几年烦圣主，请缨今日羡儒生。","军前草檄风侵幕，楼上吹笳月满营。","谁道赋诗难退虏，诗家元自有长城。"]},{"t":"施虞吉丈携琴过小斋率尔赋赠","f":"五言古诗","c":["散吏有馀清，苔绿无人破。","客子抱琴来，剥啄惊高卧。","入户皎玉山，爽气满中座。","明徽与善手，泛弄三两过。","心随流水远，尘世堪一唾。","家有无弦琴，闭匣久不课。","对君怜知音，操缦试则个。"]},{"t":"鸣琴行送樊孟泰令广昌","f":"楚辞体","c":["子贱宰邑日，鸣琴不下堂。","琴中有妙理，坐使庶事康。","君今出宰携琴鹤，山水麻姑元不恶。","南熏舜殿已曾听，单父清声应继作。","客路西风惜别离，停杯立马意迟迟。","空囊无物为君赠，聊陈琴趣君当思。","琴不在弦不在指，金徽玉轸徒为尔。","自古希声属大音，谁知趣在无弦里。","有弦有声并有情，八风六律总和平。","大弦张急小弦绝，勿以春温等秋烈。","明徽善手两相调，游鱼秣马皆娱悦。","邑有豪暴君摧之，中弦霹雳随霜飞。","岂无贤士在空谷，又奏幽兰与鸣鹿。","曲罢遥闻乌夜啼，应怜野哭多孀妻。","乌啼天曙飞朝雉，境内遣鳏须料理。","立身凛凛同高山，清节冷冷若流水。","曲如钩兮虽封侯，不若如弦气更遒。","君看美材居爨下，自有识者能相求。","行行莫厌为俗吏，但贵不思泉石意。","古调今人多不弹，琴心三迭泪潺湲。","念我时能操别鹤，愿慎动静加君餐。"]},{"t":"无题","f":"七言律诗","c":["何处春风无别离，梨花落尽负前期。","虚传龙剑能运匣，不分鸠巢独占枝。","苏北药苗名远志，江南红豆号相思。","韶光物态关人意，况复青灯夜雨时。"]},{"t":"米君梦过小斋赋以赠之","f":"七言律诗","c":["相逢击筑倚青萍，中夜哀歌怅独醒。","身寄风尘孤鹤瘦，眼空湖海一鸿冥。","诗名都下推秋柳，处士云边识客星。","闭声著书春草合，几人能过子云亭。"]},{"t":"闻刘门从姊新寡","f":"五言律诗","c":["老年儿女大，婚嫁已难禁。","岂意刘伶饮，翻为屈子沉。","竹枝千点泪，关塞万重心。","行橐垂垂尽，回书怅一金。"]},{"t":"题王太史梅花帐","f":"七言绝句","c":["官阁梅开雪霁时，月斜移影入书帷。","暗香浮动谁先觉，祗有庄周蝴蝶知。"]},{"t":"送蔡敬夫司马转饷关西","f":"七言律诗","c":["折柳都门惜解携，仙郎转饷出关西。","使星气压边烽息，行幰睛褰塞草齐。","野戌万花迎客笑，荒屯独鸟向人啼。","羡君乘传当春日，处处香坭待马蹄。"]},{"t":"哀滇南","f":"七言律诗","c":["昆明池上黑云浮，魂哭天阴草水愁。","狡虏黄金还在肘，荒郊白骨已成丘。","幕中坐啸谁为主，城下寻盟众所羞。","启衅兴戎非一日，滇南十载困诛求。"]},{"t":"采莲曲","f":"古风","c":["若耶溪畔几人家，处处清流漾落花。","东流远接镜湖水，洗残西子旧时纱。","春鸠昨日催春雨，水长门前三尺许。","今朝鹊语报新睛，潮归水落溪湖平。","红莲簇簇向人笑，花摇锦浪香风生。","临溪女伴娇罗袜，兰舟桂楫乘潮发。","绣带朝萦溪里烟，歌声夜泛江边月。","细踏船头步步金，偏惊雁落更鱼沈。","正怜翠叶如眉黛，又弄珠光荡妾心。","两岸紫骝游冶子，缓辔随船不知止。","谁识心中别有丝，水深没藕怨江妃。","还看双双鸂?浴，复羡鸳鸯两两飞。","日暮归来肠断尽，馀香在袖上残机。"]},{"t":"相逢行赠别王木仲社丈请急东归","f":"古风","c":["长安静寄者，非隐亦非吏。","床上书连阶下苔，门径萧萧无客至。","空瓶乏粟愧侏儒，拥膝高歌小天地。","待诏金门笑岁星，相逢谁氏眼偏青。","王君王君好气岸，天花落笔纷淩乱。","社中新创白雪坛，酒后频投青玉案。","自从结社叠赓酬，洛阳纸价如琳球。","岂直都人竞传写，绝国已许千金求。","一时意气横今古，郢曲巴声安足数。","科危持却曹刘墙，复构云梯攻李杜。","正叹知音和者稀，君今请急又东归。","诗筒入袖随行橐，别泪临河洒客衣。","云来亭下波涛远，月明濯足沧溟晚。","得句应翻鲛室珠，霞飘锦字群龙趋。","阳春有意怜同调，时寄高文一起予。"]},{"t":"咏得含风蝉","f":"五言绝句","c":["清韵因风远，泠泠万木秋。","莫矜玄鬓影，叫白几人头。"]},{"t":"花王三诗 其一 绿牡丹","f":"七言律诗","c":["静倚雕栏半掩嚬，青皇偏与十分春。","羊权条脱逢仙子，金谷明珠换美人。","袜染洛波浮翠色，裙摇湘竹动芳尘。","可怜嫩叶如眉黛，秉烛相看意转亲。"]},{"t":"花王三诗 其二 黄牡丹","f":"七言律诗","c":["曾侍君王捧玳筵，御袍相映曲池前。","休誇汉苑妆如月，不羡潘妃步蹴莲。","丛菊无缘窥艳冶，流莺何意妒婵娟。","姚家旧谱君休问，凝碧沈香起暮烟。"]},{"t":"花王三诗 其三 白牡丹","f":"七言律诗","c":["槛外温风绽锦囊，花王何事尚含霜。","吹残柳絮难分色，落尽梨花为避香。","白玉堂前春欲暮，水晶宫里日初长。","相逢谁是怜花者，虢国夫人爱淡妆。"]},{"t":"春昼","f":"七言绝句","c":["懒困东窗昼觉长，起来帘幕暗浮香。","青皇有意催诗句，故遣飞花落笔床。"]},{"t":"戊申清明高梁桥申太仆招游","f":"七言律诗","c":["宿雨初晴麦气凉，西郊芳草遍春光。","舞回波影流偏驻，歌飏杨风絮更狂。","士女行缠金屈膝，少年飞鞚紫游缰。","谁怜散吏容疏放，岁岁看花大道旁。"]},{"t":"李侍御晋囧卿贰赋赠","f":"七言律诗","c":["几年搅辔半中原，到处霜清露更繁。","直谏千秋传旧草，仙班九列拜新恩。","天高卿月临沙苑，夜静房星在厩门。","正是金台求骏地，羡君当御尽龙孙。"]},{"t":"燕山闻杜鹤","f":"七言律诗","c":["百舌声喧絮乱飞，杜鹃又到蓟门枝。","洛桥啼罢市朝异，蜀国魂归道路疑。","人事未随阳气转，天心宁待野禽知。","好依宫树催春曙，日暖龙眠起每迟。"]},{"t":"春暮清斋作","f":"七言律诗","c":["嫩槐垂槛噪新蝉，屈指春光又一年。","作客敢辞花底醉，出郊应欠杖头钱。","聊将蒲殖供朝膳，亦有琴书伴午眠。","虚馆寥寥如野寺，茶烟轻绕博山烟。"]},{"t":"风沙诗","f":"五言律诗","c":["莽互疑龙战，风沙白日阴。","土囊应破裂，地轴恐浮沈。","道路无青草，乾坤半绿林。","忧时关百虑，造化若为心。"]},{"t":"暮春登报国寺经楼感滇粤辽阳警报作","f":"七言律诗","c":["独上高楼望紫宸，微茫宫树锁残春。","飞飞珠箔堂中燕，扰扰铜驼陌上人。","四海膏脂随日尽，九边烽火逐年新。","不知肉食优游者，曾向空门学化身。"]},{"t":"喜雨","f":"五言律诗","c":["山带晓氤氲，层阴午未分。","微风起少女，惊电划长云。","润变郊原色，声冲鹳鹤群。","羽书滇粤急，好洗汉家军。"]},{"t":"丁未午日独酌","f":"五言律诗","c":["密叶咽疏蝉，虚堂坐黯然。","壶觞堪自遣，蒲艾故相鲜。","久客伤千里，怀归又一年。","江南箫鼓竞，心折幕潮边。"]},{"t":"夏日招郑周黄三子集小斋细雨忽至","f":"五言律诗","c":["虚室净琴张，开樽对夕阳。","微言能却暑，过雨更生凉。","人世多岐路，浮沈付醉乡。","晚归堪跃马，山简本清狂。"]},{"t":"夏日米君梦吴翁晋载酒过斋头席上同赋二首 其一","f":"七言律诗","c":["雨过苔痕绕砌生，客居终日罢逢迎。","叩门谁载贤人酒，怪尔偏知隐吏名。","谈久竹风吹短麈，坐深花影落残枰。","淹留正好期华月，向晚虚堂暑气清。"]},{"t":"夏日米君梦吴翁晋载酒过斋头席上同赋二首 其二","f":"七言律诗","c":["高枕西窗午梦阑，翛然对客若无官。","闲来转觉三生妄，静后还怜一室宽。","近市臣心同止水，断金交谊比丛兰。","醉归直待喧声歇，门外红尘不忍看。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其一","f":"七言律诗","c":["衔杯执手久踟蹰，往事惊心感慨馀。","南国怀人千里梦，西风归雁几封书。","旅愁落落便吾懒，交态悠悠与世疏。","夜雨空阶苔藓合，怜君还问病相如。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其二","f":"七言律诗","c":["相逢犹忆壮游年，并马看花绣陌边。","老去豪狂仍面目，重来燕赵异风烟。","干戈杀气缠三辅，阊阖浮云隔九天。","我是羁人君左调，夏时谁著祖生鞭。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其三","f":"七言律诗","c":["西飞白日东流河，荏苒年华叹掷梭。","客舍短檠惟汝共，闲门阴雨更谁过。","微官偃蹇羞鸡肋，半醉佯狂学凤歌。","试问北山人去后，岩扉松桂近如何。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其四","f":"七言律诗","c":["年少青云夙共期，辟雍春水照琼枝。","君看鸣佩环桥日，何异游梁入洛时。","意气久倾天下士，功名番后里中儿。","浮沈潦倒伤今昔，旧恨还应短剑知。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其五","f":"七言律诗","c":["作吏天涯叹薄游，金阊白狱尔离忧。","秫田芜没宁供醉，手板逢迎可自由。","兴到吕安难命驾，愁来王粲只登楼。","自从共泛吴门月，枫叶芦花五换秋。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其六","f":"七言律诗","c":["惆怅离群经几春，依然相对泣迷津。","纵令白眼难谐俗，岂谓青山亦厌人。","宦达鸳鸾堪结侣，退居猿鹤可为邻。","穷通有主非关我，不辨乾坤幻是真。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其七","f":"七言律诗","c":["读罢离骚动苦吟，新安江水照君心。","从他流谤能盈箧，自信披裘不取金。","世事无常看倚伏，此身如寄任升沈。","百年□付杯中物，莫遣闲愁入爽襟。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其八","f":"七言律诗","c":["雨洒灯花落酒卮，停卮不语有馀悲。","捩风孤鹳鹳城去，隔叶流萤出槛迟。","下榻虚窗更漏永，思乡远峤水云疑。","僦居邻近经过易，旅食淹留且岁时。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其九","f":"七言律诗","c":["侠骨崩腾浪自矜，穷愁慰籍有良朋。","炎天门巷凉如水，野菜盘飧澹似僧。","仕路几人誇捷径，词坛惟尔快先登。","千秋大业吾曹事，肯谓支床病未能。"]},{"t":"雨夕陈仪翔年丈过小斋话旧同赋十首 其十","f":"七言律诗","c":["剪烛高斋夜未央，一尊款曲话偏长。","班荆正好宽离索，沽酒何须问客囊。","风雨此时情脉脉，蒹葭他日恨苍苍。","预愁岐路还南北，未唱阳关已断肠。"]},{"t":"落花诗三十首 其一 一东","f":"七言律诗","c":["飘花何意到房栊，叹息年华落镜中。","弱带纤腰同萎谢，伯劳飞燕共西东。","数声羯鼓朝催急，几树琼栏夕照空。","怪底封姨故相妒，开时元解笑春风。"]},{"t":"落花诗三十首 其二 二冬","f":"七言律诗","c":["应同神女下巫峰，黯澹伤春意万重。","舞袖拂来还有态，游丝罥去迥无踪。","桃蹊沙外残霞浅，梨院阶前积雪浓。","莫道芳菲浑落尽，涉江吾欲采芙蓉。"]},{"t":"落花诗三十首 其三 三江","f":"七言律诗","c":["开时还似斗新妆，瘦损丰姿意渐降。","此日乱枝情脉脉，早时连理本双双。","斜翻幕影摇红浪，暗扑灯花下玉釭。","别有渔舟随水入，桃源深处吠仙乡。"]},{"t":"落花诗三十首 其四 四支","f":"七言律诗","c":["枝垂红泪忍抛枝，还胜征人泣诀时。","香歇纵伤今日幕，春归应有隔年期。","明妃出塞终埋骨，苏武生妻竟去帷。","试想人间长别苦，花神何事尚含悲。"]},{"t":"落花诗三十首 其五 五微","f":"古风","c":["探春未了送春归，万紫千红洗渐稀。","馀艳卢姬堪?面，残香荀令待熏衣。","乍迎丝竹临风笑，忽绕梁尘度曲飞。","多少王孙金勒马，重来何处聘轻肥。"]},{"t":"落花诗三十首 其六 六鱼","f":"七言律诗","c":["谩说繁华能久居，请看荣落有乘除。","宠无班女曾题扇，时过龙阳亦泣鱼。","风起青蘋千树靡，庭霏红雨一帘虚。","还疑竹叶无颜色，邀得君王半夜车。"]},{"t":"落花诗三十首 其七 七虞","f":"七言律诗","c":["石家别业洛城隅，昔日风光近有无。","不见留欢围锦障，但闻如意碎珊瑚。","香消谷口春泉冷，人堕楼头夜月孤。","试过遗基望残景，数株芳树带平芜。"]},{"t":"落花诗三十首 其八 八齐","f":"七言律诗","c":["连天烟树望中迷，万片侵堤又点溪。","鱼戏清涟吹锦浪，马嘶芳草踏香坭。","飘残歌扇青楼晚，敛却啼妆翠幄低。","解佩汉皋空想像，断肠人隔画桥西。"]},{"t":"落花诗三十首 其九 九佳","f":"七言律诗","c":["寻芳揽胜兴无涯，不似禅居意味佳。","幻色自牵游子目，妖花难入野僧怀。","翻残贝叶闻清梵，飞尽天香散晚斋。","谁悟沾坭心不染，十年面壁锁芒鞋。"]},{"t":"落花诗三十首 其十 十灰","f":"七言律诗","c":["惜花反畏花开尽，又报东君遣使催。","楚苑雄风吹面急，梁台宝雨自天来。","御沟流去何时尽，宫鸟衔飞几日回。","犹有数株怜妾恨，长门留影覆苍苔。"]},{"t":"落花诗三十首 其十一 十一真","f":"七言律诗","c":["闻道青皇返玉轮，故将香雨浥行尘。","绕沾兴庆池边笛，忽点含童阁里人。","九十春光难再得，百千酒价岂辞频。","寄言全盛红颜子，行乐须知贵及晨。"]},{"t":"落花诗三十首 其十二 十二文","f":"七言律诗","c":["谁家少妇婿从军，闲数馀花对夕曛。","吹度西窗人独倚，泛归南浦水全分。","风飘蝴蝶三更梦，雨散阳台一片云。","踏碎琼瑶愁不扫，朝来还拂绛罗裙。"]},{"t":"落花诗三十首 其十三 十三元","f":"七言律诗","c":["舒啸高台望广原，百花今有几花存。","从来玉貌难长姣，错恨青皇是薄恩。","灯烛西宫虚绛帐，淋铃南内怨黄昏。","谁能更展回春手，惆怅隋家旧日园。"]},{"t":"落花诗三十首 其十四 十四寒","f":"七言律诗","c":["投辖闲园洽晚欢，紫房丹萼渐阑珊。","过墙蜂蝶春拖去，半席壶觞带醉看。","客下歌台珠履散，人归香径翠翘残。","幽崖恐有孤芳在，好倩云烟护洞峦。"]},{"t":"落花诗三十首 其十五 十五删","f":"七言律诗","c":["千岁蟠桃春昼闲，倚云和雾杳难攀。","瑶池宴后花长在，方朔偷来鬓已斑。","堪叹铅华同木槿，谁逢萼绿识仙鬟。","天台从觅来时路，流水潺潺失故山。"]},{"t":"落花诗三十首 其十六 十六先","f":"七言律诗","c":["冉冉东流竟不旋，花飞随马促游鞭。","栽成满县怜潘岳，唱入回风恼丽娟。","十里香尘迷蹴鞠，一围红玉上鞦韆。","鹔鹴典却金龟解，还指新荷当酒钱。"]},{"t":"落花诗三十首 其十七 十七萧","f":"七言律诗","c":["狂风夜动广陵潮，逝水飘香不可招。","波上玉颜窥晓镜，雨中珠泪湿残绡。","瑶花仙种空存观，明月长桥渐罢箫。","尚想龙舟游戏日，到今杨柳亦萧条。"]},{"t":"落花诗三十首 其十八 十八肴","f":"七言律诗","c":["枝压倡楼泣露梢，春深游客半相抛。","娇红浪说如人面，浓绿空看覆鸟巢。","车马不闻喧曲巷，樽罍谁共出芳郊。","江州他日逢司马，拟诉琵琶为解嘲。"]},{"t":"落花诗三十首 其十九 十九豪","f":"七言律诗","c":["闲来结驷共游遨，穿尽重林步远皋。","阵阵玉尘吹麦浪，霏霏金粉落松涛。","青春转眼过三月，绿鬓驱人忽二毛。","分付花前诸乐部，急催檀板和银璈。"]},{"t":"落花诗三十首 其二十 二十歌","f":"七言律诗","c":["淡日和风熏绮罗，清明上巳乐偏多。","飞花恋妓娇能舞，啼鸟怜香巧和歌。","剪彩纵难回锦树，铺茵还得卧青莎。","大堤宴罢归来晚，素袜轻摇洛浦波。"]},{"t":"落花诗三十首 其二十一 二十一麻","f":"七言律诗","c":["恼乱芳心向狭斜，少儿懒困不司花。","游春费尽缠头锦，买笑抛残击臂纱。","黄褪蜂腰无剩蕊，红飞鹃血落谁家。","还闻雨露深如海，掷果他时尚满车。"]},{"t":"落花诗三十首 其二十二 二十二阳","f":"七言律诗","c":["走马看花兴欲狂，飘零万点思茫茫。","绕园锦绣新闻宴，委地胭脂晚罢妆。","系日恨无长命缕，留春那得返魂香。","五陵子弟重相问，更待明年百草长。"]},{"t":"落花诗三十首 其二十三 二十三庚","f":"七言律诗","c":["遥忆西川锦作城，万家香霭散红英。","平拖柳絮浑无力，并掷榆钱暗有声。","卓氏垆头春酒尽，薛涛填畔幕烟生。","花溪近日凭谁浣，欲写鱼笺远寄情。"]},{"t":"落花诗三十首 其二十四 二十四青","f":"七言律诗","c":["祓禊江南饶胜事，暮春高会有兰亭。","群贤载笔清如玉，曲水浮花细似萍。","香堕觞前分片片，枝摇竹外更青青。","风流人物今独昔，寿夭谁能混醉醒。"]},{"t":"落花诗三十首 其二十五 二十五蒸","f":"七言律诗","c":["少年豪侠浪相矜，旋过平阳复杜陵。","兴到酒徒空有约，春残花债向谁征。","更开金埒闲调马，试学吴歌戏采菱。","游罢回鞭指芳树，仓庚飞去但闻鹰。"]},{"t":"落花诗三十首 其二十六 二十六尤","f":"七言律诗","c":["金陵自古帝王州，后主清酣恣逸游。","狎客妖姬骄艳曲，临春结绮搆巍楼。","庭花萧索沈宫井，玉树凄凉蔓野丘。","日暮乌啼归古堞，莫愁湖水亦生愁。"]},{"t":"落花诗三十首 其二十七 二十七侵","f":"七言律诗","c":["催花风雨晚森沈，千里江南永夜心。","戴胜下时香作国，鹧鸪啼后绿成阴。","轻飞赵后翩翩掌，低逐潘妃步步金。","欲赠新词聊戏谑，迢遥溱洧水云深。"]},{"t":"落花诗三十首 其二十八 二十八覃","f":"七言律诗","c":["朝来散步出城南，风水淙淙响石潭。","残蕊树头还有几，标梅林下仅存三。","掠枝乳燕新成子，拂叶飞蛾又变蚕。","怅望丛花如梦里，静依松桧结山龛。"]},{"t":"落花诗三十首 其二十九 二十九盐","f":"七言律诗","c":["闲阶剩馥晚偷拈，错认仙人绛雪甜。","欲笑床空翻入户，似怜愁坐故窥帘。","摧残眉黛芳姿减，迢递关山别恨添。","借问嫦娥月中桂，可曾雕谢洒寒蟾。"]},{"t":"落花诗三十首 其三十 三十咸","f":"七言律诗","c":["离宫琼蕊傍层岩，狼籍香魂尽坼缄。","凝碧未经妃子折，上阳先被晓莺衔。","生憎密叶偏笼帽，可惜轻花乱扑衫。","还让阖闾城下树，半分颜色染风帆。"]},{"t":"题谭子草玄亭","f":"七言律诗","c":["一片冰心隔市廛，闲来卜筑帝城偏。","翛然虚室能生白，率尔挥毫学草玄。","径外小桥澄水木，檐前远岫澹云烟。","问奇载酒谁同醉，妙趣休将醒者传。"]},{"t":"避署露坐书怀二首","f":"七言律诗","c":["避暑闲门向晚扃，乘凉披露坐虚庭。","微官远愧山中相，浮客空嗟水上萍。","关塞怀人遥对月，干戈闻报暗占星。","疮痍未息豺狼斗，时事年来不□□。"]},{"t":"闲居杂诗二十首 其一","f":"五言律诗","c":["日日可休沐，高斋常晏如。","卧游半壁画，坐隐一床书。","岁月闲中永，宾朋病后疏。","门前春草合，谁识散曹居。"]},{"t":"闲居杂诗二十首 其二","f":"五言律诗","c":["叩门云落帽，知是远山僧。","且洗风尘足，休论大小乘。","龙难藏一钵，鼠已啮孤藤。","借问西来路，如君到未曾。"]},{"t":"闲居杂诗二十首 其三","f":"五言律诗","c":["春残花落深，乘兴共登临。","翠柳摇佳色，黄鹂复好音。","游人看断续，天气半晴阴。","寄谢采桑妇，谁轻南陌金。"]},{"t":"闲居杂诗二十首 其四","f":"五言律诗","c":["下帘授老易，细雨洒庭虚。","往事据梧外，闲心散帙馀。","花飞春渐老，懒与世弥疏。","幸接东邻子，高文一起予。"]},{"t":"闲居杂诗二十首 其五","f":"五言律诗","c":["侯家连戚畹，裘马气翩翩。","系腰丈二组，门依尺五天。","已誇金作穴，宁惜埒铺钱。","却笑南邻客，安贫学草玄。"]},{"t":"闲居杂诗二十首 其六","f":"五言律诗","c":["驱车出广陌，道遇斗鸡儿。","上巳催游兴，春光正尔时。","墙外鞦韆影，桃李路傍枝。","可是王昌侣，香风处处随。"]},{"t":"闲居杂诗二十首 其七","f":"五言律诗","c":["桑落长年悲，秋风日夜吹。","未将云作液，那免鬓成丝。","笑酌三杯后，陶然百不思。","刘伶与阮籍，生愧不同时。"]},{"t":"闲居杂诗二十首 其八","f":"五言律诗","c":["弱心馀一寸，载得许多愁。","久客年为日，远书春到秋。","天寒邻杵急，木落晚蝉稠。","渐觉凉衿薄，中宵搅敝裘。"]},{"t":"闲居杂诗二十首 其九","f":"五言律诗","c":["闲来无一事，永日坐观棋。","谱外传神秘，机深下子迟。","手谈浑不语，柯烂已多时。","自得仙家趣，人间未许知。"]},{"t":"闲居杂诗二十首 其十","f":"五言律诗","c":["习静高斋久，沈屙尚未消。","移床安药臼，傍竹结茶寮。","羸病宜跨鹤，疏慵好弃瓢。","后来漆园吏，幽意在逍遥。"]},{"t":"闲居杂诗二十首 其十一","f":"五言律诗","c":["远蹑西风上，层城独眺间。","霜威初变柳，雾气欲沈山。","泪逐南云落，心随早雁还。","可怜三径处，芳草锁柴关。"]},{"t":"闲居杂诗二十首 其十二","f":"五言律诗","c":["客到征诗债，人来索药钱。","苦吟侵瘦骨，旅食又经年。","苏晋斋偏醉，维摩病是禅。","无生欲有寄，何处问诸天。"]},{"t":"闲居杂诗二十首 其十三","f":"五言律诗","c":["睡癖非全懒，黄庭落枕中。","谷神元寂静，火候在虚空。","天上朝群帝，淮南忆八公。","玉京眇何许，遥隔片云红。"]},{"t":"闲居杂诗二十首 其十四","f":"五言律诗","c":["读罢古思边，虚堂片月悬。","光浮乌鹊外，影落绣帏前。","怨妇思朝暮，征人自岁年。","刀头空有问，破镜几时圆。"]},{"t":"闲居杂诗二十首 其十五","f":"五言律诗","c":["九日登高处，西山最上头。","乡关疑在眼，云物不胜秋。","鼓角侵胡塞，烽烟绕汉州。","穷边多老将，念尔未封侯。"]},{"t":"闲居杂诗二十首 其十六","f":"五言律诗","c":["狐兔晚骎骎，秋郊草正深。","呼鹰看侠少，喜猎见童心。","聚饮收残网，论功索赐金。","官閒无薄禄，不愧伐檀吟。"]},{"t":"闲居杂诗二十首 其十七","f":"五言律诗","c":["剥啄不相呼，庭除长绿芜。","病因书是癖，人与古为徒。","诗赋穷诸体，波澜障别途。","沈思何所似，铁网取珊瑚。"]},{"t":"闲居杂诗二十首 其十八","f":"五言律诗","c":["吴越连三楚，东南半陆沈。","奔涛万壑斗，野哭四天阴。","蜃气空成市，龙宫直傍岑。","商霖殊太急，尧警若为心。"]},{"t":"闲居杂诗二十首 其十九","f":"五言律诗","c":["南国泪如雨，滇池血作波。","沈冤天地老，新魂岁时多。","谁念向隅泣，还闻鼓缶歌。","黄金台上草，莫遣野麋过。"]},{"t":"闲居杂诗二十首 其二十","f":"五言律诗","c":["扶筇到远寺，为赴老僧招。","谈柄挥松叶，清羡煮菊苗。","月凉如坐水，梵响似闻潮。","白业非难就，青山信可骄。"]},{"t":"银河","f":"五言律诗","c":["终古贯天经，迢遥浅更清。","雨云空自变，风浪静无声。","一水盈盈阔，双星夜夜情。","谁持河畔石，再去问君平。"]},{"t":"戊申七夕旅思","f":"五言律诗","c":["万感集萧辰，羁怀难具陈。","还因牛女会，远忆别离人。","雨霁火云歇，天空秋气新。","宦游今十载，依旧阮家贫。"]},{"t":"寄友人读书西山野寺","f":"五言律诗","c":["扰扰红尘地，思君在翠微。","游人不到处，幽鸟亦忘机。","碧草摇书带，秋风脆芰衣。","竹窗休早掩，时有白云归。"]},{"t":"讯米君梦病","f":"五言律诗","c":["傲骨缘诗瘦，腰存尚几围。","空囊还药里，细雨问秋衣。","委巷余衰草，何人到叩扉。","维摩元示病，知汝悟禅机。"]},{"t":"送陈仪翔年丈之抚州司李","f":"七言律诗","c":["相逢暑雨对闲扉，送别长亭叶又飞。","易水寒风飘客泪，蓟门秋色上征衣。","临川词赋谁堪继，贾谊才名世所希。","莫道苦吟支瘦骨，知君战胜自能肥。"]},{"t":"邻砧","f":"五言律诗","c":["寒入燕山树，清砧满四邻。","声回缠戍角，风过乱边尘。","驿使音书断，交河梦寐频。","晚来休太急，隔院有离人。"]},{"t":"初秋社集同用飞花二韵 其一","f":"五言律诗","c":["华馆辟风扉，疏林澹晚辉。","星随座密叶，叶共羽觞飞。","秋色清于酒，云光薄似衣。","良宵须尽兴，明月待人归。"]},{"t":"初秋社集同用飞花二韵 其二","f":"五言律诗","c":["万里同为客，停杯感岁华。","西风吹片月，秋思在谁家。","夜久移桐影，谈深落烛花。","明河清且浅，好泛斗边槎。"]},{"t":"施隐君诗","f":"七言律诗","c":["深居何异武陵津，一片闲云自在身。","沮溺偶随南亩隐，羲皇聊寄北窗人。","流年可叹如朝槿，上古谁云有大椿。","借问辽东仙鹤去，归来城郭几回新。"]},{"t":"镜园秋集同用闻山二字 白露前二日 其一","f":"七言律诗","c":["落日高台对晚醺，芳尊同调自为群。","红尘水外隔朝市，清籁林间净听闻。","野鹤迎秋新警露，远山横翠半沉云。","可怜一片空明界，塞北江南■未分。"]},{"t":"镜园秋集同用闻山二字 白露前二日 其二","f":"七言律诗","c":["鸥鸟还输隐吏閒，馀酣矶畔漱潺湲。","坐来白石清流里，疑到三湘七泽间。","夕网鱼虾翻几案，秋风蒪脍忆乡关。","扁舟径可如张翰，词赋何须学子山。"]},{"t":"赋得落叶惊残梦","f":"五言律诗","c":["旅次依荒驿，山空静不闻。","孤眠愁夜永，假寐逼宵分。","木叶响如雨，阳台散片云。","亦曾传綵笔，拟制宋生文。"]},{"t":"赋得钱塘潮排律十六韵赠钱塘卢生","f":"五言古诗","c":["曾向钱塘渡，烟销一镜开。","潮头忽以至，地轴仄将摧。","赤日飞睛雪，青天起暗雷。","龙宫银作阙，鲛室玉为堆。","组练疑横海，帆樯似泛罍。","属娄光欲动，强弩势难回。","东奔翻禹穴，南去蹴苏台。","吐吸谁为此，陶钧力大哉。","湖山澄秀气，越峤挺雄才。","羡汝江边住，潮从笔底来。","放歌摇彩鹢，弄月进霞杯。","一击踰千里，相期在九垓。","钓鳌偏有兴，向若敢轻猜。","赋就水皆立，文成木尽灾。","沉思牵铁网，佳句剖珠胎。","近诧观涛作，前身或姓枚。"]},{"t":"出都门风沙大作","f":"五言古诗","c":["南飞本弱羽，复被风沙欺。","咫尺不辨人，驱车将安之。","宾朋饯远郊，执手伤路岐。","呜咽不能语，仰视浮云驰。","浮云捲长风，飘散无定期。","回首望春明，顷刻即天涯。","臣心如皦日，匪石不可移。","怀人兼恋阙，立马且迟迟。","赠言同心者，努力崇令规。"]},{"t":"渡白沟河","f":"七言律诗","c":["秋暮驱车古战场，平沙宿莽浩茫茫。","乾坤易位惊龙斗，汗竹无人记国殇。","流水不随魂共去，野燐应与月争光。","楚些歌罢阴云起，萧飒悲风啸白杨。"]},{"t":"鄚州晓发","f":"五言律诗","c":["叶响树冥冥，侵晨出远坰。","河低斜浴日，炬落难残星。","野寺钟初歇，谁家梦未醒。","不如岩下叟，白昼掩柴扃。"]},{"t":"河间逢九日","f":"七言律诗","c":["莽莽寒原草木腓，登临无地怨斜辉。","他乡节序仍黄菊，古驿壶觞有白衣。","上垄暗伤槚松冷，插萸还念弟兄稀。","愁来莫听关山曲，人隔关山梦已归。"]},{"t":"高唐道中晚望","f":"七言律诗","c":["齐右流风想至今，幽怀寥落起孤吟。","南还暂断思乡泪，北望仍悬恋阙心。","禾黍收残寒雀少，牛羊归去野烟深。","绵驹歌后无人续，愁听村原处处砧。"]},{"t":"管仲三归台","f":"古风","c":["君不见晏子狐裘三十年，管家台榭势连天。","时来各展经纶手，世往空馀草木烟。","一奢一俭何须数，共作荒山一抔土。","霸气雄心浪自矜，景桓芜没无丘墓。","始信吾儒自有真，更将小见笑齐人。","南辕重拜三迁地，碧瓦朱甍岁岁新。"]},{"t":"滕县遇雨","f":"五言律诗","c":["催归秋思急，风雨转凄凄。","湿气沉烟火，潢流断路溪。","郊原浑欲晦，乡国望逾迷。","错报黄昏候，隔林闻午鸡。"]},{"t":"徐州道中即事","f":"七言律诗","c":["残照萧萧怪鸟鸣，飞蓬吹断旅魂惊。","山空不见盘龙气，台古犹存戏马名。","破屋几家频荷锸，冲波三面齧危城。","可怜万顷膏腴地，水落沙平草自生。"]},{"t":"范增墓","f":"七言律诗","c":["玉斗鸿门似雪飞，老臣骸骨竟东归。","龙文已识随真主，剑舞何须动杀机。","成败当年浑大梦，江山终古对斜辉。","休嗟荒墓多樵牧，曾见人耕汉帝畿。"]},{"t":"濠梁驿","f":"五言律诗","c":["濠梁当驿道，风景近何如。","无复高贤迹，频经过客车。","人亡应化蝶，水长更生鱼。","侧想逍遥意，临流一浣裾。"]},{"t":"凤阳晓征","f":"七言律诗","c":["侵星晓发渡淮河，落叶迎霜拂马过。","远山残烧明如月，旷野浮烟涌似波。","潘岳正伤年鬓改，杨朱堪叹路岐多。","劳劳半世成何事，欲向岩栖制薜萝。"]},{"t":"度北峡关作效谢灵运体","f":"五言古诗","c":["北土多平原，旷望弥宇宙。","南行入舒城，始觉群峰辏。","烟岚锁山门，岌巀土囊口。","入之骇心魄，万状无不有。","曲径剧羊肠，危峦压马首。","稠迭若赑屃，连接如携手。","溪回水懒流，天窄岩转陡。","怪石献殊姿，蹲立像人兽。","宿瘤与疥驼，未足仿奇丑。","树杪见人家，云中听鸡狗。","山魈并木魅，狞目楼林薮。","悲风黑处来，万穴尽啸吼。","束峡镇雄关，关门仅如斗。","峻疑五丁凿，崄出三蜀右。","一夫荷戈立，百万失驰骤。","吾闻世有道，四夷自为守。","凉德弃人和，殽函竟谁有。","时事近多艰，豺狼满墟囿。","我行逢岁晏，旅况动制肘。","气寒风水涩，路远僮仆瘦。","迷朦误东西，错莫乱昏昼。","回驭愧王阳，寸心翻自疚。","嗟予谬通籍，已落十年后。","临关虽弃繻，偃蹇仍墨绶。","既忝耳目司，何以酬敷奏。","袖中五色石，安能补天漏。","人运无百年，清霜入蒲柳。","石火倏留光，谁复跻上寿。","近耻鸡鹜群，远忆希夷友。","丹砂庶可学，玄牝亦可叩。","息踵踵常安，内视视乃久。","停车问关吏，倘遇青牛叟。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其一 楼上","f":"七言律诗","c":["百尺危栏倚翠眉，天风吹动绣罗衣。","孤高直对嫦娥阙，缥缈平攀织女机。","月下时闻箫一弄，春来还见燕双飞。","寄言芳岁须行乐，金谷迷楼事已非。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其二 桥上","f":"七言律诗","c":["谁道长虹有美人，游鱼争识晓妆新。","佳期岂待招灵鹊，微步偏怜赛洛神。","濯濯金莲初出水，盈盈罗袜不沾尘。","采芳拾翠闲来往，珍重休过妒妇津。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其三 马上","f":"七言律诗","c":["借问纤腰大几围，娇跨骏马弄春辉。","不随暮雨朝云去，却作追风逐电飞。","红粉残香沾汗血，桃花浅色上绯衣。","五陵年少相逢处，共道明妃塞外归。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其四 镜中","f":"七言律诗","c":["湛湛菱花绝点埃，双双宝靥笑颜开。","远山忽向湘波现，孤影疑从月殿来。","金鹊难逢张敞笔，綵鸾空忆太真台。","清心一片寒如水，为报君王且莫猜。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其五 舟中","f":"七言律诗","c":["香风送上木兰船，水映红妆更可怜。","西子锦帆遥出浦，赵姬新曲正怀仙。","烟销菡萏偏能语，沙媛鸳鸯不独眠。","日暮轻桡徐转去，紫骝多在绿杨边。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其六 帘中","f":"七言律诗","c":["伎衣摇曳挂雕楹，彼美娉婷隔夜明。","不见玉颜翻舞袖，但闻檀板度歌声。","珠光欲滴巫山雨，烛影空垂楚殿缨。","芳宴渐阑浑似梦，满堂实客若为情。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其七 月下","f":"七言律诗","c":["月度空庭鹊绕林，美人闲立罢清砧。","欢娱正忆乘鸾舞，幽怨长悬窃药心。","万里关山人杳杳，双星河汉夜沉沉。","刀头破镜何须问，近日辽阳绝信音。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其八 灯下","f":"七言律诗","c":["灿烂银缸照玉人，残妆未卸翠蛾颦。","九微忍看膏成泪，五夜谁怜影伴身。","鸳帐承恩他日梦，灯花送喜近来频。","君心好似光明烛，长信昭阳本隔邻。"]},{"t":"舆中无事赋得美人三上三中三下诗共九首 其九 花下","f":"七言律诗","c":["懒出芳郊逐伴游，惜花巡槛漫夷犹。","宝妆檐下因谁点，玉笛池边为你留。","独对天香矜国色，难将红雨洗春愁。","不知情绪还多少，戏蝶狂蜂舞未休。"]},{"t":"秋杪渡浔阳怀古","f":"七言律诗","c":["尘迷马首暂停鞭，倚棹浔阳兴■然。","久客乍逢卑湿地，轻帆遥挂泬㵳天。","丹枫洲上空明月，流水声中忆旧弦。","借问秋江多送别，几人能似白家船。"]},{"t":"重游东林寺迟袁伯益不至","f":"七言律诗","c":["春风驻马曾游地，往事悠悠已四年。","古刹残僧非旧主，香炉睛色又新烟。","请看客鬓同黄叶，可悟禅心是白莲。","惆怅登临虚夙约，美人迢遁隔江天。"]},{"t":"夜宿卢山下通远驿闻夜泉作","f":"七言律诗","c":["静听鸣泉滴翠微，随风飘洒数仍稀。","泠泠窦迸流云出，飒飒声悬落叶飞。","欹枕忽惊深夜雨，呼童还觅旧寒衣。","西窗一洗尘劳梦，四十年前尽觉非。"]},{"t":"皂口问渡","f":"五言律诗","c":["天窄群峰逼，翻愁倒日车。","马头冲鸟道，云脚挂人家。","壑抱三冬暖，林开十月花。","高滩问渡处，何异斗边槎。"]},{"t":"乌兜夜雨","f":"五言律诗","c":["问津绕皂口，旅宿又乌兜。","落叶迷官路，流云锁驿楼。","风悲闻虎啸，月黑共猿愁。","向夕还微雨，羁怀不可收。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其一","f":"七言绝句","c":["青山万迭锁回溪，花发源深客自迷。","啼鸟渐阑春寂寂，樵歌远山竹林西。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其二","f":"七言绝句","c":["云气淋漓不可收，山腰洞穴有龙湫。","高田数顷无忧旱，夜夜泉声屋上流。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其三","f":"七言绝句","c":["万丈峰头架石桥，微闻鸡犬落青霄。","耕耘休课儿孙辈，雨过黄精自发苗。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其四","f":"七言绝句","c":["山间自有四时花，霜后丹枫艳似霞。","昨过西岩汲新水，邻家又送小春茶。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其五","f":"七言绝句","c":["晚禾收罢散鸡豚，浊酒时携过近村。","野老不知尧舜力，别开深洞创乾坤。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其六","f":"七言绝句","c":["枕上飞泉响四山，万花如雨水潺潺。","醒来已向山灵语，不许飘花到世间。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其七","f":"七言绝句","c":["绳床窗下自眠云，巢许元来不事君。","新造松花春酿熟，开尊烧笋醉斜曛。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其八","f":"七言绝句","c":["稚子骑牛过野坡，自吹横笛和山歌。","柘弓射雉归来晚，犹说前冈兔更多。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其九","f":"七言绝句","c":["闻道城中数万家，暑深如火气蒸霞。","何如濯足溪潭里，闲数游鱼踏白沙。"]},{"t":"行赣州道中爱其山川丛僻田家茅屋半带云烟拟作隐居诗十首以寄幽怀倘他年解组便可山斋实事非浪语也 其十","f":"七言绝句","c":["雪压浮桥玉树孤，叩门邻叟共携壶。","陶然已到羲皇世，不数香山九老图。"]},{"t":"度庾岭","f":"五言律诗","c":["踏云循石磴，路仄水潺潺。","万里常为客，十年频度关。","人归鸿雁后，身老利名间。","却笑宦游子，不如山鸟闲。"]},{"t":"过平圃谒张文献墓作","f":"五言古诗","c":["文献千秋人，埋玉兹山麓。","墓门翳寒萝，野鸟啼如哭。","缅惟天实际，阳精被阴黩。","竟以雨淋铃，滴碎霓裳曲。","西蜀路崄巇，日车几翻覆。","忠言不见用，坐受蒙尘辱。","风度虚尔思，公已沦幽谷。","石椁谁勒铭，金鉴犹存录。","贞魂化日星，地下宜朝烛。","鹑火万古翔，高名系其足。","我来孟冬初，霜露气清肃。","落叶迸东流，感此世代速。","人生孰不死，要择所归宿。","忠正自英英，奸佞徒碌碌。","展拜仰清芬，庶以执予躅。"]},{"t":"集祁恒季香雪斋玩梅","f":"七言律诗","c":["万竹侵沙一径微，疏枝冉冉弄晴辉。","堂空正可容香入，冬暖番惊有雪飞。","宅似孤山斜傍水，人同东阁晚开扉。","迎年物色催残腊，相对那能不醉归。"]},{"t":"元夕前四日余将之官留垣韩圣期韩孟郁苏汝载谭公谨诸子过集珠江舟中玩月同赋用青字","f":"七言律诗","c":["相逢柳眼似人青，潦倒江干任醉醒。","浪迹未能同野鹤，深杯还欲引沧溟。","坐来星月当筵满，歌动鱼龙倚棹听。","南北岐途浑大梦，不须愁问短长亭。"]},{"t":"元夕珠江宴集","f":"七言律诗","c":["一别珠江已十春，重游烟景逐年新。","尊前鳌涌疑无地，海上羊归若有人。","四面波光摇绿酒，万家歌管隔红尘。","清酣欲问蓬山路，不记金门侍从臣。"]},{"t":"登舟留别姚巽卿","f":"七言律诗","c":["去燕来鸿两不群，将归惆怅晚逢君。","苍龙锈涩寒无语，白雪声高旧有闻。","解组欲裁平子赋，怜才谁荐长卿文。","离心摇曳空江上，愁见孤帆挂片云。"]},{"t":"发新林浦","f":"五言律诗","c":["楼船摇五两，倏忽过新林。","秋色拖枫浅，江声入荻深。","皇都他日梦，乡国此时心。","远愧忘机鸟，鸣榔起越吟。"]},{"t":"过采石","f":"五言律诗","c":["自从羁薄禄，采石几经游。","月吊袁宏艇，山含李白楼。","浦凫惊客散，江水促年流。","何事登临懒，风岸畏听秋。"]},{"t":"天门山","f":"五言律诗","c":["两岸天门辟，高崖不可攀。","相看如对语，并立迥临关。","吴楚地交错，帆樯日往还。","江流何太急，渔父自閒閒。"]},{"t":"秋江夜泊寄怀吴翁晋孙燕诒","f":"七言律诗","c":["秋林落叶不堪闻，野戍维舟静夜分。","明月窥篷如笑客，寒潮摇梦远寻君。","兰心尚记灯前语，雁使难逢海上群。","为问湖山终日待，更谁尊酒共论文。"]},{"t":"芜湖矶","f":"五言律诗","c":["湖色蘼芜遍，秋怀满水滨。","欲将三国事，更问蜀夫人。","古庙邻鲛室，灵风后海神。","挂帆遥酹酒，为我导迷津。"]},{"t":"河口镇阻风","f":"五言律诗","c":["狎鸥同水宿，晚棹泊枫林。","鹢首冲涛急，樯边落叶深。","行藏难自料，倚伏固相寻。","一雁临流意，方知不竞心。"]},{"t":"江边野老","f":"五言律诗","c":["白凫如野老，蓬户映江开。","静听潮消长，坐看云去来。","鱼虾频入网，风月自迎杯。","对尔思严濑，清波绕钓台。"]},{"t":"荻港扬帆","f":"七言律诗","c":["枫叶飘飘尽向东，危樯五两舞高空。","锦帆已化双飞翼，画角长吹万里风。","残荻离披鸣柁外，乱山争度捲帘中。","多情屏翳能相引，莫叹乡关隔断鸿。"]},{"t":"秋岸芦花歌","f":"七言古诗","c":["芦花两岸堆成雪，旅客怀归心欲绝。","轻棹如浮剡曲舟，开尊似坐瑶池月。","年华随水向东流，芦荻无心亦白头。","正苦征鸿偏怨夜，翻憎络纬竞吟秋。","芦花飞去如蓬转，乡路微茫水深浅。","村童莫更□笳吹，恐惹边风入柳枝。"]},{"t":"夜听橹声歌","f":"古风","c":["滩声潺潺如急雨，渔子罟师隔江语。","月钩瓜破遥村烟，何人摇橹西岩边。","喔喔悠扬鸣复息，江长日暮愁无力。","摆浪休惊龙女宫，轻音似学鲛人织。","忆昔吴儿白苧衣，兰桡一道唱歌归。","香风艳月随船转，?玉鸳鸯逐隧飞。","旧游如梦长洲苑，橹声今夜肠堪断。","惆怅江湖道路难，劳劳搔首已更阑。","百年谁是长閒者，愿买扁舟理钓竿。"]},{"t":"秋江杂咏六言三首 其一","f":"古风","c":["最爱垂杨系艇，溪明白石无坭。","向晚携壶泛月，芙蓉十里平堤。"]},{"t":"秋江杂咏六言三首 其二","f":"古风","c":["雁阵连空没云，江楼倚槛斜曛。","吹笛谁家思妇，无书远寄夫君。"]},{"t":"秋江杂咏六言三首 其三","f":"古风","c":["已怪鸿南燕北，更嗔芦白枫丹。","露下千山似洗，沙边孤棹偏寒。"]},{"t":"四时宫怨四首 其一","f":"七言律诗","c":["御道如弦永巷开，翠华何日复重来。","泪痕暗滴连宵雨，车响遥闻别院雷。","天上兰花空入梦，门前竹叶岂为媒。","夜阑独对金莲烛，一寸丹心一寸灰。"]},{"t":"四时宫怨四首 其二","f":"七言律诗","c":["并蒂花开水殿红，披襟难待大王风。","朝朝闭舌防鹦鹉，夜夜研砂饲守宫。","桂阙有心偷药去，阳台无路倩云通。","相如没后词人少，买赋年来恨未工。"]},{"t":"四时宫怨四首 其三","f":"七言律诗","c":["静听鸿声度苑迟，夜长惟有妾先知。","明河远隔三天水，凉月孤悬百子池。","鸳瓦暗惊霜信早，铜仙偏浥露华滋。","时来各有承恩日，寄语芙蓉好自持。"]},{"t":"四时宫怨四首 其四","f":"七言律诗","c":["积雪长门几尺深，冬衣制就罢清砧。","有情不敢轻题扇，多病那能学捧心。","西苑腊回银箭急，南宫歌歇玉绳沉。","辟寒无分留温室，空抱君王旧赐金。"]},{"t":"偶有所见戏作江楼秋怨","f":"古风","c":["采莲无伴到芳洲，闲踏西风倚小楼。","愁向栏前看逝水，遥从天际认归舟。","飞飞鸂?还成耦，袅袅芙蓉不耐秋。","欲取琵琶弹旧恨，月明何处是江州。"]},{"t":"江雨独酌谣","f":"七言古诗","c":["高浪汹汹风索索，雨脚斜连鸥鹭脚。","繁声碎响乱鸣篷，恰如一部钓天乐。","浦外渔歌对客船，买鱼赢得槎头鳊。","蒪丝菱角俯可拾，一醉啸破江中烟。","世间万事无不有，浮云白衣忽苍狗。","明日阴睛那得知，千钟一石休停手。","君看长安马足坭，何如听雨舟中酒。"]},{"t":"大姑小姑歌","f":"古风","c":["娉婷谁家妹与姊，盈盈独立波光里。","日月悬为宝珥珠，江湖泻作金盘水。","摩天浩气凛如神，化石刚心终不死。","星宿摇摇起暮风，吞舟鱼眼映波红。","洪涛震荡撼山岳，大地倾仄随蛟龙。","奔雷急雨助阵势，海若天吴偏意气。","二姑微步蹴龙宫，江天万顷俄晴霁。","君不见钱塘强弩射潮头，佽飞拔剑鬼神愁。","临危各展英雄手，贾勇更属裙钗流。","我来酹酒遥下拜，奕奕灵旗动光怪。","铁肝一掬矢神明，砥柱千秋镇长在。","谁逐颓波走世尘，狂澜一倒甘沉沦。","空存七尺称男子，枉具须眉愧妇人。"]},{"t":"风雨过鄱湖","f":"七言律诗","c":["飞鸢鸣鹳满鱼梁，怪底篙师太著忙。","帆侧湖山如箕荡，雨昏天水更微茫。","共传南斗能司命，任尔阳侯自作狂。","却笑轻躯同一粟，十年来往犯垂堂。"]},{"t":"过湖后喜晴","f":"七言绝句","c":["雨中堤柳亦含颦，雨后湖光转觉新。","织月一钩催进酒，买鱼遥唤隔江人。"]},{"t":"过鄱湖后遥望五老峰","f":"七言绝句","c":["雨气湖光暗不分，天边五老尽骑云。","尘缨未濯矶头水，来往年年愧此君。"]},{"t":"南昌樊孟泰明府招饮滕王阁雨不果上移酌舟中即席赋","f":"七言律诗","c":["高阁迎寒罢胜游，栋云帘雨洒孤舟。","星移物换悲前代，南浦西山又报秋。","千里交情堪下榻，双龙佳气自连牛。","风流为政还多暇，愿借仙凫到十洲。"]},{"t":"谑言诗","f":"古风","c":["祗须瞢董湖涂，莫说之乎者也。","直木先寻斧斤，立仗惟闻暗哑。","痴呆纪湄养鸡，祸福塞翁失马。","半夜蕉鹿非真，四大形骸都假。","岑楼寸木反高，得车■痔愈下。","为岂枉尺直寻，功在画墁毁瓦。","下里曲奏同声，阳春调孤和寡。","将携雄剑双龙，击碎唾壶一把。","流言可中姬旦，非罪谁明公冶。","傲骨只合昂藏，好官彼甘唾骂。","狐妖已诧据城，鼠匿奚容熏社。","阮籍嫉时眼白，元礼何辜衣赭。","世途不啻羊肠，宦达真同土苴。","知止知足久长，苟合苟完聊且。","既悟鸟尽弓藏，何用回车泪洒。","招龙宁在菜圃，索骏惟之冀野。","陶公三径未荒，淳于一石堪泻。","好月好风当邀，闲是闲非休惹。","老性不改姜桂，美材任舍梧槚。","阳虎或类宣尼，宫黝亦似子夏。","肉眼必有遗珠，簧口徒工炙輠。","翻波终泾渭分，斜日非贤圣打。","谁知百代鼓吹，只在片言风雅。","雅女羞隙需媒，玉不求沽待贾。","鲲鹏奋翼垂云，燕雀依人贺厦。","岂如急马缰收，莫待临崖身舍。","请看萧艾共焚，不异鱼虾并鲊。","秉烛聊效狂言，覆辙示诸迷者。"]},{"t":"南浦夜雨","f":"七言律诗","c":["寒潮乱拍滕王阁，暮雨横江呼鹊鹤。","江豚拜浪长比人，芙蓉玉箸双双落。","乱苇残葭水外看，秋衣未制已迎寒。","孤舟无客谈秋水，蓬响江声怨夜阑。"]},{"t":"舟泊南昌希举彦成两王孙移酌泛月作","f":"七言律诗","c":["倾盖论文一夕间，十年意气早相关。","主宾敢擅东南美，词赋仍兼大小山。","月满江天连酒湛，风清鸥鹭似人閒。","从来此地分龙剑，惆怅征帆发晓湾。"]},{"t":"临江中秋篇","f":"古风","c":["去岁泛园池，共掇中秋月。","今当秋色半，倚棹江天阔。","江天池水雨茫茫，水底骊珠一色光。","南国仙舟看郭李，西江旅泊叹参商。","江流去去秦淮曲，想像银蟾摇绿玉。","怨入蒹葭夜正长，书稀鸿雁肠难续。","蒹葭鸿雁不胜愁，惆怅嫦娥耐九秋。","罗绮谁家秦女管，关山几处庾公楼。","高楼急管宜秋兴，不及澄江如练净。","鲛室迎潮泪满绡，湘妃抱瑟妆临镜。","绡可裁衣镜可窥，镜中岁岁换容辉。","淩空正忆鸳鸾侣，绕树还惊乌鹊飞。","飞飞乌鹊天边急，风高露重铜仙泣。","商妇何须红袖弹，迁人自觉青衫湿。","江中碎月散流金，坐久凄凄玉露深。","袁宏咏史无人听，枚叔观涛郁壮心。","且按绿琴成苦调，更骑黄鹄觅知音。"]},{"t":"十六夜金川驿","f":"七言律诗","c":["金川澄彻见龙宫，更胜南楼月色中。","桂影岂缘今夜减，秋光还与昨宵同。","疏星点点运渔火，长笛声声叫塞鸿。","青女不须先送冷，有人江阁倚西风。"]},{"t":"十七夜玉峡驿","f":"七言律诗","c":["南方白露未为霜，单裌秋衣爱晚凉。","天上片帆飞玉峡，月中孤影坐银潢。","潮消龙女堪垂泪，秋老嫦娥渐卸妆。","叹逝怀人当此夜，关山寒色更苍苍。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其一 谢公墩","f":"七言律诗","c":["草绕荒墩客到稀，谢公馀韵使人思。","白云明月归何处，著屐登山忆往时。","风鹤数声闻退虏，废兴千古笑残棋。","诸君剩有遨游兴，胜地携尊好对谁。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二 桃叶渡","f":"七言律诗","c":["渡头风急打回潮，桃叶青青不可招。","远水正怜牛与女，轻舟何用鹊为桥。","烟波往事成今古，云雨当年自暮朝。","最是多情欢会地，离怀回首冷萧萧。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其三 梅花水","f":"七言律诗","c":["翠羽空山哢早春，一泓清水写花神。","新妆乍对含章镜，微步应消洛浦尘。","曲涧浮来香冉冉，疏枝影落石粼粼。","江南景物长相忆，谁寄罗浮岭外人。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其四 冶城","f":"七言律诗","c":["城荒古木郁孤峰，返照浮烟紫翠重。","匠去垆边无宿火，剑飞天外已成龙。","二都声价留空匣，六代河山罢战锋。","寄语群星时聚会，斗间休遣白云封。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其五 莫愁湖","f":"七言律诗","c":["水映双眸一片明，莫愁湖畔正含情。","春风几度虚兰桨，夜月千秋对石城。","绿鬓尚馀芳草色，清歌散入野禽声。","到今谁是消愁者，休笑卢家浪得名。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其六 孙楚楼","f":"七言律诗","c":["酒泉何用觅封侯，最爱参军旧日楼。","岁岁提壶闻好鸟，时时开瓮筑高丘。","杯空竹叶犹摇影，客散枫林自醉秋。","人世拍浮须痛饮，知君鹔鹴还有裘。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其七 景阳楼","f":"七言律诗","c":["景阳楼阁倚高峰，珠翠帘前列几重。","狎客彩毫留夜月，妖姬丽曲乱晨钟。","春归树老庭花落，运去龙沈野井封。","自古登临多感慨，懒寻残碣问遗踪。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其八 临春阁","f":"七言律诗","c":["山腰古寺四无邻，谁信行宫乐事新。","此日寒原悲宿莽，昔年高阁号临春。","晚来霞结还成绮，望去仙妆若有人。","惆怅风流江令醉，不知人世阅梁陈。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其九 鸟衣巷","f":"七言律诗","c":["对语呢喃黯自伤，梦中王谢竟茫茫。","古槐高柳仍深巷，坭落巢空失旧堂。","当日春风褰锦幕，此时秋草对斜阳。","休誇新入人家好，若个人家是久长。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十 长干里","f":"七言律诗","c":["江左风流竞绮纨，寻芳争向大长干。","王孙宝马开金埒，士女轻桡上木兰。","晓发管□分队队，夜阑环佩尚珊珊。","自从王谢遨游后，几度春衫改旧观。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十一 献花","f":"七言律诗","c":["石磴疏松夹道斜，白云长护懒融家。","不闻高足能传钵，谁见幽禽再献花。","浮世几回悲劫火，闲僧还解说恒沙。","何时共理登山屐，同坐空岩转法华。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十二 凤凰台","f":"七言律诗","c":["凤台零落古城边，花木春深怨杜鹃。","丹穴飞归踰万里，青莲题后又千年。","遗宫废苑皆如此，怀古思乡共惘然。","休作狂歌同楚客，吹箫吾拟挟飞仙。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十三 燕子矶","f":"七言律诗","c":["曾上高亭一振衣，江边落木带斜辉。","盈盈明月随潮上，片片征帆逆浪归。","眼底吴山临岸尽，天边楚树入云稀。","休□燕子如奇石，恐学零陵逐雨飞。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十四 白门","f":"七言律诗","c":["南连驰道北通庄，明月临门皎似霜。","沈水已消前日火，栖乌今换几垂杨。","楼前调马闻琼佩，台上吹箫待玉郎。","自是江南佳丽地，游丝飞絮尽生香。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十五 新亭","f":"七言律诗","c":["晋代衣冠已草莱，新亭遗事总堪哀。","羯鼓胡角连云起，龙马銮舆渡水来。","挥麈谁云无壮士，围棋真信有奇才。","当时怪杀王夷甫，我辈谈锋莫浪开。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十六 青溪","f":"七言律诗","c":["玄湖几曲入青溪，水长侵莎渐没堤。","白鸟不惊渔子网，绿阴遥听羽人鸡。","津头石仄桥还断，渡口花深客自迷。","风月昔时移画舫，到今杨柳为谁低。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十七 秦淮","f":"七言律诗","c":["秦时王气映淮河，休道繁华逐逝波。","芳甸烟花春正好，画船箫鼓晚来多。","芙容两岸飞丹阁，菡萏中流写翠娥。","谁近酒家还夜泊，隔江重听后庭歌。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十八 邀笛步","f":"七言律诗","c":["轻调玉管倚江浔，子野风流自古今。","隔岸两人非旧识，入舟三弄即知音。","落梅曾洒临岐泪，折柳偏伤送客心。","别后关山多少恨，凭君传与水龙吟。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其十九 华林园","f":"七言律诗","c":["园林萧瑟暗惊秋，霸气东南黯已收。","弦管久随风送去，繁华惟见水空流。","台倾半入红尘陌，池废斜通绿荻洲。","游客莫嫌无故物，园丁时拾玉搔头。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十 雨花台","f":"七言律诗","c":["萦回石磴紫苔残，吴楚凭栏入望宽。","僧去不传真偈秘，客来徒把野花看。","云深竹坞睛还湿，风满松关夏亦寒。","鲁倚台边居两月，至今清梦绕长干。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十一 落星冈","f":"七言律诗","c":["携壶曾上落星冈，醉后狂呼问彼苍。","天上几时遭谴谪，人间犹自妒光芒。","飞来恐是支机石，驱去应同渡海羊。","可悟升沉皆幻迹，百年休自拟行藏。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十二 鸡笼山","f":"七言律诗","c":["不听迎潮报晓声，徒闻古寺号鸡鸣。","崇台观象星辰近，高阁凭虚沆瀣清。","雨过后湖浮翠黛，烟销双阙映葱菁。","欲寻帝子翻经处，书带萋萋草自生。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十三 三山","f":"七言律诗","c":["郭外长江江外烟，三山真见落青天。","潮翻雪屋明还灭，云荡寒崖断复连。","望去蓬壶今远近，漫劳方士访神仙。","乘秋尚忆停桡处，不信灵风解引船。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十四 八功水","f":"七言律诗","c":["山门十里度松风，笑汲灵泉忆志公。","流去可观心不住，照来还悟色皆空。","烹茶客坐春云外，洗钵僧归夜月中。","况接园陵佳气近，清波应与鼎湖通。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十五 劳劳亭","f":"七言律诗","c":["劳劳世路嗟行役，立马荒亭忆往时。","笑语临风惊乍断，壶觞分手岂重持。","大江长泻离人泪，垂柳应无旧日枝。","借问道旁来往者，骊歌几度听新词。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十六 石头城","f":"七言律诗","c":["沉沉铁锁泣寒潮，古堞吹笳夜寂寥。","踞虎虚传关王气，降旗亲见出前朝。","秋高塞雁啼霜急，风起江豚挟浪骄。","千古石头城下水，英雄流恨几时消。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十七 朱雀桥","f":"七言律诗","c":["但见长虹饮碧流，谁云朱雀集芳洲。","雕栏直接寻春路，锦水斜通拾翠舟。","鸣佩逢人疑巧夕，吹箫对月忆扬州。","六朝无限伤心事，野草桥边叶叶秋。"]},{"t":"余濒行金陵诸词客分赋都下名胜兼傅之丹青壮我行色舟中无事披册展读忽然技痒赋寄酬之共得二十八景诗如其数 其二十八 玄武湖","f":"七言律诗","c":["忆昔龙舟宴幸频，牙樯锦缆满湖滨。","筵前鱼鸟惊新曲，水上神仙拥丽人。","宫镜长悬千古月，香风吹散一洲蘋。","可怜胜地今闲却，不许兰桡再问津。"]},{"t":"巫山高","f":"楚辞体","c":["山十二兮同云隔，暮雨兮渺难分。","天既昏兮峡急，肠欲断兮猿闻。","山中人兮披霞衣，乘文螭兮翳桂旗。","为谁需兮然疑，魂亭亭兮来迟迟，鸠为媒兮鸩先之。","椒浆兮兰籍，君不御兮日将夕。","经滟滪兮下瞿塘，怅佳人兮天一方。"]},{"t":"湘水深","f":"楚辞体","c":["谁鼓瑟兮怀思？","君山落镜兮修眉。","帝子降兮北渚，竹飒飒兮潇湘雨。","魂恍惚兮合离，情含睇兮默语。","伐班竹兮吹洞箫，骑赤凤兮奏虞韶。","扫八极兮拥彗，荃独命兮皋陶。"]},{"t":"明星玉女","f":"楚辞体","c":["君杂佩兮明星，谁其侣兮许飞琼。","翩翩兮来下，倏忽兮遐征。","遐征兮安之。","托青鸟兮衔书。","叩金天兮诉白帝，猛犬狺狺兮噬予。","君池莲兮似船，愿一乘兮共洄沿。","知不可兮骤得，横流涕兮潺湲。"]},{"t":"上元君","f":"楚辞体","c":["山棱层兮十八盘，有美一人兮立云轩。","临日观兮开天门。","予将腾兮逝驾，拆芳荪兮秣予马。","羌不达予之忠诚兮，反拒予以不暇。","辛夷屋兮杜蘅房，期之子兮洁自芳。","日汛扫兮湛兰浆，不我顾兮尘凝堂。","日杲杲兮忽雨，君不来兮谁许。","牛羊晚兮下山，平芜暮兮千里。"]},{"t":"俎上翁","f":"古风","c":["俎上翁，受勒逼。","俎上肉，烹何益。","任烹若翁烹乃止，不然父子同日死。","谁云帝欲烹而翁，胡宽还见营新丰。"]},{"t":"千金报","f":"古风","c":["受一饭，报千金。","非酬母，酬寸心。","汉皇推恩重一饭，信不负母宁负汉。"]},{"t":"排墙叹","f":"古风","c":["挥麈尾，谈转清。","谋兔窟，何营营。","尚言君少无宦情。","临危乞哀仍不免，试问墙边窟深浅。"]},{"t":"博山炉","f":"五言古诗","c":["春鸟催百花，紫陌香车骛。","长安多名园，歌舞应无数。","可怪粤南客，杜门守真素。","道书行尚把，不惹春芳妒。","叩齿静漱泉，博山萦轻雾。","壶中自有天，任彼流年度。"]},{"t":"清泉钵","f":"五言古诗","c":["井花出辘轳，清彻静无滓。","洗钵贮空明，置之白石几。","澄心想天一，至味乃无味。","□洞可降龙，渊默堪洗耳。","门前红尘满，问君何能尔。","臣门虽近市，臣心乃如水。","世路多风波，吾以观其止。"]},{"t":"九鸶观","f":"五言古诗","c":["砚池一掬水，荷叶自田田。","中有九鹭鸶，唼藻何翩跹。","良工巧斫琢，几夺造化权。","石质铿清磬，墨花吐轻烟。","时关飞动意，恍惚浮青莲。","余非梦鸟客，亦异笼鹅贤。","对此皎洁姿，如游江海边。","静观齐物理，大小未云偏。","砚池即鲲溟，鹭翼可垂天。","更乘莲叶舟，卧读逍遥篇。"]},{"t":"古方镜","f":"五言古诗","c":["阴阳鼓大炉，水火相交扇。","化为双飞镜，照入大千遍。","虚室自生白，毫光粲然现。","泠泠望若空，心胆了可见。","非由魏国宫，岂出秦王殿。","虽无妆七宝，只有冰一片。","对此问形影，幻真谁复辨。"]},{"t":"古琴","f":"五言古诗","c":["首夏当清和，薰风咽新蝉。","槐阴荫广庭，秀色媚远天。","沐馀换绛帻，虚徐鼓冰弦。","一为出塞吟，堂闼如穷边。","广陵散已绝，兹法更谁传。","欲知希声意，当在无弦前。"]},{"t":"又登风度楼","f":"五言古诗","c":["朝登风度楼，城郭何绵延。","城头早日出，万井开寒烟。","目断千山外，心飞百代前。","九原今已矣，风度尚依然。","巍楼夹道衢，古墓知何处。","栋宇神鬼扶，柱石英灵聚。","招魂学楚歌，有泪风吹去。","想像放逐时，为君三痛哭。","忽闻弦管音，似听梨园曲。","笑彼开元主，间关蜀道悲。","临危识孤忠，去后枉劳思。","欲去不忍去，危栏且复凭。","沉吟白羽扇，如见赤心人。","千秋鉴不磨，可以蹑清芬。"]},{"t":"游九疑拟古二首 其一","f":"五言古诗","c":["一生耻低眉，八极纵遐想。","迩来宦况淡，自署方外长。","乘闲穷杳眇，及霁搜深广。","名山号九疑，俶诡还方状。","一登耳目骇，久涉形神王。","水石拂霜清，岩峦入秋爽。","朝旭射高峰，璀璨如银榜。","中有帝寝陵，龙气伏层嶂。","悲风日夕起，草木犹含怆。","桂酒降神时，哀哀凤凰响。","微臣吊千古，感慨增激赏。","求仙彼何人，却笑骊山葬。"]},{"t":"游九疑拟古二首 其二","f":"五言古诗","c":["人生百年内，天地总如寄。","大哉帝王居，八荒堂闼尔。","形骸有雕谢，神理无终始。","远近岂殊观，徒劳泣妃子。","沾沾妇女仁，应为达者嗤。","赢博无不可，延陵悟兹旨。"]},{"t":"集瓦官寺观竹酌赋","f":"五言古诗","c":["同人喜于野，素尚敦夙秉。","选胜到城南，顿入清凉境。","悬梦一径幽，秀竹千竿挺。","不见火龙飞，但看苍玉映。","微风度万叶，天籁自寥迥。","青浮白氎巾，绿动金杯影。","扫地坐莓苔，一片罗茵净。","伊蒲行素盘，晚饭催清磬。","夕阳斜透林，侧布金光竟。","淹留澹爽襟，宴笑开谈柄。","曰余寡谐俗，此君得吾性。","游非三湘远，迹偶七贤并。","陶然羲皇上，诸虑已尽屏。","愿截翠琅玕，吹笙踏缑岭。"]},{"t":"西园闲坐读韩城薛节妇传有感辄作长话","f":"五言古诗","c":["衙斋坐岁晏，西园草木腓。","倚石抚孤松，苍干何崔巍。","闲披薜妇传，殉夫竟同归。","激我侠烈肠，悲歌欲沾衣。","松风鸣谡谡，倒卷严霜飞。","愁云自西来，白日惨无晖。","人生孰不死，此节古今稀。","何地堪为葬，当在华山畿。","何物堪为奠，当采首阳薇。","魂缠青陵蝶，伴逐湘江妃。","昔年两掬泪，应变为珠玑。","双龙终会合，地下启重帏。","一坯掩香骨，千载留音徽。","寄语须眉子，胡多习脂韦。"]},{"t":"沐浴子","f":"五言律诗","c":["金刀裁白纻，楚楚洁衣裳。","当户兰已锄，谁为具温汤？","玉质不受染，十暑犹含霜。","乘风散发去，长啸过沧浪。"]},{"t":"门有车马客行","f":"五言古诗","c":["侯门势翕赫，气与秋天高。","结交遍海内，轩盖同游遨。","歌钟日夜起，弦管声嘈嘈。","欢呼屋瓦振，饮博各分曹。","借问堂上客，皆云五陵豪。","落花随玉舄，华烛粲珠袍。","三杯意气豁，慷慨视宝刀。","申言恩义重，泰岱轻鸿毛。","一朝人事别，田窦相倾夺。","众宾掉臂去，相弃如屣脱。","昔时歌舞地，日暮呼鸧鸹。","得宠交自深，失势情斯割。","为谢书门者，毋劳更咄咄。"]},{"t":"独不见","f":"五言古诗","c":["流水终到海，浮云岂归山。","大堤芳草绿，游子何时还？","人去曾寄衣，鸿归无一字。","锦纹终夜织，不尽心中事。","妾心长似水，君意散如云。","寥寥怯空房，梦合晓更分。","春来忆玉箫，秋后悲纨扇。","泪眼几时晴，年年独不见。"]},{"t":"长安大道行","f":"五言古诗","c":["高楼错如绣，大道平如水。","裘马彼何人，经过赵与李。","斗鸡入南坊，蹴鞠归下里。","几群珠履随，十丈香尘起。","横冲丞相车，唾骂金吾子。","自倚椒房亲，骄矜极奢侈。","一朝恩爱夺，门径生荆杞。","谁言大道平，往往催辀死。"]},{"t":"长干行","f":"五言古诗","c":["飞絮乱春心，落花侵履迹。","步出大长干，香车密如织。","油幢翠羽扇，珠箔镂金床。","争驰红尘里，环佩声琅锵。","相逢谁最好，王谢两家郎。"]},{"t":"又赋得薰风自南来殿角生微凉","f":"五言古诗","c":["青莲滴沆瀣，本是清凉界。","南薰入古殿，四座生灵籁。","胜会集群贤，披襟仍解带。","炎蒸尽洒濯，世虑归澄汰。","一为白雪吟，秋声益澎湃。","宦途苦桎梏，远引轻冠盖。","君看嘒嘒蝉，饮露得仙蜕。","列子如可作，御风期方外。"]},{"t":"立秋社集赋得木叶动秋声留别诸君","f":"五言古诗","c":["寺古册更幽，爽气金天接。","新凉入高树，萧瑟吟风叶。","轻随清磬度，微带寒蝉咽。","听之伤客心，骨冷魂先詟。","日月如车轮，徂年催急节。","孤臣不遇主，何异长门妾。","团扇自光辉，秋风难再热。","徘徊别知友，转觉临歧怯。","执手肠九回，离琴曲三叠。","折赠欲搴兰，江波眇难涉。"]},{"t":"荆轲咏","f":"五言古诗","c":["荆高两相许，击筑燕市旁。","既乐又复泣，谁知非浪狂。","怀七入秦庭，调笑轻舞阳。","其事虽不成，白虹久低昂。","追思争博日，目摄即遁藏。","借问鲁勾践，何如秦始皇。"]},{"t":"谒周濂溪先生祠","f":"五言古诗","c":["古祠即旧宅，门径清如水。","欲识濂溪心，池中白莲是。","来寻孔颜乐，自觉风月美。","吟弄意不穷，咏归兴难已。","陶陶扫静室，一悟无极理。"]},{"t":"对酒","f":"五言古诗","c":["愁心不复醒，欢伯日相召。","湖南米价贱，曲檗事未了。","摘来安石榴，粲粲何人笑。","落盘珍珠红，色映琉璃妙。","一醉解天韬，人间徒扰扰。"]},{"t":"酬区启图赠别之作","f":"五言古诗","c":["诗学为箕裘，君家美桥梓。","袖中双彩笔，惯绣天孙绮。","掷地黄金声，掀云白雪起。","咳唾自成珠，粲粲佳公子。","公子爱留宾，临歧念楚臣。","心随湘岳远，兴入杜兰新。","赠我裁骚调，凄凄泣鬼神。","郢国元无敌，巴渝岂有人。","怜余肮脏骨，落羽湖南去。","捐佩自为歌，登楼共谁赋。","徘徊黄陵庙，偃息丹枫树。","三载始一迁，哀湘仍反顾。","劳者惮长征，多君轸远情。","匣龙方对舞，塞雁忽孤鸣。","岁时行欲暮，云水递微明。","展君佳句读，遥想人如玉。","琴瑟恋知音，关塞萦心曲。","一日犹怨迟，三秋尚嫌速。","斯道若狂澜，哇声满世间。","阳春日以远，古调谁能攀。","欲把雄风赠，南溟浪似山。","何时重对酒，沿月棹歌还。"]},{"t":"五渡湘江感赋二首 其一","f":"五言律诗","c":["惯为湖南客，频渡湘江水。","鸥鸟长笑人，君忙乃如此。","老渔正濯足，晒网芦洲里。","对此感人怀，荣名翻自鄙。"]},{"t":"五渡湘江感赋二首 其二","f":"五言律诗","c":["仲冬霜气清，寒江净如镜。","未敢照须眉，试照余心性。","前波催后浪，滔滔常不竞。","回处有澄潭，十年还自定。"]},{"t":"坐含清阁下视潇江水涨喷激洲渚雷轰雪溅泠然有述","f":"五言古诗","c":["昨夜星照泥，通宵雨达曙。","潇江汇众水，欲载孤城去。","触石郁而怒，冲洲益骄倨。","喧豗震山麓，哀响彻官署。","凭栏一纵观，雪浪排银锯。","气势压吕梁，猛急过滟滪。","白龙挟素虬，共捧冯夷驭。","风波浩荡中，正轸垂堂虑。","寄言行客子，维舟莫匆遽。"]},{"t":"日长","f":"五言古诗","c":["一片竹枝阴，不容人吏足。","自从花落后，但许青苔覆。","幽居暇日长，清风时肃肃。","散发者何人，道书行且读。","虽非白眼客，已异红尘目。"]},{"t":"晓来何所爱","f":"五言古诗","c":["晓来何所爱，烟松与烟竹。","郁葱复峭茜，濯濯如膏沐。","隐几静对之，幽意两相属。","平生山林骨，浪出徇微禄。","赖有此二君，泠然伴孤躅。","扫阁一焚香，衙斋亦薖轴。"]},{"t":"赠曹能始","f":"五言古诗","c":["兰芷叶芬芳，姜桂岂殊性。","鸣玉必缓趋，由窦多捷径。","伊予与之子，侠骨有馀劲。","落落寡所谐，仕途逢叠磴。","忤人轻解组，初服寻箕颍。","猿鹤订深盟，烟霞入诗兴。","拔茅及小草，得与之子并。","神交廿馀年，声气元求应。","把臂苍梧云，两心皎如镜。","论文符雅调，失路怜同病。","三已共栖迟，千秋递为政。","咄咄厌书空，诗成聊击磬。","古人有遗训，水流心不竞。"]},{"t":"前出塞","f":"七言律诗","c":["几岁磨成三尺铁，悬弧养就一腔血。","男儿堕地气吞胡，旁人不用肝肠热。","酌罢雄生两腋风，剑冲星彩月衔弓。","君看虎头猿臂者，岂肯随人死牖下。"]},{"t":"后出塞","f":"七言古诗","c":["去岁饶歌入汉宫，上功幕府谁先容。","擒生斩馘不计数，一生力尽归纨裤。","今年烽火照咸阳，依旧身随六郡良。","行经战地认故镞，回头却向残云哭。","主将凭陵气益骄，虚闻大树风萧萧。"]},{"t":"长笛篇","f":"七言古诗","c":["月照高楼凉浸水，风刮秋衣人独倚。","湘南奇客好新弄，当窗拭袖调纤指。","此时河转众星稀，声绕琼宫高处飞。","顾兔佳人遥罢舞，临桥仙子乍停机。","曲遍人天离恨远，残梅落尽衰杨晚。","霜露空凋少妇颜，关山不见征人返。","谁家少妇歇清砧，闻笛迟回折寸心。","苦月斜连萤影度，愁云暗结雁声沉。","忽然孤愤如裂石，寒天九月驱霹雳。","鱼龙起舞鸟兽呼，侠游年少头先白。","馀音散落胡天秋，边马长嘶脱辔头。","无定河边青冢外，野磷枯骨哭啾啾。","我昔离家越两载，转眼风烟时序改。","听罢翻憎夜似年，更阑益觉愁如海。","问君此曲传者谁，宋祎子野是吾师。","搜竹行穷湘水岸，调声直写鹧鸪悲。","一吹巫峡来神女，三奏断猿浑不语。","周游湖海鲜知音，今夜胡床乘月举。","燕云缥缈接洞庭，曲终遥望楚峰青。"]},{"t":"悲笳篇","f":"七言古诗","c":["边风杀气何萧萧，牧马南来势转骄。","将军夜出弓横弰，鱼丽鹅鹳阵渐交。","不知何人吹芦管，边风乍寂黄云断。","胡兵意气涩不扬，汉卒肝肠凄欲懒。","试听其中幽怨声，咿咿怀土不胜情。","谁能一日离乡国，难舍双亲并弟兄。","凉秋九月霜华重，枕戈应有阳台梦。","塞北胭脂簇似花，关南珠翠团成凤。","封侯拜将本无期，落月归心起远思。","楚歌不救虞姬泣，笳韵宁忘越石悲。","汉卒南还胡自北，疾归两泪犹沾臆。","谁道和番用美人，只须一叶净边尘。"]},{"t":"看剑篇","f":"七言古诗","c":["夜半城头挂北斗，华堂宴客犹呼酒。","主人上将近休边，曲部金绯将炙走。","为欢不敢寿千金，请看钢锋一片心。","启匣虹霓纷缭绕，拔镡檐户冷萧森。","骤观三尺空如水，不知其内藏龙子。","恍惚苍精暗欲腾，须臾白练平吹起。","指去遥知山可崩，弹来直立天为倚。","延津波落丰城空，一时移在华堂中。","只恐妖姬幻鬼母，翻疑坐客有猿公。","侵灯闪烛乱光怪，帘外星河皆破碎。","众宾长跪请韬锋，主人更为谈边塞。","虎须半拂燕颔旋，自言擐甲十馀年。","战多剑锷光仍在，戍久马蹄浑尽穿。","麾向龙堆回落日，㔉将疏勒出飞泉。","犁庭老上魂先夺，绝幕呼韩血尚鲜。","近时塞外无骄虏，玉门关下多闲土。","马援矍铄浪据鞍，李广遨游徒射虎。","说剑雄心只自知，登坛馀勇真堪贾。","忧时叹老泪沾衣，宾主留连不忍归。","千秋欧冶今何有？","只眼张华遇者稀。","喑呜慷慨俱落魄，赌胜千金轻一掷。","匣里龙飞忽裂垣，群鸡惊叫东方白。"]},{"t":"听琴篇赠卞琴师","f":"古风","c":["羡君幽且静，调琴先调心。","示我无弦趣，徐得山水音。","此时明月方出岭，银塘雨歇澄鲜景。","帘外清风飏篆烟，林间宿鸟低花影。","主宾相对两忘言，心远神清指不繁。","恍惚离鸾临镜舞，逶迤以产绕堂翻。","堂下幽兰团白雪，又听归风催鹤别。","和弄阳春玉柱温，高张霹雳冰弦折。","长侧与短侧，大游复小游。","思归鲁女怨，送远楚妃愁。","乌夜啼时声咽咽，雉朝飞处恨悠悠。","言迟欲速皆闲雅，迟似蟹行速走马。","萧瑟松风入壑深，奔腾石峡流泉泻。","相如文采动琼环，叔夜丰神比玉山。","师旷能令玄鹤舞，琴高亲骂赤鱼还。","此君琴格尤高贵，平正优游兼果毅。","共道清泠合古音，宁知洞越含元气。","罢琴明月照房栊，人坐冰壶碧落中。","朗朗四天无障翳，寥寥五蕴尽归空。","更阑夜久客欲起，散步中庭净如水。","平生不好郑卫声，此夜洗尽淫哇耳。","肯惜知音一再弹，朝朝扫径期之子。"]},{"t":"捣衣篇","f":"七言古诗","c":["洞房环佩惊秋早，叶满空阶愁不扫。","闲来不省出门行，梦里已到交河道。","交河戍客铁为衣，八月严霜扑面飞。","可念拂沙眠塞草，何辞织锦理鸳机。","鸳机织就烦刀尺，熨斗帖平针线迹。","灯下装绵泪满床，窗前捣练风侵石。","风清月冷气凄凄，力尽繁声高更低。","捣时庭树初栖鸟，捣罢邻家已报鸡。","谁识繁声结悲咽，心中万恨凭砧说。","千里情悬落日西，双题响逐行云灭。","东家砧歇西家鸣，夜夜风来满帝城。","愁苦频年征戍急，何人不作断肠声。","衣成缄固重重意，又恐关前无驿使。","别久腰衰知带宽，路长秋寄经春至。","春去秋来貌不同，家家怨旷恨无穷。","汉皇好武何时已，愿送砧声达汉宫。"]},{"t":"长安古意","f":"古风","c":["燕甸风流胜洛阳，莺花三月绣成行。","云迎旭日连鳷鹊，霞散长虹绕凤凰。","凤凰鳷鹊临驰道，驰道杨垂玉沟草。","七贵香车佳气多，五侯珠履春光早。","侯门公子日联翩，白哲青丝傲少年。","舞榭歌台纷扑地，哀弦急管闹喧天。","一生美妾过三百，岂吝新丰斗十千。","十千三百欢娱处，醉倒红妆不知曙。","庭院偏栽夜合花，池塘尽种相思树。","相思夜合度寒宵，百态千容各斗娇。","春风飞鞚龙为马，明月横吹凤作箫。","凤箫龙马势侵云，蜀锦齐纨日日新。","腰间宝铗光流雪，头上犀簪气辟尘。","犀簪宝铗万人誇，踏絮寻芳乐事赊。","共携侠客荆高辈，遥指红楼第一家。","红楼少女孰当垆，似识真娘与薛涛。","一见清容心自醉，千金买笑价能高。","千金买笑留连久，铜盘吐蜡明如昼。","拂袖低垂弱柳腰，弹筝半出柔荑手。","柔荑弱柳不胜春，对客含羞倚绣茵。","生憎织女经年度，笑杀嫦娥不嫁人。","嫦娥织女怜孤独，忍使巫山空六六。","上客何妨脱鹔鹴，仙郎更请翻鸲鹆。","鹔鹴鸲鹆醉如泥，步入天台路易迷。","烟花洞口春方好，歌舞楼头月未低。","春来歌舞欢无已，更怀匕首临燕市。","肯拚身命若鸿毛，直把肝肠照秋水。","交通戚畹与貂珰，豪横由来不可当。","剧孟一身堪敌国，郭翁片语挫侯王。","别有权门负天宠，左平右墄相矜重。","结客批根并引绳，下交执辔兼摩踵。","家藏金穴辟铜山，异宝周搜到百蛮。","火浣侍儿皆曳地，摩尼诸婢动鸣环。","天道由来有亏损，突兀冰山愁见睍。","长信宫中斗锦鸡，咸阳市上牵黄犬。","魏其池馆静无喧，夜雨狐啼霍氏门。","可叹张罗无燕雀，何须沁水夺田园。","长安大道平如掌，几见摧轮翻道上。","贺监应思镜水波，陶君自老山中相。","已矣乎归去来，书生十载困蒿莱。","嘶风蹀躞至燕市，何时更筑黄金台？","幽兰莫道无人赏，谷底春风亦自开。"]},{"t":"长安明月篇","f":"七言古诗","c":["琉璃碾破碧云堆，仙子银屏次第开。","淡扫蛾眉安玉匣，高悬鸾镜下瑶台。","蛾眉鸾镜舒清眺，东海冰轮送秋晓。","雾幌初褰七宝妆，琼章早报三青鸟。","霓裳天乐沸云流，此夜群仙尽出游。","绿发吹笙遥跨鹤，紫箫骑风晚登楼。","曾从天路招灵鹊，更隔明河笑女牛。","女牛灵鹊佳期暮，天上人间几相误。","怅望停棱已可怜，凄凉抱兔应难度。","苍茫云水广寒空，叹息红颜闭六宫。","莫问涂黄羞满月，只将团扇怨秋风。","铜龙夜咽天河水，玉辇征歌乘月起。","流素偏归凝碧边，扬辉只在昭阳里。","五侯七贵竞繁华，风月宵宵赵李家。","红锦缠头调宝瑟，银钿击节奏琵琶。","潘安卫玠千金马，韦娘苏小倾城价。","锦帐流苏不放春，铜盘吐蜡消长夜。","荡子倡楼日易迷，归来明月已沉西。","但矜楼上冰姿好，不惜闺中玉箸啼。","别有空房二八女，征夫远赴辽阳戍。","月暗斜笼夜合花，流萤乱点相思树。","绣户秋深冷疑茵，沙场落月闪青磷。","受降城外风前笛，无定河边梦里人。","挥杯试问天边月，含情细向嫦娥说。","处处柔肠叹合离，年年香魄嗟圆缺。","合离圆缺异悲欢，才子佳人怅各天。","既催牛渚乘流句，又落江州司马船。","可厌尘寰多意绪，寒蟾为我调霜杵。","乞将灵药蜕凡胎，飞仙挟去云为侣。"]},{"t":"击剑行，送山人谭永明出塞","f":"古风","c":["有客拔剑砍地歌，怪云片片窗前过。","云横剑气化雷雨，千山欲撼沧溟波。","甲兵须挽天河洗，男儿有身岂徒死。","孟尝不识弹铗人，半醉唾骂孟尝君。","世上难逢唐举术，尘埃谁相封侯骨。","昔君结客少年场，千金散尽恣豪狂。","黄石久窥桥下秘，白猿频舞剑头霜。","只今绝塞风烟起，朝廷拊髀思颇李。","丈夫为国作长城，谁能龌龊恋妻子。","大笑长歌向燕陌，手排闺阖披肝膈。","豹虎盘胸十万兵，龙蛇绕笔三千策。","君不见，终军小竖儿，请缨欲把胡儿羁。","又不见，燕颔腐儒轻投笔，飞而食肉玉门北。","孟坚碌碌守一经，遘时且勒燕然铭。","人生功业在晚成，贫贱岂必皆愚冥。","浮杯击剑送君行，叱咤摩厉秋纵横。","朝闻尺疏动天颜，暮闻三箭定天山。","嗟嗟君去布袍蒯缑衿见肘，君归黄金紫印大如斗。","直使公侯负弩迎，更教怨妇下机走。","黄金斗印不足羡，麟阁须君图不朽。"]},{"t":"扬州花月歌","f":"古风","c":["君不见广陵潮接秦淮水，隋帝龙舟泛江沚。","锦缆云帆天上来，丛丛绿鬓烟花里。","艳曲新声度玉簧，蛾眉曼睩胜昭阳。","至今士女传遗教，偷得宫中第一妆。","岁岁踏青二三月，香车宝扇倾城发。","柳幔花茵拥丽人，碧沙锦水摇仙袜。","目眺更心招，穿堤更过桥。","赠珰怜意密，掷果怨情遥。","尽日春游欢未足，娟娟新月燃华烛。","大道青楼几百家，家家尽唱迎郎曲。","碧玉与潘安，相看两少年。","排场齐蹴鞠，对舞上秋千。","共道月明须纵酒，莫将花落恼啼鹃。","花开花落无穷已，月圆月缺人相似。","歌管常留富贵春，风光肯负繁华里。","广陵自古擅风流，夜市箫声晓未收。","不惜千金拚买笑，何须尺锦作缠头。","花月能邀词客笔，还如何逊在扬州。"]},{"t":"长安少侯行","f":"七言古诗","c":["长安大道逢少侯，传呼冠盖若云浮。","扇开翡翠明金勒，香逐旃檀控紫骝。","借问君侯年十几，仙居甲第阿那里。","笑指皇城东北陬，琼楼绮阁中天起。","自言乃祖识真龙，先建麒麟第一功。","铁券金章联奕叶，生年二八有重封。","椒房戚畹姻连理，十世分茅三尚主。","西馆金张未敢窥，东床赵李争相取。","新娶佳人十五馀，金塘春水映芙蕖。","绿珠碧玉随为媵，掩面含羞捧佩琚。","娇歌妙舞青楼晚，火树银灯霄彻旦。","帐底鸾栖楚雨浓，钗头燕亸巫云散。","平明步入明光宫，剑舄横冲豹尾中。","黄帕笼盘传赐食，绯衣中使竞趋风。","归来门巷纷车马，半揖公卿尽为亚。","灌夫骂酒寂无言，强项董宣先肯下。","豪雄意气骋遨游，七国三边不解忧。","自负魏其新得宠，谁怜李广未封侯？","锦袖珠袍摇白晢，道旁观者皆辟易。","富贵何曾识一丁，太玄闭户知何益。"]},{"t":"长安老山人行","f":"七言古诗","c":["烟霞自逐长安杖，鹤怨猿愁空蕙帐。","周猎希寻渭水竿，汉庭已厌商山相。","耳聋不觉市朝喧，日暮愁过七贵门。","秋色迎寒貂已敝，谈锋罢战舌犹存。","近来年少气如云，眼底绨袍孰识君。","堪叹出山泉水浊，当年未读北山文。"]},{"t":"丛竹歌为黄敦柱年丈赋","f":"古风","c":["火旗焰焰行高天，迸泉驱汗气如烟。","我来解带虚堂前，满庭苍霭秋飒然，羡君丛竹琼阑边。","能使子奠看不足，娟娟翠袖笼寒玉。","蓊郁光浮缃帙青，檀栾色泛金尊绿。","劝君斟竹叶，为君歌竹枝。","清阴疏影何离离，棋声琴韵宜风吹。","莫言节苦夏虫避，莫道丛卑凤不至。","龙去须惊化杖时，雪深方见凌云器。","君家缥管有辉光，篇翰长悬汗竹香。","赋就仙声来嶰谷，梦回明月在潇湘。","七贤扫径堪为友，狂来潦倒非关酒。","最爱堂空客散后，山童剥笋敲茶臼。","怜君意气本清真，冰簟藤床对绿筠。","从今日日相过熟，看竹何须问主人。"]},{"t":"中秋泛月篇","f":"七言古诗","c":["江南秋色正平分，雨霁天空澹片云。","铁瓮潮生迎月彩，钟山霞起拂星文。","星文月彩临双阙，轮转露盘光渐发。","万井如浮雪浪中，千门共坐天香窟。","千门万井竞豪雄，戚里侯门乐更浓。","楼上秦箫双戏凤，台前羌笛独吟龙。","凤箫龙笛风吹去，直到琼宫空阔处。","素娥褰幌暗窥人，玉兔听歌暂停杵。","幌褰杵歇洞重门，天上何如下界喧。","共道广寒无俗调，岂知城郭有仙源。","仙源即在名园里，地僻何嫌翻近市。","万树悬萝挂客冠，一片秋声洗人耳。","轻舫斜维太乙莲，洪池高接银河水。","荡舟随水弄涟漪，月隐楼台露半规。","炯炯菱花初启匣，亭亭妆阁映纤眉。","纤眉笑出临团镜，池心始觉冰轮正。","河伯轩窗烛影深，水晶院宇珠光净。","水晶坐久露霏微，去去疑攀织女机。","取石不须过卜肆，裁云还解制秋衣。","摇曳秋衣如练白，沿洄谁识寻源客。","拍手人间傀儡场，攒眉市上铜鞮陌。","水月空明彻底清，醉来挥盏吸琼英。","酒星自有仙舟侣，却笑山公浪得名。"]},{"t":"神仙曲","f":"七言律诗","c":["蕊珠宫里琼帘卷，下望九州烟九点。","一局残棋尚未终，七国战馀三国战。","茫茫浩劫如车轮，蟠桃花下几回春。","晚过蓬莱曾濯足，晓看东海起红尘。"]},{"t":"吉祥寺古梅花下醉歌巨源王孙招游","f":"七言古诗","c":["东风醉客胜醍醐，春情流转如辘轳。","官闲锁印一事无，联镳载笔多酒徒。","看花踏遍金陵都。","金陵梅花虽满眼，标格不足骄狂夫。","吉祥一株最奇古，白龙鳞甲拿云舞。","练裳缟带态自轻，仙姿不老临瑶圃。","香魂应自雪山来，群芳共让花神祖。","巨源王孙兴有馀，携壶花下扬轻裾。","繁英十亩团成幄，广荫四座纷扶疏。","举杯酹酒聊索笑，怜君逸韵殊恒调。","凌霜挂月不知年，粉脸烟鬟长窈窕。","茫茫岁序如飞梭，问君阅人人几多。","妆残阁下魂醒否，鹤去孤山客若何。","曾识骑驴高士面，曾临水部琉璃砚。","庾岭人归可有书，罗浮梦后谁能见？","花如解语诉知心，愿托香风达玉音。","脱尽铅华空色相，朅来忘却古还今。","齐梁台殿知何处，还同一阵催花雨。","屈指当年欢赏人，贤愚贵贱总成尘。","燕归不识乌衣巷，水落难寻桃叶津。","问君何事绵多历，托根应借空王力。","可悟灵椿有大年，榔梅曾说證真仙。","王孙王孙且尽醉，醉归好著淮南篇。"]},{"t":"刘生","f":"七言律诗","c":["门外香尘喧酒车，堂中食客不歌鱼。","招呼六郡三河少，千里趋风半纸书。","伎台幸舍连云起，赤胆人争为君死。","输金还愿筑三边，马埒何须惜布钱。"]},{"t":"采茶词","f":"七言古诗","c":["昨夜新雷破嫩芽，旗枪簇簇相交加。","持筐女伴相催去，丛云踏碎纷如絮。","戴胜啼残日渐西，归溪花满使人迷。","竹炉缓焙收清味，芳馥犹含百花气。","石泉泱泱胜兰汤，留取输官未敢尝。"]},{"t":"春江花月夜","f":"七言古诗","c":["春风两岸发繁花，春月乘风渡浦沙。","皎皎波心摇白练，盈盈岸侧映红霞。","水月空明浑不定，一枝窈窕元端正。","月色偏能泛水纹，水纹不解流花影。","素娥倚桂妒花香，鲛室持绡待月光。","但道弄珠来洛女，谁知飞片误刘郎。","刘郎洛女临妆匣，镜里胭脂翠羽压。","玉兔翻骑赤鲤游，琼枝倒被银蟾插。","客来停棹大江湄，春信归来已后期。","却忆深闺花月貌，倩将流水寄相思。"]},{"t":"凤台曲","f":"七言律诗","c":["瑶宫金录旧有名，萧郎嬴女骨双清。","雾谷霞绡飘凤背，箫声散落星榆碎。","衿天幕地烟蒙蒙，不比人间鸳帐中。","秦苑莺花围粉黛，空忆三山望东海。"]},{"t":"屏风曲","f":"七言律诗","c":["云母栖鸾飞不起，宝障空明坐秋水。","银蟾玉兔递送光，只留轻晕护秋霜。","秋去春来还不撤，流萤夜度催炎热。","可怜蕙质汗珠红，推开遥待大王风。"]},{"t":"燕矶醉游歌","f":"楚辞体","c":["燕矶怪石欲飞舞，绝壁去天才尺五。","神工鬼斧巧镵削，突兀恐干天帝怒。","骞头奋翼何太奇，为与京畿作门户。","上攀阊阖锁，下俯冯夷宫，吞江吸汉受朝宗。","盘回王气在其中，龙楼凤阁常郁葱。","周家廷后存镐丰，闾阎扑地绮罗丛。","岁岁良辰集此地，舟车水陆交奔冲。","我辈来游值胜会，倾都士女狂如醉。","毂击肩摩十丈尘，金钿委地琼瑶碎。","有美人兮青翰舟，锦帆绣幄当中流。","征歌更鼓湘灵瑟，拾翠还过杜若洲。","万人流盼千人羡，玉质波光净如练。","不信瑶台月下逢，谁云洛浦今能见。","鸳鸯鸿雁各有偶，笑杀旁人浪回眷。","须臾填隘不可驻，揽衣直上悬崖去。","飞阁临江挂彩虹，危亭逼汉蹑罡风。","俯观下界如屯蜂，妍媸贵贱虽不同，百年瞬息皆成空。","君看矶畔东流水，流尽英雄还不止。","黄旗紫盖黯无光，玉树金莲亦枯死。","六代兴亡似奕棋，到今时事转堪悲。","清谈已落晋人吻，植党尤仍宋代非。","图里流民空有骨，关前塞卒苦无衣。","立马不闻鸣彩仗，神龙还见卧遥闱。","咫尺重阍不可叫，忧时雪涕舒长啸。","补天难展女娲手，避地终随子陵钓。","五噫歌残出汉关，桃源深处水潺潺。","可怜矶上遨游者，尚在醺醺醉梦间。"]},{"t":"勾漏洞歌寿明河家兄五十又一","f":"古风","c":["君不见铜柱之标高插天，合浦潮与南溟连。","明珠翠羽光华然，估客十万矜腰缠。","我兄侠气凌铜柱，射策武闱力如虎。","丈夫七尺肯低眉，五湖四海随轻橹。","纷纷珠翠不入眼，一掷黄金动如土。","适兴惟寻勾漏丹，往来洞口几盘桓。","白云莽互蒸丹灶，玄鹤翩跹集石坛。","稚川亲为传仙决，饮以流霞兼玉屑。","才观半局已千年，笑指南溟当一啜。","谁言跨鹤上扬州，此日丹成恣远游。","遥看蓬山迎倚杖，宁论海屋与添筹。","有弟有弟奇无匹，踞坐衡山观日出。","朱鸟飞飞送远书，盘中只进苏耽橘。"]},{"t":"衡阳七夕拟秋闺怨","f":"七言古诗","c":["天上人间隔几许，处处楼头望牛女。","欢情别思两茫茫，泪洒银河一水长。","西山挂月啼寒兔，倚桂佳人暗相妒。","自笑应同后羿妻，十年夫婿戍辽西。","寒衣未就催刀尺，露冷芳丛闻促织。","锦字还能出巧思，何须五色竟蛛丝。","城南少女明朝嫁，挑灯半夜缝裙衩。","独下高楼恨转深，万重关塞万重心。","休将河畔支机石，错比庭前捣练砧。"]},{"t":"又拟湘妃怨","f":"七言古诗","c":["湘水风清铺白练，影写银河如一线。","双星脉脉欲何为，宝扇龙车夜相见。","黄陵古庙冷飕飕，对此双星泪暗流。","白云飞去苍梧老，绿苜残时斑竹秋。","幽怀一片凭瑶瑟，声应寒蛩两呜泣。","难编斑竹架长桥，玉辇相逢定何日。","帝子天孙各水乡，悲欢今夕较谁长。","可怜点点填河鹊，却胜来仪双凤凰。"]},{"t":"落日歌","f":"古风","c":["却怪挥戈有鲁阳，更怜誇父为君忙。","今宵且向虞渊宿，明旦扶桑又束装。","今宵明旦何时了，眼底儿童两鬓霜。","鬓霜齿落休叹息，还有蓬莱水浅如涓滴。"]},{"t":"雪月双清篇","f":"七言古诗","c":["寒风忽霁千山雪，晴云忽吐三更月。","清姿皓魄共澄鲜，双献空门斗奇绝。","空门雪月最清嘉，总为高僧转法华。","皎皎毫光开晓镜，盈盈宝雨散天花。","天花晓镜寒相妒，白沙千顷眠蟾兔。","喜看身世在琉璃，何用西方寻净土。","有客凭栏眺望高，金波潋滟化银涛。","翻惊下界浑铺练，欲向嫦娥乞剪刀。","静听空外冰轮响，忽讶王恭行雪上。","六花风起白龙飞，又似唐皇步月归。","曾闻玉杵敲灵药，何事琼尘满空落。","平田种璧正芳春，只恐偏逢砍桂人。","寥寥方籁中宵静，贝阙冰壶濯孤影。","赋就挥觞发浩歌，霓裳天乐还相应。","曙钟初动叫天鸡，遥指银河作剡溪。","月华浮动莲花舫，问讯仙郎沅水西。"]},{"t":"焙茶词","f":"七言古诗","c":["主人癖睡思饮茶，春雷初破黄金芽。","云蒸露浥含灵气，百草群花让清味。","山翁穿入紫霞堆，采自仙人掌上来。","簇簇旗枪擎数斗，高斋钻燧燃榆柳。","呼童扇火红竹炉，薰笼残焙轻纱铺。","芳香片片凌兰苜，恨无杨子中冷水。","井花初汲日迟迟，烹待南窗梦醒时。"]},{"t":"洗竹歌","f":"七言古诗","c":["古墙缭绕连丛竹，野棘枯藤相结束。","上瞀蛛丝下蛇鼠，黑雾荒烟沉绿玉。","我癖还过王子猷，闲来为洗此君羞。","呼僮芟削挥霜剑，便觉直干寒飕飕。","扫除洁净无尘滓，只留一片莓苔地。","疏影能邀好月来，轻阴更引清风至。","南窗昼卧到黄昏，听雨如眠海上村。","寄语青皇须爱护，明朝新笋长龙孙。"]},{"t":"今昔行赠叶紫虚社兄南归","f":"古风","c":["秋入衙斋风淅淅，悲秋客子歌今昔。","回看往事念年馀，怀抱依然对兹夕。","当时年少气豪粗，把臂同君坐石湖。","笔下共矜千卷富，橐中宁论一钱无。","深山胜迹烟雾灿，石髓松花还可饭。","楚楚衣裳剪绿萝，荧荧灯火窥青简。","有时蹑屐上峰头，忽惊屐底有云流。","眠空宇宙三千界，气盖山河百二州。","泠然长啸雄风吼，共道功名如唾手。","砚水清波起北溟，剑花赤焰冲南斗。","意气相期接翼飞，宁知时命两相违。","宦途愧我题桥晚，失路怜君泣玉归。","春来秋去光阴谢，握手重逢两悲咤。","渐见巅毛点雪霜，更堪儿女催婚嫁。","丈夫有舌岂长贫，垂纶牧豕登要津。","羡君昂藏七尺身，重君焜耀连城珍。","彩笔挥洒如有神，肯甘龌龊淹风尘。","酒酣拔剑为君舞，羁思离情不肯诉。","况是蒹葭白露时，啼乌夜绕江城树。","劝君酒，对君歌，岁月流光一掷梭。","君归仍坐白云窝，倚天长剑还再磨。","歌残漏永商风起，磊落平生一片气。","薄宦虽无陆贾装，赠君空有绨袍意。","旧事凄凉昔与今，岁寒父谊□千金。","石湖松桂烦相问，芳草闲云寄此心。"]},{"t":"毛女","f":"楚辞体","c":["秦皇沿海求神仙，宫中怨女夜如年。","中有人兮鹤胎而鸾骨，饮石泉兮啖松柏。","髓绿毛青踏玉峰，彩霞红雾留春容。","招手徐郎向东笑，灵风引船船缥缈。","回首沙邱不见君，吹箫旧侣自为群。"]},{"t":"春游篇","f":"古风","c":["霁色澹东风，韶光丽南郭。","共持千日酒，去觅三春乐。","三春景物属芳年，万户遨游簇锦筵。","昨日裹饧过冷节，今朝钻燧起新烟。","嫩绿平铺芳草地，轻阴暖烘养花天。","几处斗鸡还蹴鞠，谁家拾翠更秋千。","花裀片片承珠履，柳幕垂垂拂玉鞭。","玉鞭香毂城南道，公子王孙联璧好。","酒泛波光似鸭头，衣薰花气如龙脑。","名花美酒两相当，挈榼提壶列雁行。","韩嫣金丸飞道左，潘安珍果满车旁。","游丝飘絮纷相逐，杜宇声残莺韵续。","修褉何须问洛滨，寻芳不必誇韦曲。","踏青佳处在旗峰，彩翠岩峦映几重。","绣幄翻风宜藉草，红氍软坐可论松。","春兴低昂林外蝶，雄风浩荡酒中龙。","已倒玉山看酒态，犹坚壁垒竞谈锋。","谈锋未已歌声起，宛转轻盈呈百媚。","绿蚁频催北海觞，白云正拥东山妓。","彼美娉婷冠教坊，遍游湖海号名娼。","曾邀陶谷风光调，惯乱苏州刺史肠。","飞燕掌中盘妙舞，图黄额里倚新妆。","新妆宜压缠头锦，百叠征歌促豪饮。","宴笑同迷下蔡人，醉眠谁荐阳台枕？","酒罢歌阑客欲归，云軿金勒去如飞。","香尘滚滚笼红袖，草色萋萋妒绿衣。","难把长绳牵落日，且将沉醉送馀晖。","人生何用苦羁束，百岁须臾鸟过目。","问舍求田日转忙，持筹钻核人真俗。","半文犹吝杖头钱，请看累累诸墓田。","可叹千秋归暗夜，何曾一滴到重泉。","终古长眠不知醒，得似生前先酩酊。","十日频愁风雨声，三春肯负清明景。","适意乘春散百忧，生涯痛饮是良谋。","秦陵汉阙山空在，金谷铜台水自流。","转眼春光将暮矣，相期秉烛夜深游。"]},{"t":"七日龙潭篇","f":"古风","c":["佳节过天中，和风吹水面。","弦歌盈乐土，花径开芳甸。","东官芳甸湛清华，锦作晴川玉作砂。","竹暗名园连鸟道，桃深僻坞隐人家。","名园僻坞蟠深奥，别敞龙潭澄碧绿。","榴花古渡溯沿洄，铜岭悬崖森结束。","宛如巫峡控三巴，恍似武陵穿九曲。","不独山川相映带，更兼楼阁纷联属。","中有龙宫水府通，水晶院宇何玲珑。","万丈阴沉含雨气，四时光怪闪腥风。","海天风雨龙神现，水族乘潮逐飞电。","晴来青镜照菱花，雨后黄涛奔竹箭。","泛罢蒲觞雨渐收，倾都七日竞龙舟。","金鳞火鬣腾高浪，伐鼓齐桡下急流。","夹岸垂杨摇锦旆，窥帘少妇倚琼楼。","水龙稳睡澄潭里，木龙乱趁风涛起。","角胜争雄响若雷，繁弦丽曲喧于市。","潭中聚市沸笙歌，舟上倾杯溅绮罗。","已羡鄂君骄拥被，争看洛女解凌波。","联舟士女闲游戏，菡萏芙蓉相并媚。","万舫俄惊仙令来，双凫忽驾清风至。","人陪仙令宴仙舟，杯酒留连更唱酬。","谁云郢曲压巴调，还许渔人和棹讴。","曲终暗洒怀沙泪，明水江蓠堪寄酹。","三闾遗韵和应希，千古骚人吾辈在。","吊古悲歌起暮愁，昔年曾向楚南游。","搴芳坐叹三湘冷，作赋平吞七泽秋。","归来已署江湖长，今日龙潭惬清赏。","遥望烟笼杜若洲，还疑身在湘江上。","粤海湘江隔几重，逐臣沦落竟孤踪。","可怜古狱空沉剑，岂信高冈有卧龙。","真龙画龙谁复辨，覆雨翻云谁忍见？","刻木虚张鳞甲威，掀波便作玄黄战。","阅尽人情黯自悲，怀仙欲与白云期。","蓬莱弱水舟难到，愿借长房竹一枝。"]},{"t":"湘江问渡篇","f":"古风","c":["借问湘江水，缘何不断流。","长驱朝夕浪，不洗古今愁。","客愁万斛凭谁诉？","跋涉湘江凡七度。","退步真同六鹢飞，入宫久被双蛾妒。","归卧宁知阅岁深，出山始觉流年暮。","岁月频催去后人，关河不改来时路。","滚滚江干多白沙，还如迁客鬓边华。","青枫旧是伤心树，芳杜新开剌眼花。","人来人往无休暇，湘水东流看逝者。","愁驱羸马入咸秦，懒赋招魂哀屈贾。","徘徊江上数峰青，瑶瑟泠泠不忍听。","涕泪肯将沾楚竹，升沉还欲问湘灵。","湘灵谓我宜安命，可悟水流心不竞。","渔父元称玩世翁，水鸥自有忘机性。","昔年此水渡昌黎，迁谪应同屈贾悲。","凄凄衡岳开云日，惨惨蓝关拥雪时。","世间变态无不有，浮云白衣忽苍狗。","失意从人唤马牛，高标终是齐山斗。","受教湘灵重稽首，奠以椒浆兼桂酒。","直上西秦路八千，蓝关即在马蹄边。","捷径且输俗士后，芳踪宁让古人前。","提兵欲拂冲星剑，命驾长挥绕电鞭。","功成勒石黄陵庙，记取湘江问渡篇。"]},{"t":"北邙吊古","f":"七言律诗","c":["洛阳城里歌钟起，北邙松风徒聒耳。","当年生死异炎凉，此时人鬼随流水。","王侯陵墓尽皆空，一望童山夕照中。","传语樵儿须爱惜，且留残树伫悲风。"]},{"t":"匡公啖荔歌","f":"古风","c":["庐山之精化匡公，平吞彭蠡洗心胸。","五蕴吹转法轮风，尾闾归墟洞不穷，其中暗与南溟通。","南溟荔熟当炎夏，火珠遍缀芳林下。","甘美如割云山蜜，香甜不数扶南蔗。","外披绛绡内玉肤，色味双绝天下无。","皎然西施并子都，来呈香酥献醍醐。","匡公与荔结缘久，一闻荔熟垂涎久。","词客园林凡几家，家家荔落匡公手。","抛壳纷纷红雪飞，入口滚滚糖槽漏。","遗核在地日数斗，翻令见者惊欲走。","拍手笑东坡，自矜三百颗。","若持饷匡公，日日还遭饿。","匡公大嚼更怀归，行住常餐兼坐卧。","人言丹荔王百果，封公荔王制曰可。","问公腹中何所如，蠡湖溟海趋尾闾。","信我前言良不虚。","不然啖后茗碗还五十，滔滔荡荡安能储？","南人畏荔热太毒，公腹清凉乐有馀。","试问甘露门，何如荔中味。","我言半偈公须记，色香佛法所最忌。","此物曾经驰驿骑，千人万人相枕死。","至今犹怨太真妃，玉肤红粉空妍媚。","甘口生疾苦口药，芳洁无如蔬笋气。","知公心似絮沾泥，勿使香魂入梦迷。","满口莲华宣梵呗，本来无物是菩提。","吁嗟丹荔休多携。"]},{"t":"浮云妒月歌","f":"楚辞体","c":["秋空皎月扬清辉，银河避影群星稀。","羽衣舞罢雄风起，玉杵敲残瑞露霏。","谁言春有千金夜，月到中秋更无价。","酌酒遥薰桂子香，开筵如坐琼宫下。","此时秋色正澄明，此夜银蟾上太清。","朗朗偏催希逸赋，娟娟先照亚夫营。","良宵豪兴相挥霍，邀得嫦娥对斟酌。","酕醄不惜玉山颓，潦倒宜倾金凿落。","况当年岁丰，欢笑万家同。","里巷争歌洒乐子，儿童群拥柚灯红。","严城不夜明如昼，铁锁开关停玉漏。","欣逢月姊靥偏娇，忽遇云师眉欲皱。","云从何来自海东，或疑曾过楚王宫。","招携巫峡阳台女，将向天南行暮雨。","偶睹仙宫倚桂人，新妆妒杀霓裳舞。","云如鱼鳞又草莽，苍狗白衣更殊状。","搏弄平铺大地阴，奔腾尽把诸天障。","杯停酒冷恨如何，翻作浮云妒月歌。","故助砌蛩声惨切，深笼桂树影婆娑。","银屏半掩窥云隙，似听嫦娥长太息。","最恼今宵氛䘲遮，还同往夕妖蟆蚀。","凄凉古与今，感叹一长吟。","谁使蝇污璧，谁怜口铄金？","万里九阍难遇主，逐臣离妾易沾襟。","世态总浮云，哀歌心独苦。","拟挥龙剑划云堆，更运风斤修月户。","云兮云兮且暂休，放开霜月肃高秋。","取醉此时虚北海，携尊明日上南楼。"]},{"t":"卖拙歌","f":"古风","c":["西园公，真奇绝，不愿乞巧偏乞拙。","七夕铺张香粉筵，低头拜向天孙说。","天孙玉梭织七襄，霞丝虹线组天章。","园公胸藏锦绣肠，天工人巧相低昂。","歌中丽藻驱韩柳，东坡辩舌钟王手。","金石盈篇节奏鸣，龙蛇落纸纵横走。","人生最苦不知足，何须用拙为貂续。","天孙无拙可与君，憨生有拙君不闻。","昔年怀宝骄白眼，此日索价高青云。","园公问我拙数目，我拙三万六千斛。","一口一斛用未尽，到今堆积还充屋。","包裹何曾藉智囊，收藏正合居愚谷。","我言拙状君莫笑，一个铁锤无孔窍。","兀兀腾腾蠢性资，期期艾艾讷言辞。","无书徒鼓便便腹，失韵空吟浅浅诗。","曾事支离称小友，更尊溟涬作严师。","吟诗作赋终何用，镇日推敲费拈弄。","残稿宜将酒瓮覆，寄人莫倩椰瓢送。","壮年作宦少因依，晚岁回车失路归。","本期击水鹏同运，岂料迎风鹢退飞。","归来偃卧长林下，夜逢醉尉还惊怕。","如病如狂不自知，呼牛呼马从人骂。","自怜年纪未衰颓，何事冰心若冷灰。","七日凭谁凿混沌，千金无药治痴呆。","怀藏此拙向谁卖，难折药资还酒债。","卖货须寻识货人，一时惟有园公在。","五车载拙向园公，不须白镪兼青铜。","将我一团真懵懂，换公一副绣心胸。","园公咄咄频摇手，君家奇拙兼百丑。","君且怀藏自享用，更付子孙长世守。","园公乞拙只问天，如君人拙不值钱。","君且为鸠我为鹊，有巢各自相安眠。","我闻园公言，自嗤还自疑。","春蚕死茧里，织妇无完衣。","离离栎树荫百亩，斧斤不到凌云枝。","世间拙处亦有用，园公园公，好听村婆说春梦。"]},{"t":"题侍御彭符苏公巡核茶马宴赏西戎图","f":"七言古诗","c":["龙飞圣主继离明，端拱垂裳镜太清。","哈赤安奢虽跋扈，犹思薄伐戒穷兵。","庙算绸缪在牖户，古来王道称神武。","抚夷款市示羁縻，戢伏戎心莫予侮。","秦地元为天下枢，九重拊髀廑西顾。","西京锁钥藉名臣，特简苏公持玉斧。","苏公持斧下丹霄，百二山河尽动摇。","课吏首推龚渤海，谈兵先起霍嫖姚。","边城款市公为政，茶官马监趋严令。","戎奴入市跨龙媒，汉贾临关携凤饼。","两家贸易肃而和，牵马囊茶行且歌。","万匹青骊归苑寺，千箱紫笋渡洼河。","戎奴感德皆罗拜，誓为属国防西塞。","既变枭音吐悃诚，当宣天语推仁爱。","秋日秋风霜满天，苏公张幕静临边。","椎牛迭进葡萄酒，列席平铺玳瑁筵。","笑指诸戎皆赤子，饮斯食斯同燕喜。","高牙大纛急翻风，羌笛胡琴纷聒耳。","汉将戎王递引杯，潜消杀气坐春台。","欢呼尚守君臣礼，乐事还携妇女来。","喧喧击鼓传筹饮，又赐越罗兼蜀锦。","不独投醑醉恁深，更思挟纩衔恩甚。","从此玉门堪启关，只今榆塞皆安枕。","苏公明威凛若神，清霜俄变露华新。","驭夷自有金汤策，代狩能敷天地仁。","嗟彼安奢与哈赤，跳梁转眼为俘馘。","请看归顺醉壶觞，何用凭陵膏剑戟。","将帅疏防反剧戎，折冲若个似苏公。","雄姿未列麒麟上，宴赏先传图画中。","呜呼此图真可羡，诸戎胆落风霜面。","始信丹青动鬼神，更疑光怪驱雷电。","韩范当年曾备胡，不知能有此图无。","庙堂若会图中意，九塞三边可赐酺。"]},{"t":"去妇词","f":"古风","c":["新妇归来久，十年长食贫。","山花当首饰，寂寞度残春。","南陌提筐采蕨晚，崎岖行汲西江远。","入夜邻家与凭舂，并日糟糠方一饭。","雇直馀粮养舅姑，还嗔野菜索江鱼。","小姑娇蠢啼东壁，又怒炊迟动裂裾。","夫婿一编临瓮牖，残膏映读甘蓬首。","岂料红颜失旧容，年年愁苦成衰丑。","冬日严霜半夜飞，绳床长伴一牛衣。","千秦季子曾空返，相待何尝不下机。","誓将富贵酬酬贱，富贵已来心乍变。","庑下宁怜举案人，茂陵娶得如花面。","蛾眉谗诼妒无盐，黄泉决不容相见。","哭向高堂诉舅姑，舅姑含怒一言无。","咫尺庭阶不许立，剖分旧镜频催出。","邻人偷看满墙头，为我掩泪衣皆湿。","片帆羞过望夫山，徒步潜寻旧路还。","路旁追送多邻里，问我还家何所倚。","父母沦亡四壁空，从军有弟迷生死。","此身形影自相怜，薄命无心再问天。","寄言夫胥须珍重，更愿新人长少年。"]},{"t":"罗浮歌送韩孟郁南归","f":"楚辞体","c":["若有人兮思罗浮，骑南鸿兮排高秋。","风萧萧兮木正落，暮雨急兮愁云稠。","君暂停兮夷犹，泥滑滑兮易摧辀。","况孱仆兮瘦马，又敝尽兮貂裘。","问君囊兮几何，止蒯缑兮无多。","弹长铗兮空返，同谁散发兮山阿。","山阿兮寥泬，洞衔星兮岩挂月。","山鬼哭兮萝深，鹧鸪啼兮竹裂。","玄熊绿罴，狞目舔舌。","烟结翠沉，径崄人绝。","念幽栖兮骨冷，忽惨别兮肠热。","君山中兮茹薇，手一编兮掩扉。","石潭黑兮龙蛰，高梧老兮凤饥。","意不乐兮强牵衣，伤逋客兮久未归。","临风恍兮悼叹，魂九逝兮先飞。","为我谢兮安期，云车来兮何迟迟。","君行迈兮岁将晏，日复近兮长安远。","时不可兮再少，君毋徒兮偃蹇。"]},{"t":"赠剑客游五","f":"古风","c":["五陵游侠儿，裘马自轻肥。","怀中匕首光陆离，高歌气化白虹飞。","醉来舞剑器，矫捷如猱猿。","朝过朱亥里，暮入信陵门。","三杯白眼耳热后，千金为寿常摇手。","平生意气重贫交，五侯七贵余何有？"]},{"t":"仙政乡丛石山歌","f":"古风","c":["女娲补天弃残石，掷落南荒填薮泽。","仙家洒露种云根，抽笋成林插天碧。","望之冠冕如伟人，执圭鸣玉万仞身。","缤纷争向九嶷去，恍若千官从舜来南巡。","大者轩翔小者仰，旌幢队队森仪仗。","又若迎銮候驾追翠华，翠华不返相咨嗟。","须臾山带拖白雾，忽见千官皆缟素。","松风涧水助哀音，弓堕龙沉失归路。","君不见，仙政乡，千年山水恨同长。","寝陵寂灭铜碑没，泪竹斑斑空断肠。"]},{"t":"结客少年场","f":"古风","c":["千金买骏马，百金装鞍辔。","骑出大长楸，万人看意气。","朝过博馆暮屠肆，毛薛为兄朱亥弟。","宝剑倚天光照地，半酣拔剑起相视，人间谁有不平事？"]},{"t":"卖花词","f":"古风","c":["朝卖花，暮卖花。","为助青皇一肩力，香风散遍千人家。","朝暮花含，春暮花笑。","花落不重开，人生难再少。","寄语楼头招手人，买花沽酒莫辞频。","昨过名园多换主，纷纷蜂蝶入西邻。"]},{"t":"射雉词","f":"楚辞体","c":["轻风吹麦垄，野雉落山梁。","耿介不相让，趫争各占场。","宁知翳中人，伏机在其旁。","枯弓一发响，雄殪雌悲伤。","不恨人伏机，但恨媒相引。","警戒各翻飞，缡褷过修畛。","雉兮雉兮各有雌，如皋何事骄其妻。"]},{"t":"猛虎行","f":"古风","c":["虎啸空山动，深林鸟兽惊。","悲风缠玉爪，流电铄金睛。","伏机陷阱还遭缚，伥魂杀气嗟零落。","摇尾垂头似槁枝，猎童还见寝其皮。","君不见，世间元恶哮如虎，东门黄犬收眉坞。"]},{"t":"公莫舞","f":"古风","c":["夜寒鬼母哭秋郊，一龙一蛇今更交。","莲花光吐双虹碎，谁人拦箾反相背？","汉王已起楚王醉。","公莫舞，夜渐阑。","亚父亚父不解事，请君试问芒砀山。"]},{"t":"采葛篇","f":"古风","c":["朝采葛，暮采葛。","朝行冲雾畏虫蛇，日晚提筐苦饥渴。","为絺为绤两般机，卖与他家作嫁衣。","年年入山赤双足，百结悬鹑遮尺幅。","可怜长袖摇薰风，不到蒙茸深谷中。"]},{"t":"大观楼歌","f":"古风","c":["纵横千里目，浩荡万古心。","乾坤何寥廓，山水自高深。","楼头缥缈诸天近，玲珑八面祥飙引。","谁言新成来贺燕，只恐孤骞如结蜃。","披襟临水揽蒸湘，挥手凭空扪翼轸。","游丝摇曳扇微和，城郭郊廛乐事多。","正看晴景浮烟树，又送春声入棹歌。","棹歌残，渔歌起。","紫兰落远洲，斑竹垂清泪。","白云片片自南来，借问苍梧何处是。","微茫七泽盘心胸，凭栏一啸生雄风。","我欲挟赤帝，鞭赤龙。","划长空而倚剑，蹴天山而挂弓。","平生慷慨羞怀土，去国懒裁王粲赋。","平生散慢恣豪狂，兴来还踞庾公床。","世上人空老，壶中日自长。","争名与争利，臧谷俱亡羊。","君看醯鸡不出瓮，亦有鹏背摩青苍。","谁是谁非园吏梦，无忧无喜曲生乡。","我为登楼歌，高声振林木。","曾闻芥子纳须弥，肯道吾身同一粟。","幕天席地无边幅，倦来且抱希夷宿。"]},{"t":"杨花篇","f":"古风","c":["上林消宿雨，旭日照新妆。","气暖人偏懒，春深蝶更忙。","翩翩粉蝶闲园里，轻盈乱逐杨花起。","共道花狂胜舞腰，不知春去随流水。","借问杨花几处飞，日长风细自依依。","才迎南陌秋千架，又扑西邻织锦机。","百丈游丝遥带去，一群骄鸟共衔归。","衔归带去纷无数，南陌西邻两回顾。","灞岸低粘拾翠桥，渭城轻点寻春路。","路上桥边铺白毡，游人醉处总堪眠。","携壶结驷有今日，酒袖侵衣似去年。","去年今日红颜改，休道杨花镇长在。","蹋地凄凉只自歌，渡江消息空相待。","谁家怨别惜残春，闲掇杨花衬绣茵。","笑尔飘摇如荡子，那能吹送寄征人。","征人昔日江亭别，柔条尚忆同攀折。","薄薄难装战甲绵，霏霏想像阴山雪。","对此伤心半掩闺，从他漂泊斩东西。","愁来正作辽阳梦，窗外流莺且慢啼。"]},{"t":"赋得春日迟迟篇为梁封君年伯寿","f":"古风","c":["南海扶胥口，洪波万里长。","蓬壶东望近，隔岸即扶桑。","扶桑高拂天门晓，天鸡唤起圆罗耀。","缥缈仙人驾六螭，曈昽瑞霭翔三鸟。","此日东皇弄早曦，条风佳气转春姿。","钟山散彩收龙烛，若木擎枝度郁仪。","辉射露盘偏泛滥，光浮兰砌更逶迤。","君家箫鼓喧春昼，麟驭鸾旌相辐辏。","红日高翻彩袖明，白云低绕银璈奏。","白云红日共澄鲜，野马轻飞洞里天。","已命羲如徐按辔，何须誇父急扬鞭。","棋残柯烂不知午，桃熟椿芳正上筵。","筵前恍坐壶公境，把酒负暄醺又醒。","起视松阴偃盖平，渐看花影笼阶静。","松阴花影久徘徊，春日如年引寿杯。","自缘两珥承轮驻，不为单戈叱驭回。","语燕流莺能缓唱，景圭昼漏莫相催。","仙翁春酒宜长日，仙郎昼锦还依膝。","鹤发犀鞶色映新，中台南极拥金轮。","羡君爱日承欢暇，更长作安捧日人。"]},{"t":"潇湘曲","f":"古风","c":["潇湘水，滔滔流。","垂杨两岸中兰洲，鸳鸯□玉兼沙鸥。","今朝忆郎处，去岁送郎舟。","水流人去远，立望潇湘头。","愁来把钓连双鲤，恐有征夫边塞字。","剖之空腹无素书，江寒日暮风吹裾。","含啼泪尽横波目，那堪再染湘妃竹。"]},{"t":"天坐歌","f":"楚辞体","c":["自为烟波主，长作烟波游。","擘破红莲瓣，轻盈制小舟。","小舟恰受人三两，九日乘流坐天上。","今人翻作古人案，已变登高为泛广。","绣被何须载鄂君，兰桡不用呼吴榜。","舟中何所有？","鲈脍兼莼丝。","江清月更朗，正值秋高时。","玉盏浪摇红琥珀，金蛇尾摆青玻璃。","乘流而逝兮遇坻则止，日落潮生兮海风又起。","乘风纵柁任吾之，瞬息宁知千万里。","取石应攀织女机，濯缨疑到银河水。","鼓吹一部，歌童一双。","声穿云而裂石，龙警睡而翻江。","视龙犹蝘蜒，捉龙入酒缸。","我骑醉龙拂云去，琴高赤鲤同翱翔。","更笑古人愚，钓国而钓璜。","兹江异渭水，署曰水仙乡。","浮家泛宅无涯岸，弄月观涛夜将半。","谁云一叶小轻舟，星斗垂珠天作幔。","赢得投闲自在身，鸥群渔父永为邻。","君看桂水鸣榔客，不数龙山落帽人。"]},{"t":"孟冬念二日集李将军伯修署中赏菊戏作把菊问答歌","f":"楚辞体","c":["问黄菊，开何迟，严冬杀气凝东篱。","金钱已过浮萸后，玉醴非逢落帽时。","把花枝，堪笑汝，耽隐逸，有何趣。","冷淡曾淹处士家，凄凉今倚将军树。","名园百卉斗春妆，五侯七贵飞琼觞。","如花少女出洞房，莺喉鸾舞调笙簧。","一刻千金夜未央，汝时抽茎寸许长。","野畦芳草同摧藏，到今开处满头霜。","北风瑟瑟吹衣裳，月寒酒冷对虚堂。","侍儿曲调虽绕梁，曲中哀怨含清商。","纵有黄□与绿袖，敢与桃李争风光。","把花枝，长太息。","怯秋霜，傲秋色。","一生不得青皇力，花兮花兮何岑寂。","花动容，似解语。","执予袖，附予耳。","樽前莫笑我开迟，如君偃蹇还堪嗤。","同朝鸳鹭燕云隔，失路风波粤水悲。","致身何太晚，抽身何太早。","不言时命乖，但说烟霞好。","君归君归何草草？","君家松桂可盘桓，惟我同君共岁寒。","愿作君家篱下物，年年长得奉清欢。","花有情，酒有味。","泛英酌酒醉且歌，人世忙忙竟何事？","君有刚心照雪霜，我将正色留天地。","听花言，领花意，坚持晚节同须记。","斗转参横未忍归，狂浮大白向花挥。","花神有约酣余兴，明日携壶更典衣。"]},{"t":"枯庵歌送匡云上人还庐山","f":"古风","c":["问枯庵，杳何许。","曷名枯，有何意。","云在匡庐之巅，乱峰深处。","千重云，万重树。","三级泉，向庵注。","九叠屏，背庵竖。","主人习静而坐枯，心似寒炉灰，身如槁木株。","方丈大于斗，趺跏十载馀。","庵中无长物，一瓶一钵兼木鱼。","不点玉莲灯，山月遥相照。","不爇旃檀香，山烟常袅袅。","不钟不磬不梵呗，泉声鸟声自叫啸。","颇类巢父巢，又似壶公壶。","有石任名悟，有谷堪名愚，坐来枯寂一念无。","忽然粘壁蜗，化为云出岫。","芒鞋踏遍粤闽天，此心元属亡何有。","数枝松偃旧房前，猿愁鹤怨私自怜。","虽然去住本随缘，老去却忆庵中眠。","别我西归将有日，细语灯前宵促膝。","自言此别戒云游，坐烂绳床终不出。","赠吾诗，索我律。","离情黯黯上河梁，只履孤筇态萧瑟。","我笑匡公何太憨，妄认汝为汝，妄认庵为庵。","四大是幻形，可北亦可南。","天地一蓬庐，何处可恋耽。","汝去无所去，我别无所别。","两心冷似水，不为临歧热。","公看庵外月明时，罗浮与庐岳，两点在玻璃。","同居佛界中，芥子藏须弥。","汝我相聚何曾离？","我闻竹林寺，空相但现影。","譬彼阿闪国，谁能涉其境？","请公置庵空相中，金绳有路西方通，我也行坐常同公。"]},{"t":"重阳后五夜镜园小集听泉泛觞戏作问月歌","f":"古风","c":["翻疑东海月，却向小池生。","掩映双珠动，澄鲜两镜明。","素娥对镜垂珠珥，吾园水镜还如此。","广寒深殿乏泉声，转觉吾园更无比。","园中有畦兼有泉，听泉漱石集群贤。","试问开尊时共醉，何如抱兔只孤眠。","低头拍弄池心月，举头笑向嫦娥说。","窃药那能脱死生，伤离肯复嗟圆缺。","碧海青天夜夜心，恐君绿鬓今成雪。","君歌霓羽踏云游，照遍华夷内外州。","闻道冰轮三万里，缘何落在小池头。","池头贮石沉沉静，依稀月里山河影。","漱石已惊通海眼，步蟾愿指升天径。","两镜双珠对不移，金波拍弄转离披。","由来水月皆空相，只有西方悟者知。"]},{"t":"墨妙歌为冯无文赋","f":"古风","c":["龙宾道士一十二，佐以陶泓管城子。","更邀白晰楮先生，四君总属冯君使。","自从羲画创人文，鸟迹传来到八分。","垂露偃波争体势，钟王妙雇近谁闻？","冯君豪强好气岸，蛟螭盘拿入手腕。","为我挥毫酒镜园，楷行篆隶纷凌乱。","满园鱼鸟尽腾逃，古色祥光贯斗高。","已写新诗戛金石，旋驱笔阵涌波涛。","元气淋漓收不得，风涛怒战天昏黑。","楼台似挟阳侯飞，拔宅凌风生八翼。","咄咄怪事谁为之，疑是龙宾幻作奇。","返风息浪实藉霞仙力，龙鳞倒挂银钓丝。","君不见苍颉鬼夜哭，张颠濡墨头颅秃。","君归好作铁门限，相赠浮提汁万斛。"]},{"t":"新妇石 其一","f":"五言律诗","c":["可叹身犹幻，佳期怅永违。","无灵能窃药，有石岂支机。","晓月悬为镜，行云剪作衣。","江山长是伴，直待藁砧归。"]},{"t":"新妇石 其二","f":"五言律诗","c":["露重愁环佩，天空冷洞房。","娉婷看洛浦，云雨想高唐。","红叶年年落，夭桃岁岁芳。","银河连野水，相望恨无梁。"]},{"t":"新妇石 其三","f":"五言律诗","c":["塞北书难寄，衡阳雁不回。","独怜心匪石，空有泪成灰。","风月谁为主？","莺花肯自媒。","武都山下镜，应照片怀开。"]},{"t":"衡阳来雁塔","f":"五言律诗","c":["高标跨鹫岭，危构阚龙宫。","三楚冥蒙里，诸天指顾中。","檐前低度鸟，槛外倒听风。","因悟西来意，观空未是空。"]},{"t":"南雄陈好甫招集寺塔","f":"五言律诗","c":["陈遵能好客，选伎得邯郸。","酒借红颜宠，歌翻渌水寒。","人居金世界，醉倚玉阑干。","春事无劳问，桃花入座看。"]},{"t":"东山寺春集","f":"五言律诗","c":["花浓春寺晴，江日照心明。","云定鸟犹睡，泉流石有声。","天香浮殿细，宝梵出林清。","坐久忘归路，人疑到化城。"]},{"t":"赣江元夕遇雪三首 其一","f":"五言律诗","c":["□弦当此夕，灯火万家稠。","有客歌黄竹，游人已白头。","花迷梁苑树，兴尽剡溪舟。","尚惜千金夜，迎寒白更浮。"]},{"t":"赣江元夕遇雪三首 其二","f":"五言律诗","c":["雪色纷高下，蓬声递有无。","云深寒度雁，月暗夜翻乌。","冷入星桥合，光沉火树孤。","酒醒怀谢赋，幽思满江湖。"]},{"t":"赣江元夕遇雪三首 其三","f":"五言律诗","c":["飞絮侵春早，投珠入夜明。","金吾非有禁，鹤氅几人行。","舞阁销兰焰，更楼咽漏声。","入门各自媚，孤客若为情。"]},{"t":"秦淮春泛二首 其一","f":"五言律诗","c":["红桥通绿水，画舫澜银沙。","人识寻源客，春回犯斗槎。","伤心前日柳，莫问后庭花。","醉上长堤望，香车满狭斜。"]},{"t":"秦淮春泛二首 其二","f":"五言律诗","c":["草迷蝴蝶梦，日丽鹧鸪天。","江练摇歌扇，沙鸥近酒船。","豪华看往事，光景惜流年。","吾爱菖蒲□，兰桡莫更前。"]},{"t":"嘲萤火","f":"五言律诗","c":["腐草寄馀生，乘昏莫浪行。","烧霜光转湿，隔雨焰全轻。","岂以投珠巧，能当按剑迎。","炎凉看百态，星月敢争明。"]},{"t":"送张漱六下第南归二首 其一","f":"五言律诗","c":["送别边风急，金台古道旁。","无人市骏马，为尔哭昭王。","贫甚岁仍歉，愁多路更长。","萧萧秋色里，肠断雁南翔。"]},{"t":"送张漱六下第南归二首 其二","f":"五言律诗","c":["行路难如此，怜君抱玉归。","哀歌看短剑，相顾问无衣。","还洛金应尽，干秦策未非。","神鹰留梦泽，控地始雄飞。"]},{"t":"独酌月下","f":"五言律诗","c":["谁谓酒杯小，中涵万事空。","未须论圣品，且与洒尘胸。","好友形兼影，嘉肴月共风。","无人会此意，归去问陶公。"]},{"t":"病起","f":"五言律诗","c":["肺病起秋色，四肢忘安排。","苔侵捣药臼，竹覆弹琴斋。","瘦同鹤影立，静与鸡谈偕。","未割区中缘，难将幽性谐。"]},{"t":"独酌问月二首 其一","f":"五言律诗","c":["常从东海出，几度见桑田。","桂子何方落？","霓裳若个传。","空床消永夜，捣药怨长年。","多少关山意，离心满海天。"]},{"t":"独酌问月二首 其二","f":"五言律诗","c":["谁云不老身，圆缺竟何因？","却笑孤眠影，还窥独酌人。","无台那挂镜，渡汉恐沾轮。","秋近寒偏急，君应白发新。"]},{"t":"修褉日入金陵","f":"五言律诗","c":["垂柳临清水，风光动褉辰。","湖山如待客，花木总宜春。","细草偏承履，游轩不染尘。","繁华今古事，惆怅六朝人。"]},{"t":"江南春词","f":"五言律诗","c":["江上踏青处，清流映白沙。","天晴丝罥蝶，风细草眠花。","骏马系芳树，鹴裘付酒家。","醉来堪托宿，垂柳惯栖鸦。"]},{"t":"西园十咏 其一 澄碧亭","f":"五言律诗","c":["群木搴萝薜，泠然幽径通。","一亭偏傍水，四面总宜风。","地与市朝远，心将鱼鸟同。","避人焚草处，已作灌园翁。"]},{"t":"西园十咏 其二 方玉池","f":"五言律诗","c":["朱栏围绿玉，天水澹空明。","雨歇蒲芽长，风来柳浪轻。","蓬瀛他日梦，濠濮此时情。","岸帻无尘到，何须更濯缨。"]},{"t":"西园十咏 其三 瑞泉井","f":"五言律诗","c":["一泓终不竭，混混只如斯。","积润浇花圃，分津及玉池。","烹茶亭午后，漱齿月明时。","万国红炉里，幽人总不知。"]},{"t":"西园十咏 其四 翠鳞渠","f":"五言律诗","c":["池光摇赤日，鱼性正怀新。","汲井翻银浪，清渠蹙翠鳞。","桔槔看物变，升斗笑波臣。","试问临流者，兰亭第几人。"]},{"t":"西园十咏 其五 柳径","f":"五言律诗","c":["未赋归来句，还依五柳旁。","池平清镜晓，风澹翠眉长。","莺影迎朝旭，蝉声送晚凉。","清阴元不定，永日几移床。"]},{"t":"西园十咏 其六 茶寮","f":"五言律诗","c":["竹炉烟似缕，新水井花明。","稍觉旗枪战，微闻风雨声。","开瓶倾露乳，解带吸云英。","何异卢仝宅，萧然茅屋清。"]},{"t":"西园十咏 其七 荻塘","f":"五言律诗","c":["小园微雨霁，步屐出横塘。","荻苇丛生处，水禽相与翔。","幽栖元泽国，高咏即沧浪。","不待秋风起，莼鲈头已长。"]},{"t":"西园十咏 其八 蔬畦","f":"五言律诗","c":["家有荷锄仆，囊无入市钱。","垄畦才就列，青翠各依然。","雨过催新甲，宾来屡摘鲜。","汉阴机已息，高枕上皇年。"]},{"t":"西园十咏 其九 酌霞楼","f":"五言律诗","c":["缥缈危楼上，鸾车路岂赊。","谁知虚白室，自近太清家。","何物堪长醉，仙童进晚霞。","下看人代速，木槿是空花。"]},{"t":"西园十咏 其十 听月台","f":"五言律诗","c":["台迥悬明镜，嫦娥欲近人。","御风鸣玉佩，度汉响冰轮。","灵药杵初歇，霓裳曲更新。","寥寥云水意，想像翠蛾颦。"]},{"t":"七夕立秋戏作古思边","f":"五言律诗","c":["一叶飘残暑，蛩声唤晚愁。","征人正南望，大火复西流。","莫以边城月，来窥乞巧楼。","惟应牛与女，此夕不悲秋。"]},{"t":"中元夜李园池上泛舟","f":"五言律诗","c":["风起横塘浪，涛声接大江。","星河低画舫，鱼鸟识新腔。","酒态各争长，谈锋未易降。","花源深几许，岛外吠仙尨。"]},{"t":"金陵秋兴六首 其一","f":"五言律诗","c":["晚出城西望，平沙浩渺茫。","昏鸦点古渡，野水落寒塘。","阅世东流急，怀人鸟路长。","莫将孤客鬓，来比菼葭苍。"]},{"t":"金陵秋兴六首 其二","f":"五言律诗","c":["去去秦淮水，微波蹙细鳞。","尚浮千古月，几泛六朝人。","春到才通舫，秋来只渐轮。","因悲时代改，东海总成尘。"]},{"t":"金陵秋兴六首 其三","f":"五言律诗","c":["一作愁霖唱，寒蛩亦和歌。","漏天谁复补？","浊浪更扬波。","瓮牖嗟薪桂，侯门换绮罗。","沉沉江路黑，时报绿林过。"]},{"t":"金陵秋兴六首 其四","f":"五言律诗","c":["残柳如新柳，依然作淡黄。","纵能牵弱缕，终觉怯繁霜。","少妇房栊冷，征人道路长。","谁家过巧夕，不忍望银潢。"]},{"t":"金陵秋兴六首 其五","f":"五言律诗","c":["高楼闻晚笛，一半入商声。","孤雁惊翻叫，流云惨不征。","凄凉前日事，叹息几时平？","正喜消残暑，霜天寒又生。"]},{"t":"金陵秋兴六首 其六","f":"五言律诗","c":["鸿来燕已去，中道岂相期。","浮世多行役，何人免别离？","酒迎寒露菊，心折故园枝。","只恐东篱笑，归来已后时。"]},{"t":"石头秋望","f":"五言律诗","c":["秋原眺望闲，远目遍江关。","河影摇城堞，吴云入楚山。","风高帆半落，书去雁空还。","正值莼鲈节，渔歌起近湾。"]},{"t":"孟冬二之夜吴翁晋孙燕诒过访","f":"五言律诗","c":["萧疏梧竹里，还似广文官。","客至踏纤月，帘开怯晚寒。","篆烟浮烛细，蒲俎引杯乾。","何物堪留坐，论诗到建安。"]},{"t":"送郭张虚还崇德","f":"五言律诗","c":["白下相逢处，犹歌蜀道难。","无官舌尚在，有泪剑同弹。","棹返五湖远，帆冲片雪寒。","奚囊多锦字，好当万金看。"]},{"t":"冬夜邀韩孟郁过宿赋得席上三物刻烛共成三首 其一 盆石","f":"五言律诗","c":["座有烟霞气，三峰迥不群。","烛摇如挂月，香散欲蒸云。","倚岱曾称丈，临湘或号君。","晚来堪一倚，为我解馀醺。"]},{"t":"冬夜邀韩孟郁过宿赋得席上三物刻烛共成三首 其二 盆竹","f":"五言律诗","c":["湘妃摇绿袖，一夜到庭隅。","未可为龙杖，偏宜待凤雏。","微风吹缥缈，清籁入虚无。","错认兰亭会，流觞对酒徒。"]},{"t":"冬夜邀韩孟郁过宿赋得席上三物刻烛共成三首 其三 盆松","f":"五言律诗","c":["岁寒风飒飒，帘外倒飞霜。","爱尔龙鳞嫩，移之石几旁。","㔉苓持斧远，偃盖拂云长。","总是他年事，从君觅异方。"]},{"t":"岁暮书怀二首 其一","f":"五言律诗","c":["饥凤不吸粟，耻同鸡鹜肥。","丈夫傲骨在，意气排云飞。","五斗羞微禄，三冬未授衣。","寄言陶处士，岁晏愿同归。"]},{"t":"岁暮书怀二首 其二","f":"五言律诗","c":["暄和风日好，晓上酌霞楼。","闾巷如塍错，轩车若水流。","感时堪一笑，吊古起千愁。","何处期鸾鹤，西山最上头。"]},{"t":"和苏汝载雪诗四首 其一","f":"五言律诗","c":["积素接华裀，光浮白氎巾。","凤城疑不夜，花木竟先春。","姑射来仙子，瑶池见舞人。","徵歌何处好，偏爱郡中新。"]},{"t":"和苏汝载雪诗四首 其二","f":"五言律诗","c":["试问前朝事，兴亡竟若何。","陈宫久寂寞，玉树尚嵯峨。","冻集城乌静，风回夜柝多。","诗成何所赠，应付雪儿歌。"]},{"t":"和苏汝载雪诗四首 其三","f":"五言律诗","c":["薄暮寂无哗，同云冷万家。","不闻吹玉笛，但见落梅花。","翠失梁园竹，晶凝剡曲沙。","三杯催作赋，字字是瑶华。"]},{"t":"和苏汝载雪诗四首 其四","f":"五言律诗","c":["正忆长门冷，还伤绝塞寒。","窥帘同泪落，倚剑拂花残。","貂帽何时赐，羊车入梦看。","寄言新燕尔，此际异悲欢。"]},{"t":"己酉除夕同苏汝载守岁","f":"五言律诗","c":["名香手自焚，虚室坐氤氲。","客是他乡聚，年从残烛分。","头颅空老大，鸡鹜耻同群。","明日探春去，相期弄白云。"]},{"t":"春早","f":"五言律诗","c":["春早馀寒在，西园未看花。","病为断酒客，懒拒卖书家。","闭閤观空理，无心玩物华。","参禅今渐熟，但欠制袈裟。"]},{"t":"题张大理荣赠册","f":"五言律诗","c":["荀里曾占瑞，韦经真胜金。","箕裘三代业，风木百年心。","紫府回鸾诰，玄台捧玉音。","当因家庆远，转觉主恩深。"]},{"t":"修褉日苏汝载介绍林茂之昆玉过我西园小酌同赋","f":"五言律诗","c":["和风吹嫩绿，有客到西园。","留坐非关酒，论交不在言。","琴书当昼静，蜂蝶入花喧。","畅矣群贤会，清池绕蕙荪。"]},{"t":"赠山中隐者","f":"五言律诗","c":["一屋带云局，萧然万虑清。","山泉入厨灶，石乳煮藜羹。","月静猿规帐，林疏鹤伴行。","却嫌居未僻，樵子尚知名。"]},{"t":"病起伤春","f":"五言律诗","c":["性以闲逾懒，神缘病后清。","风来还有信，花落太无情。","不浅芳郊兴，难寻漉酒生。","西园数株柳，聊坐一听莺。"]},{"t":"闻虏大入辽阳","f":"五言律诗","c":["不见雷霆怒，悲风白日阴。","谁传寒外箭，空费帑中金。","鬼哭川流血，春归燕在林。","江南佳丽地，莫忆翠华临。"]},{"t":"飞来双白鹤","f":"五言律诗","c":["乘风同矫翮，瘦骨是胎仙。","别去冰弦怨，归栖珠树连。","吹闻缑氏岭，寒忆帝尧年。","可笑人间世，累累自墓田。"]},{"t":"天界寺十咏 其一 疏钟","f":"五言律诗","c":["高高带云敲，疏越更镗鞳。","古殿吼长鲸，空房醒老衲。","声摩山欲动，响歇岩还答。","夜阑梵呗寂，月照竹间榻。"]},{"t":"天界寺十咏 其二 清磬","f":"五言律诗","c":["割来罗浮石，洗以泗滨水。","清冷击云根，飘萧拂尘耳。","翻经猿鸟集，演法人天喜。","勿言音韵微，更探无声始。"]},{"t":"天界寺十咏 其三 古钵","f":"五言律诗","c":["莫测降龙处，中涵沧海深。","愿将无漏水，洗我有为心。","但受香厨饭，休承长者金。","词人幽兴发，一击起高吟。"]},{"t":"天界寺十咏 其四 妙香","f":"五言律诗","c":["一缕若无烟，飘飖度微眇。","劫火岂能烧，慈云自相绕。","不从气味入，远出鼻根表。","过院几人闻，心清方了了。"]},{"t":"天界寺十咏 其五 莲灯","f":"五言律诗","c":["大放白毫光，红莲火中发。","迢迢照诸天，朗朗烛细发。","添油如江河，扬焰并日月。","慧者代为传，妙明永无歇。"]},{"t":"天界寺十咏 其六 蒲团","f":"五言律诗","c":["容膝岂求馀，趺跏终日夕。","面壁寂无言，观空了不隔。","阶前莓苔深，户外蛛网积。","直至十年后，点头是顽石。"]},{"t":"天界寺十咏 其七 法鼓","f":"五言律诗","c":["天乐晚相和，阗阗发高奏。","试听海潮音，亦带灵鼍吼。","新雷绕广殿，宝雨飞晴昼。","馀响遍大千，修罗息其斗。"]},{"t":"天界寺十咏 其八 风铎","f":"五言律诗","c":["殿阁凭虚构，檐牙紫翠分。","风回惊怖鸽，铎响落层云。","山晓烟中见，林昏雨外闻。","居高声更远，羡尔出尘氛。"]},{"t":"天界寺十咏 其九 锡杖","f":"五言律诗","c":["伏虎在床前，携行处处禅。","云林亦何意，去住本随缘。","霞外卓随鹤，山根拄出泉。","许询对支公，亹亹几绝倒。"]},{"t":"天界寺十咏 其十 松烟","f":"五言律诗","c":["疏松石路小，烟霭复周遭。","翠鬣如新沐，苍鳞泛白涛。","鸟归迷故树，僧过湿方袍。","既到空王宇，秦官莫自高。"]},{"t":"过俞君宜天界寺斋中爱其窗前丛竹漫赋","f":"五言律诗","c":["爱君窗下竹，萧瑟起清风。","积爽延秋入，流阴荡暑空。","翠涛翻枕簟，珠佩绕房栊。","梦醒衣裳冷，疑游湘水东。"]},{"t":"新秋登回雁峰","f":"五言律诗","c":["城郭晚苍苍，蝉声送早凉。","薄游同逐客，作赋拟哀湘。","乡信南来断，江流北去长。","高峰尔何意，不遣雁随阳。"]},{"t":"橘井观二首 其一","f":"五言律诗","c":["入户衣裳冷，傍檐苍翠阴。","主人已跨鹤，芳树尚悬金。","缥缈游仙路，迟回恋母心。","真源知几许，看取井泉深。"]},{"t":"橘井观二首 其二","f":"五言律诗","c":["空明澄碧甃，恍惚见丹砂。","谁悟一泓里，遥连三岛涯。","闲心同酌水，隐吏可餐霞。","愿折庭前叶，浮为海上槎。"]},{"t":"婕妤怨","f":"五言律诗","c":["秋水落芙蓉，秋风冷团扇。","君王素綦绝，草色玉阶遍。","发堕云满肩，愁来雨沾面。","谁将好明月，夜夜昭阳殿。"]},{"t":"荆妻剥笋为供戏赋示之","f":"五言律诗","c":["衙斋客不到，竹里失群贤。","且剥班龙尾，来参玉版禅。","铜铛澄涧水，厨火杂山烟。","庑下还如此，烦君举案前。"]},{"t":"初度值先慈讳日中夜感叹成四十字","f":"五言律诗","c":["马齿看将老，春愁黯未醒。","半生疑发白，三仕尚银青。","落月风吹树，啼乌夜绕庭。","蓼莪歌更苦，肠断不堪听。"]},{"t":"壬子清明","f":"五言律诗","c":["每逢簪柳日，却忆上坟时。","雨露亲恩重，松楸节序移。","春残无北雁，客泪洒南枝。","多谢啼鹃意，吾归未有期。"]},{"t":"后园课仆艺植","f":"五言律诗","c":["小园新雨霁，深草乱鸣蛙。","旭日移帘影，光风转物华。","地偏宜小隐，宦拙学农家。","谁道青门远，儿童已种瓜。"]},{"t":"四月十五月食半轮","f":"五言律诗","c":["明明三五夜，正好舞霓裳。","何处麒麟斗，翻为蟾兔伤。","宝奁愁半掩，桂影澹无光。","可是嫦娥懒，才成半面妆。"]},{"t":"梅雨","f":"五言律诗","c":["十日黄梅雨，萧条竹外扉。","冷然披白袷，倏矣化缁衣。","尚怯春寒在，还怜酒伴稀。","开樽聊一笑，赖有鳜鱼肥。"]},{"t":"虚亭","f":"五言律诗","c":["独坐不知久，虚亭澹入禅。","风恬薰柳醉，云懒倚山眠。","宦况半盂水，斋心一缕烟。","回头问身世，疑在散花天。"]},{"t":"七夕前二日焚香夜坐听张无名侍儿吹箫","f":"五言律诗","c":["吹箫延爽籁，一半是商音。","清夜寥寥永，长河澹澹阴。","篆烟浮月上，凤曲度云沉。","试问停梭女，能忘弄玉心。"]},{"t":"秋夜雨","f":"五言律诗","c":["绝塞闻茄泪，虚窗听雨心。","共牵千种恨，并是一悲音。","已厌宾鸿叫，还添蟋蟀吟。","乡关凭梦去，莽莽水云深。"]},{"t":"万岁节","f":"五言律诗","c":["拜舞天门晓，红云极望深。","北风吹广乐，南国若闻音。","仙掌秋澄露，祥光镜铸金。","湘江长北向，可比远臣心。"]},{"t":"西湖塘","f":"五言律诗","c":["芳草满湖阴，人家隔碧浔。","留连鱼鸟语，澹荡水云心。","浅立长堤上，微闻横吹音。","采莲欲有赠，惆怅楚江深。"]},{"t":"出塞曲","f":"五言律诗","c":["结交连六郡，负羽殉王师。","主将方尝胆，男儿誓裹尸。","鐎声静虎落，剑气喷龙旗。","警夜寒难寝，阴山雨雪时。"]},{"t":"冬夜梦","f":"五言律诗","c":["斗帐睡梅花，霜华隔牖纱。","疏钟遥拂曙，残梦乍离家。","镊白形容老，还丹日月赊。","却嫌眠兴剧，思饮建溪茶。"]},{"t":"孟冬同陈袁诸子泛舟入郴","f":"五言律诗","c":["楼船纤锦缆，箫鼓散江天。","此夕潇湘上，人看李郭仙。","卷帘初上月，流水入鸣弦。","试问波间鸟，应知隐吏贤。"]},{"t":"永兴道中人家","f":"五言律诗","c":["一径穿林杪，群山护竹扉。","秋高禾黍熟，日暮牛羊归。","窗外浮云度，厨前瀑水飞。","平生丘壑意，对你益忘机。"]},{"t":"送西席陈玉阳携年儿南归二首 其一","f":"五言律诗","c":["肝胆久相照，吾儿即若儿。","趋庭惭问礼，立雪得严师。","绛帐春风早，青灯夜漏迟。","谁能弹别鹤，正值岁寒时。"]},{"t":"送西席陈玉阳携年儿南归二首 其二","f":"五言律诗","c":["旅况万山中，凄清谁与同。","留连一夜话，稍觉四愁空。","薄宦看孤剑，离人怨断鸿。","绨袍无限意，前路雪兼风。"]},{"t":"夜坐","f":"五言律诗","c":["吏散重门闭，闲斋暮雀过。","卷帘引新月，笼烛辟飞蛾。","砌冷黄花瘦，城高白露多。","真成栖隐地，不必问云萝。"]},{"t":"郴阳署中冬夜","f":"五言律诗","c":["夜坐篆消烟，素心谁与传。","衙斋倚云外，箕颍即阶前。","月挂猿栖树，鸿啼霜霁天。","冷然如有得，此地本宜仙。"]},{"t":"郴阳珠雪季冬二日后十三日立春","f":"五言律诗","c":["万壑风云壮，鸣珠打牖纱。","寒应催腊变，怪不作春花。","署冷独眠鹿，城孤只噪鸦。","宿炉残火在，绿酒不须赊。"]},{"t":"郴阳癸丑元日","f":"五言律诗","c":["乾坤车盖里，日月转双轮。","三载官仍旧，今朝岁又新。","悠悠长作客，事事不如人。","已占深山住，何须羡隐沦。"]},{"t":"新春猎户献虎","f":"五言律诗","c":["昔日食官马，今朝逢猎人。","金睛宁烁电，玉爪不妨身。","杀气消长啸，寒山入早春。","持将劝元恶，勿与祸为邻。"]},{"t":"元夕郴民数百人各持灯献看鱼龙曼衍颇慰岑寂","f":"五言律诗","c":["张灯元旧俗，冒雨且冲泥。","杂沓鱼龙戏，荧煌火树齐。","山歌声上下，野舞影东西。","节序同民乐，孤城且暂栖。"]},{"t":"元夕曲回文学梁陈体","f":"五言律诗","c":["冰开暖水绿，午夜赏春华。","灯捧蟾宫月，火衔莲炬花。","绳危袅利屣，埒小斗轻车。","朋好联歌宴，渑如酒味嘉。"]},{"t":"春夜雨","f":"五言律诗","c":["卧起自徐徐，闲情任卷舒。","馀寒正月里，微雨五更初。","绿遍湘南草，鸿回岭外书。","朝来问詹尹，再卜几年居。"]},{"t":"咏东园鹊巢","f":"五言律诗","c":["星月频惊夜，南飞欲傍谁？","占风来善地，择木得高枝。","阴雨难侵牖，春虫足哺儿。","年年秋报喜，牛女有佳期。"]},{"t":"春晴","f":"五言律诗","c":["残云消雨脚，晴日丽东轩。","扫地还除湿，焚香更助喧。","蝶蜂狂欲舞，桃李静无言。","草色交行径，翻疑仲蔚园。"]},{"t":"拟春闺晓起","f":"五言律诗","c":["春深节气柔，独夜贮春愁。","欹枕钟敲梦，开檐月在钩。","栏花怜并倚，林鸟语相求。","女伴催妆竟，招邀淇上游。"]},{"t":"正月晦日晴","f":"五言律诗","c":["久雨沉山郭，苔衣上半墙。","晴云噪乌鹊，晦日足风光。","把酒春愁破，摊书午梦长。","东园花正好，蜂蝶不须忙。"]},{"t":"下泷暴潦忽涨险过吕梁定后戏笔","f":"五言律诗","c":["潦涨翻惊险，装轻自觉夷。","浮生元有命，蹈水信无私。","傲骨寒崖并，贞心鬼物知。","悠悠看出峡，对酒夕阳迟。"]},{"t":"下泷后逢午日韶阳观竞渡","f":"五言律诗","c":["危泷天上落，小艓片时过。","幸不填鱼腹，那堪吊汨罗。","双龙腾暮雨，两岸激洪波。","酌罢敲韶石，临风奏九歌。"]},{"t":"归里恭谒先墓","f":"五言律诗","c":["游子天涯返，松楸大几围。","腰横新束带，肠断旧斑衣。","怪鸟如人哭，凄风拂泪飞。","还惊云日暗，错认梦中归。"]},{"t":"题卢元明白云楼","f":"五言律诗","c":["楼居原夙好，便可挟飞仙。","尽眺大千界，还看尺五天。","山河思往事，城郭阅流年。","为问安期子，何时驾鹤旋。"]},{"t":"端溪舟中听雨与陈永平对酌","f":"五言律诗","c":["客有迷津叹，那堪暮雨时。","篷声兼棹响，云脚带帆移。","节序催新历，壶觞对故知。","茫茫今古事，流水只如斯。"]},{"t":"癸丑冬至泷上感怀","f":"五言律诗","c":["那堪行役日，正值闭关时。","水落滩泷险，风高舟楫迟。","谁添绣里线？","空长鬓边丝。","剥复无穷尽，浮生只自疑。"]},{"t":"泷险","f":"五言律诗","c":["高流奔急峡，一转一回新。","日夜闻风雨，艰危泣鬼神。","水花舷上棹，泡影幻中身。","行路难如此，年年有问津。"]},{"t":"癸丑季冬过黄州柴羽元方伯胡存蓼张玄中两宪副招游赤壁时江风不可以舟同酌苏祠台上得五首 其一","f":"五言律诗","c":["洪流吞绝壁，危堞挂长虹。","一睹江山丽，方知词赋工。","野烟低晚照，旧恨问东风。","欲写前朝事，凭栏想像中。"]},{"t":"癸丑季冬过黄州柴羽元方伯胡存蓼张玄中两宪副招游赤壁时江风不可以舟同酌苏祠台上得五首 其二","f":"五言律诗","c":["三分堪一笑，两赋足千秋。","成败浑如梦，山川尚带愁。","潮来疑战鼓，叶落想残舟。","多少英雄泪，长江不尽流。"]},{"t":"癸丑季冬过黄州柴羽元方伯胡存蓼张玄中两宪副招游赤壁时江风不可以舟同酌苏祠台上得五首 其三","f":"五言律诗","c":["昔人浮一叶，我辈上层台。","斗酒兼鱼至，东山送月来。","雄风催作赋，霜气避传杯。","郢调今还几，因君问楚材。"]},{"t":"癸丑季冬过黄州柴羽元方伯胡存蓼张玄中两宪副招游赤壁时江风不可以舟同酌苏祠台上得五首 其四","f":"五言律诗","c":["乘舟能犯斗，倚槛亦摩霄。","道士如相遇，飞仙或可招。","台高堪抱月，夜静忆吹箫。","叹息词人去，江城倍寂寥。"]},{"t":"癸丑季冬过黄州柴羽元方伯胡存蓼张玄中两宪副招游赤壁时江风不可以舟同酌苏祠台上得五首 其五","f":"五言律诗","c":["一瞬成陈迹，乾坤大转轮。","江山非属我，风月偶随人。","乘兴骑孤鹤，毋劳吊逐臣。","安知今夜客，不是德云身。"]},{"t":"游黄州赤壁有怀海内旧社诸子 二首 其一","f":"五言律诗","c":["笑倚千寻壁，还如醉客容。","火攻推上将，笔战让词锋。","往事台前水，离心江上峰。","长怀集文彦，刻烛探骊龙。"]},{"t":"游黄州赤壁有怀海内旧社诸子 二首 其二","f":"五言律诗","c":["汉水鸭头绿，临江兴倍长。","丹枫寒映壁，白露暮为霜。","对酒夜将半，美人天一方。","无由寄征雁，明发指衡阳。"]},{"t":"赤壁谒大苏祠问而吊之","f":"五言律诗","c":["妙高前日事，试问是耶非。","便可呼金粟，何须梦羽衣。","当时作赋去，几岁御风归。","夜夜江灵泣，狂涛打石矶。"]},{"t":"岁暮过长安驿有感","f":"五言律诗","c":["长安无梦到，此驿号长安。","不遇迷津苦，谁知望阙难。","日随心共远，岁与鬓同残。","更尽湖南路，群山拥汉官。"]},{"t":"岁暮十六日大雪夜行衡山道中","f":"五言律诗","c":["残冬寒作阵，半夜远游身。","雪坠花千片，云沉月一轮。","问更呼驿吏，分酒劳舆人。","茅屋多琼树，谁知村落贫。"]},{"t":"甲寅永郡元日","f":"五言律诗","c":["去岁还今岁，郴州又永州。","乾坤元客舍，身世与云浮。","薄宦好藏拙，携家且缓愁。","年来心事澹，湘水共悠悠。"]},{"t":"寒食雨","f":"五言律诗","c":["孤城细雨中，惆怅度佳节。","禁火食犹寒，思乡心转热。","花兼春共老，世与人相阅。","何事不归来，官闲好藏拙。"]},{"t":"清明又雨","f":"五言律诗","c":["层云暗远郊，骤雨打虚牖。","无计护残花，何心簪弱柳。","春游滞泥泞，旅况消杯酒。","昨日酿葡萄，床头馀数斗。"]},{"t":"衙斋清旷独缺名花玺卿周元汀缮部屈钟湘各贻我牡丹一本喜赋","f":"五言律诗","c":["伤春无意绪，脉脉近花朝。","佳客能相赠，花王不待招。","纤腰垂绿袖，醉颊晕红潮。","曲槛怜相并，江东大小乔。"]},{"t":"花朝午后忽晴坐含清阁","f":"五言律诗","c":["常疑天似漏，青帝懒司花。","岂料喧灵鹊，还能转日车。","芳菲明绿野，点缀倩红霞。","最爱斜阳外，遥村四五家。"]},{"t":"午睡","f":"五言律诗","c":["莺慵燕又懒，春睡午偏浓。","世事看双枕，仙方授五龙。","香消金□□，帐冷水芙蓉。","童子呼茶熟，斜阳已下舂。"]},{"t":"悲长城","f":"五言律诗","c":["征夫三十万，总为筑城来。","挥泪无乾土，舂声起旱雷。","春闺人入梦，霜碛骨吹灰。","万古长城下，愁云暗不开。"]},{"t":"夏朝阁望","f":"五言律诗","c":["清晨登小阁，爽气似新秋。","风静炉烟直，园深鸟语幽。","楚山和雾睡，湘水夹霞流。","望望芳洲外，遥怜不系舟。"]},{"t":"遥村","f":"五言律诗","c":["野水落田鸣，遥村雨后清。","老农方敮耒，好鸟又催耕。","饷馌甘藜藿，占年验晦晴。","家山有黄犊，一轸故园情。"]},{"t":"暑雨新霁登阁眺望","f":"五言律诗","c":["霁望天如洗，山川一片新。","清江遥影阁，凉气自侵人。","火宅寰中地，冰壶世外身。","晚来晞短发，华月更相亲。"]},{"t":"暑夜起坐","f":"五言律诗","c":["昼有北窗眠，宵还倚槛前。","月凉天似水，城静漏如年。","浴想黄姑渚，舟思太乙莲。","徘徊惜清景，休促烛龙鞭。"]},{"t":"看仆锄园灌蔬","f":"五言律诗","c":["簿领全休暇，科头傍竹林。","犹存学圃意，颇异拔葵心。","抱瓮看僮仆，忘机亦汉阴。","挥锄谁不顾，瓦砾视黄金。"]},{"t":"暑坐咏怀","f":"五言律诗","c":["退食午多暇，偷安厌日长。","小堂开绝巘，幽桂夹丛篁。","湘簟铺寒玉，纱帷卷薄霜。","南薰调一曲，吾欲贾馀凉。"]},{"t":"啖藕","f":"五言律诗","c":["虚堂爽气澄，嘉藕破炎蒸。","忽听刀裁玉，翻疑夏造冰。","甘香消渴吻，皎洁辟飞蝇。","为报湘流女，毋劳唱采菱。"]},{"t":"甲寅六月苦旱祈祷二首 其一","f":"五言律诗","c":["暗洒疮痍泪，悲歌云汉诗。","那堪望霈候，已过濯枝时。","永日烦巫祝，中宵验毕箕。","潇湘通水府，无路问玄夷。"]},{"t":"甲寅六月苦旱祈祷二首 其二","f":"五言律诗","c":["旷宇云屯火，清江浪沸汤。","苍生呼涸辙，赤帝转骄阳。","金石将焦铄，风沙屡作狂。","儿童纷拜舞，何不学商羊。"]},{"t":"立秋书怀","f":"五言律诗","c":["一叶下梧梢，微凉入远郊。","乡山梦里到，岁月客中抛。","宦况秋偏淡，尘容镜代嘲。","蒹葭迎早露，天末忆贫交。"]},{"t":"小著","f":"五言律诗","c":["自笑儒兼吏，芸窗竹影中。","雄心消跃马，幽兴寄雕虫。","钴鉧潭前月，愚溪树里风。","寂寥长对此，染翰当书空。"]},{"t":"秋夜","f":"五言律诗","c":["庭梧凋一叶，忽到授衣时。","懒妇未鸣杼，寒虫已络丝。","城高霜信早，夜永漏声迟。","旅况须沉醉，黄花满竹篱。"]},{"t":"芝城甲寅除夕对表舅钱荆石守岁","f":"五言律诗","c":["剪烛酌深夜，山城寂不哗。","冬春分岁色，梅柳竞年华。","北斗频瞻阙，南云苦望家。","愿持千日酒，得免二毛嗟。"]},{"t":"谷日立春喜晴","f":"五言律诗","c":["好鸟语高枝，东风转日迟。","流年催白发，生菜妒青丝。","岁色晴明里，农祥宴喜时。","独怜新彩胜，不照故园卮。"]},{"t":"归兴诗六首 其一","f":"五言律诗","c":["世路纷惊眼，瞿塘更孟门。","缴还腰下组，归去谷中村。","桂树堪招隐，桃花欲问源。","从今三径草，不敢怨王孙。"]},{"t":"归兴诗六首 其二","f":"五言律诗","c":["龙性谁能降，鸥盟自可亲。","好将湘上水，一洗马前尘。","蕙帐眠山月，荷衣伴角巾。","罗浮峰四百，猿鸟已迎人。"]},{"t":"归兴诗六首 其三","f":"五言律诗","c":["岂为疑蛇影，吾其料虎须。","生来无媚骨，故态本狂奴。","仙境多羊石，南溟胜镜湖。","何妨携雨管，窗下著潜夫。"]},{"t":"归兴诗六首 其四","f":"五言律诗","c":["故乡今已到，更有醉中乡。","儿解腌蒲俎，妻能录酒方。","朝朝九酝里，日日七贤旁。","莫笑馀全懒，栽花雨后忙。"]},{"t":"归兴诗六首 其五","f":"五言律诗","c":["一村如斗大，烟月颇无边。","已创祝鸡栅，还开放鹤田。","浦沙堪系艇，鱼鳖不论钱。","直到归耕处，方知沮溺贤。"]},{"t":"归兴诗六首 其六","f":"五言律诗","c":["竹园吾旧里，改号小柴桑。","松菊径还在，壶觞日更长。","云边闻吠犬，花下问渔郎。","谁似清都客，惟留鹿鹤粮。"]},{"t":"挽孝廉张无名二首 其一","f":"五言律诗","c":["衙署连床语，曾扳十日留。","才回衡岳驾，忽作岱宗游。","琪树标清骨，丛兰陨早秋。","云中还载笔，知有玉为楼。"]},{"t":"挽孝廉张无名二首 其二","f":"五言律诗","c":["壮志一抔土，馀香侠骨存。","平生好结客，今日几过门。","赋鵩年华促，招魂怨思繁。","巫阳不可问，风雨暗天阍。"]},{"t":"闻尹禺阳下第愁病赋此代柬招过剧谈","f":"五言律诗","c":["易下刘蕡泪，秋思怯早凉。","萧条怜病骨，烦恼问医王。","雨过石坛净，风轻砌药香。","高斋堪对语，烂醉是仙方。"]},{"t":"送林坦之北上春官","f":"五言律诗","c":["鹪枝予偃息，鹏运子夷犹。","执手肝肠热，扬帆江海秋。","新花看上苑，旧榻冷南州。","京贵如相问，人今理钓舟。"]},{"t":"乙卯季秋十九日周剑云尹和石周石林载酒集予天坐轩鼓吹乘潮访祁恒季绿水园招祁伊吾同酌弄月江上酣剧而返得二首 其一","f":"五言律诗","c":["主人元习静，酬对了清言。","门恭俗尘远，琴书世业存。","松风寒泛酒，江练澹浮轩。","不是求羊辈，谁过蒋诩园？"]},{"t":"乙卯季秋十九日周剑云尹和石周石林载酒集予天坐轩鼓吹乘潮访祁恒季绿水园招祁伊吾同酌弄月江上酣剧而返得二首 其二","f":"五言律诗","c":["明月美清夜，金波拂棹流。","风霜缠急管，天地肃高秋。","向若醉还语，飞仙挟共游。","玉绳低可缀，倩汝暂维舟。"]},{"t":"送尹禺阳应贡北上三首 其一","f":"五言律诗","c":["百花迎马首，北上正乘春。","京国游偏壮，琴书箧未贫。","九霄瞻日月，寸管达枫宸。","再献天人策，临轩下问频。"]},{"t":"送尹禺阳应贡北上三首 其二","f":"五言律诗","c":["长安在日下，有梦到春明。","忽作临河别，遥悬恋阙情。","逢时鹏路阔，玩世钓舟轻。","燕市多朋好，因君一寄声。"]},{"t":"送尹禺阳应贡北上三首 其三","f":"五言律诗","c":["亦曾叨里选，尚忆北游年。","岂料予投劾，方看尔着鞭。","乡心珠海月，旅况蓟门烟。","可念离居者，归程在雁先。"]},{"t":"春晚","f":"五言律诗","c":["幽亭浮彩翠，宴坐只焚香。","花静闻蜂语，人闲觉燕忙。","世情这里淡，春日为谁长。","疏懒元吾性，非关学列庄。"]},{"t":"送沈青海归四明","f":"五言律诗","c":["四海知音少，三杯语别长。","诗名推雁字，侠气动鱼肠。","自笑烟霞懒，怜君客路忙。","归舟花拥棹，好醉若耶旁。"]},{"t":"夏日积雨应季伟陈治甫周贵谔李伯修载酒过小斋池上酌赋","f":"五言律诗","c":["扫径愁冲雨，论文快聚星。","门多载酒客，人愧草玄亭。","护烛低垂幔，飞觞走建瓴。","小池云雾里，疑有老龙听。"]},{"t":"秋闺晓思","f":"五言律诗","c":["凉吹度深闺，窥窗片月低。","征人三载别，思妇五更啼。","积泪浮孤枕，繁霜叫晓鸡。","寸心灰未冷，夜夜梦辽西。"]},{"t":"村中秋泛","f":"五言律诗","c":["积潦浩无际，人来狎钓翁。","放船宜落日，破浪信长风。","葭菼霜华外，村原水气中。","转疑空阔处，或与五湖通。"]},{"t":"秋夜池边坐月","f":"五言律诗","c":["静对秋宵月，弥清物外心。","池光浮木榻，竹影扫瑶琴。","钟罢千门寂，河低五夜深。","候虫知节序，唧唧亦长吟。"]},{"t":"自笑","f":"五言律诗","c":["泉石元良友，巢由亦外臣。","老因诗度日，闲以酒藏身。","自笑狂非妄，谁怜懒是真？","闭门尘事少，踪迹似逃秦。"]},{"t":"王右仲过紫烟玩月周贵谔同酌","f":"五言律诗","c":["楼台延二妙，风月正双清。","共坐红尘外，如邻白玉京。","高谈吹爽籁，疏漏滴严城。","借问沉眠者，宁知秉烛情。"]},{"t":"忆鹤诗","f":"五言律诗","c":["悔将双羽客，博得一云屏。","罨画摩寒玉，霜衣忆素翎。","高楼中夜起，清唳隔林听。","何事关人意，仙禽旧姓丁。"]},{"t":"月到床","f":"五言律诗","c":["四照轩棂敞，疏帷透月明。","乍眠肌骨冷，永夜梦魂清。","戏泛金波浴，如听玉杵鸣。","谁云天路远，咫尺是瑶京。"]},{"t":"浮邱漫兴次李烟客韵四首 其一","f":"五言律诗","c":["傲骨逢时拙，悬车四载馀。","逍遥思化国，清寂得仙居。","洞閟真人录，碑存太史书。","翛然谐独往，高枕即吾庐。"]},{"t":"浮邱漫兴次李烟客韵四首 其二","f":"五言律诗","c":["潮生丹井满，折苇可为舟。","欲识神仙意，还同江海鸥。","未穷三岛路，权作五湖游。","何处多灵草，吾先向祖洲。"]},{"t":"浮邱漫兴次李烟客韵四首 其三","f":"五言律诗","c":["独占郊原胜，平临水石分。","岩含三秀草，门对十洲云。","风静停幡影，人来混鹿群。","只疑棋伴里，或有紫阳君。"]},{"t":"浮邱漫兴次李烟客韵四首 其四","f":"五言律诗","c":["亭台询往事，相国旧行春。","莲社推诗长，銮坡作帝宾。","荣名终白首，澹泊是玄津。","再检谪仙籍，天南近几人。"]},{"t":"戊午清明旗峰踏青因忆客岁是日携常湘云赋春游篇往事东流共增感叹二首 其一","f":"五言律诗","c":["共有杖头钱，同鸣郭外鞭。","平芜初歇雨，嫩绿远连天。","游兴看簪柳，春声乍听鹃。","桃花思往日，对酒一潸然。"]},{"t":"戊午清明旗峰踏青因忆客岁是日携常湘云赋春游篇往事东流共增感叹二首 其二","f":"五言律诗","c":["绿阴团翠幄，白袷染红霞。","宴笑宜长日，从容数落花。","行厨非宿火，洗碗试新茶。","馀兴还酣畅，城南问酒家。"]},{"t":"飓","f":"五言律诗","c":["飓母挂残虹，飙轮战雨工。","呼号万窍怒，箕荡四方风。","急恐南溟覆，遥怜海舶空。","招魂何处角，声咽黑云中。"]},{"t":"团碧亭前两石池新成水藻鲦鱼颇供静玩","f":"五言律诗","c":["夹镜双池碧，花阴俯玩□。","涟漪涵石丈，升斗贷波臣。","濠濮阶前地，江湖世外身。","何须七里濑，始可慰沉沦。"]},{"t":"暑夜晓起","f":"五言律诗","c":["沧凉夜气清，侵晓坐虚亭。","雾重花犹睡，风多鹤渐醒。","六街尘已动，三径户还扃。","莫怪人驰逐，羲和亦不停。"]},{"t":"戊午交秋患臂作","f":"五言律诗","c":["凉吹惊秋至，孱躯苦病侵。","萧条一叶下，凄恻百年心。","壮志看孤剑，流光惜寸阴。","闲庭聊抱膝，梁父若为吟。"]},{"t":"春朝","f":"五言律诗","c":["熟眠惊鸟唤，晓立傍银塘。","草嫩风偏软，花垂露有香。","百年聊偃息，三径问行藏。","春日迟迟好，人闲更觉长。"]},{"t":"春晚","f":"五言律诗","c":["随缘皆净土，至贵是闲人。","独坐园林里，惟将蜂蝶亲。","群花飞欲尽，百果献犹新。","君看高车者，徒增两袖尘。"]},{"t":"秋莲盛开","f":"五言律诗","c":["蹉跎伤往事，抱膝厌书空。","旧疾生多雨，馀酲析好风。","幽怀从澹荡，老景任穷通。","莫笑栽莲晚，秋花盛作红。"]},{"t":"匡云上人同琴客闵谏廷集紫烟楼玩月","f":"五言律诗","c":["新月清如洗，晴光散积阴。","楼台非色界，天地豁虚襟。","轻露调云液，和风泛玉琴。","金波空万里，照见西来心。"]},{"t":"四月六日立夏李伯修招同匡云上人琴客闵谏廷集署中待月向夕风雨聚对率尔成篇","f":"五言律诗","c":["征歌邀皓魄，已奏紫云回。","怅望层阴合，俄闻暮雨来。","银灯吹湿暗，金电划光开。","颇似兰亭会，临阶好泛杯。"]},{"t":"中元后一夕杨二尹朱三尹过西园玩月听闵谏廷琴","f":"五言律诗","c":["秋意过中元，凉开雨后樽。","池台澄霁景，风月入清言。","露重暑全薄，琴闲夜不喧。","何须魏公子，飞盖亦西园。"]},{"t":"游淡岩","f":"五言律诗","c":["一峰悬地肺，四壁倚云根。","但觉堂皇敞，都无斧凿痕。","烟霞邀客坐，猿鸟与人言。","可叹神工巧，难容混沌存。"]},{"t":"麻滩险路","f":"五言律诗","c":["册子澄霜气，沿江木叶纷。","滩牙寒喷雪，岩腹暖蒸云。","处处逢渔父，行行入鹿群。","谁言方外吏，尚愧北山文。"]},{"t":"宿太平乡王氏虚堂","f":"五言律诗","c":["房栊青嶂里，鸡犬白云边。","辙迹经虞帝，民风类葛天。","衣冠淮水远，家世宝刀传。","客借虚堂宿，秋床抱月眠。"]},{"t":"行回溪入九疑","f":"五言律诗","c":["胜情催晓发，霜气澹朝晖。","木落露山骨，溪寒曳水衣。","人家穿竹暗，鸟道入烟微。","处处峰峦似，谁能辨是非。"]},{"t":"谒舜祠四首 其一","f":"五言律诗","c":["帝德光千古，遗踪在九疑。","搴芳荐瑶席，酌桂礼彤墀。","百兽犹环舞，群山相向悲。","欲知龙蜕处，高嶂觅铜碑。"]},{"t":"谒舜祠四首 其二","f":"五言律诗","c":["俎豆传虞代，蘋蘩肃汉官。","岂应迷冢墓，或恐葬衣冠。","松韵如听乐，瑶歌似舞干。","寄言吊古客，当作鼎湖看。"]},{"t":"谒舜祠四首 其三","f":"五言律诗","c":["万里辞黄屋，千秋寄碧岑。","莫嫌山庙冷，方称土阶心。","木石时为偶，英皇恨转深。","微闻松竹里，恍惚凤仪音。"]},{"t":"谒舜祠四首 其四","f":"五言律诗","c":["翠辇虚驰道，玄泉不复通。","国家同弃屣，日月见重瞳。","山鬼幽篁里，鹧鸪秋雨中。","峰头帝子泪，又洒在丹枫。"]},{"t":"三峰石","f":"五言律诗","c":["登眺穷殊胜，兹峰迥不群。","烟霄离五尺，楚粤划三分。","雨过冲雷仗，星飞避剑文。","南天多物怪，倩汝扫魔军。"]},{"t":"秋日访彭贞元留题时适有饷以酒者喜曰吾留客有胆矣可想其风致云","f":"五言律诗","c":["投剌入斋中，应门无小童。","酒添留客胆，诗不妒人穷。","侑酌惟黄菊，承家只素风。","怜君耽市隐，踪迹似墙东。"]},{"t":"和李自得题咏小园上下平韵三十首 其一 一东","f":"五言律诗","c":["青门在郭东，小筑偶然同。","只爱山溪胜，非关木石工。","幽栖宜地僻，简出免途穷。","自觉悬车稳，揶揄笑阮公。"]},{"t":"和李自得题咏小园上下平韵三十首 其二 二冬","f":"五言律诗","c":["城池离二里，溪壑隔千重。","叹世时歌凤，无才愧卧龙。","偶留人下榻，睡到日高舂。","晏起科头者，天南一老农。"]},{"t":"和李自得题咏小园上下平韵三十首 其三 三江","f":"五言律诗","c":["昔曾为壮士，侠气近来降。","学道抛金剑，忘怀倒玉缸。","竹烟朝沐发，松月夜窥窗。","莫道耕无偶，沙边鹤一双。"]},{"t":"和李自得题咏小园上下平韵三十首 其四 四支","f":"五言律诗","c":["为园曾几月，花果亦频移。","燕入惊新主，鸥归识旧池。","听禽徐度曲，对客细敲诗。","何必千间厦，巢林只一枝。"]},{"t":"和李自得题咏小园上下平韵三十首 其五 五微","f":"五言律诗","c":["小楼穿象外，当夏觅秋衣。","星宿巡檐度，云霞拂槛飞。","龙衔真诰下，鹤驾列仙归。","招手洞天使，何人应少微。"]},{"t":"和李自得题咏小园上下平韵三十首 其六 六鱼","f":"五言律诗","c":["放浪郊原外，相羊水竹居。","垂纶聊取适，洗耳异逃虚。","兰径呼僮扫，芝田或自锄。","昼长开卷懒，云湿一床书。"]},{"t":"和李自得题咏小园上下平韵三十首 其七 七虞","f":"五言律诗","c":["荒园浮水镜，人拟小方壶。","山岳交回护，烟波幻有无。","客从穿竹至，酒向隔村沽。","半醉摇渔艇，还如泛五湖。"]},{"t":"和李自得题咏小园上下平韵三十首 其八 八齐","f":"五言律诗","c":["地远人稀到，心闲物自齐。","醉残卯后酒，梦破午时鸡。","得句敲青竹，微吟步绿堤。","幽亭堪点笔，蜗篆已留题。"]},{"t":"和李自得题咏小园上下平韵三十首 其九 九佳","f":"五言律诗","c":["池亭粗部置，水石略安排。","碧乳翻茶碗，丹砂贮药斋。","看山朝更爽，弄霭夕还佳。","徙倚高台上，雄风快入怀。"]},{"t":"和李自得题咏小园上下平韵三十首 其十 十灰","f":"五言律诗","c":["七载赋归来，柴门静不开。","故人频劝驾，明主解怜才。","击水惭鹏翮，生身是鹤胎。","琼华台畔吏，差可并三台。"]},{"t":"和李自得题咏小园上下平韵三十首 其十一 十一真","f":"五言律诗","c":["宦拙非无命，诗成若有神。","宫商一以叶，鱼鸟自相亲。","白眼宜投帻，青云叹积薪。","未须论出处，草莽固称臣。"]},{"t":"和李自得题咏小园上下平韵三十首 其十二 十二文","f":"五言律诗","c":["自从东郭隐，已谢北山文。","诗许山僧校，名羞女子闻。","一竿严濑月，数亩鹿门云。","借问鸳班客，何如鸥鹭群？"]},{"t":"和李自得题咏小园上下平韵三十首 其十三 十三元","f":"五言律诗","c":["抱膝荒凉地，缘何号镜园？","一溪斜进艇，四沼曲环轩。","白练烟中净，青铜浪里翻。","临流闲照胆，挥麈欲忘言。"]},{"t":"和李自得题咏小园上下平韵三十首 其十四 十四寒","f":"五言律诗","c":["山水绝人境，楼台逼广寒。","且携修月斧，更整切云冠。","桂树笼虚阙，银河澜浅澜。","游仙别有路，指点问星官。"]},{"t":"和李自得题咏小园上下平韵三十首 其十五 十五删","f":"五言律诗","c":["远枉青莲驾，重瞻紫气还。","诗名高海内，浪迹寄人间。","击钵催联句，支颐共看山。","细谈濠上理，身外得长闲。"]},{"t":"和李自得题咏小园上下平韵三十首 其十六 一先","f":"五言律诗","c":["垒石置浮屋，因名书画船。","任他风动地，只坐水中天。","重待石帆驾，轻输莲叶仙。","何时泛东海，一借祖龙鞭？"]},{"t":"和李自得题咏小园上下平韵三十首 其十七 二萧","f":"五言律诗","c":["地近紫霞里，仙踪久寂寥。","楼台动遐想，笙鹤似相招。","九转虚丹室，三山透海潮。","翛然乘兴往，岂惮业风飘。"]},{"t":"和李自得题咏小园上下平韵三十首 其十八 三肴","f":"五言律诗","c":["有地堪藏拙，无心作解嘲。","琴知闲里趣，水似淡中交。","清静参禅理，盈虚玩易爻。","怪无蝇鼠到，蔬笋在香庖。"]},{"t":"和李自得题咏小园上下平韵三十首 其十九 四豪","f":"五言律诗","c":["既同元亮隐，休续屈原骚。","骨懒非缘病，名微不用逃。","百忧缠世网，一醉解天韬。","直任渔人入，前溪密种桃。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十 五歌","f":"五言律诗","c":["坐久潮侵户，眠多云满窝。","懒裁穷鸟赋，厌听饭牛歌。","火宅城中地，冰壶槛外波。","自无经世策，敢浪说挥戈。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十一 六麻","f":"五言律诗","c":["荒圃惟栽菊，清溪亦浣花。","藜床临水石，笔格染烟霞。","静坐乌皮几，闲鞭白鼻䯄。","马头尘十丈，失笑忆京华。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十二 七阳","f":"五言律诗","c":["辋川同啸咏，千古羡裴王。","胜地输前辈，高风接后行。","园林留上客，骚雅共平章。","试掬池边水，澄泓泛墨香。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十三 八庚","f":"五言律诗","c":["濯足溪头罢，还随独鹤行。","迂疏成漫叟，礼法恕狂生。","好鸟频催酒，清风为解酲。","眼前多乐事，身后总浮名。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十四 九青","f":"五言律诗","c":["楼角响风铃，秋声日夜听。","霞红天似醉，云破月如醒。","乍觉游仙梦，因之展道经。","藜光谁借照，太乙老人星。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十五 十蒸","f":"五言律诗","c":["波光碧四澄，俯槛若怀冰。","傲骨能轻举，罡风亦可乘。","龙车随竹杖，月路引金绳。","近悟逍遥理，高于入定僧。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十六 十一尤","f":"五言律诗","c":["晓起望南亩，烟中听叱牛。","笑看耕耨者，只为稻粱谋。","作苦怜终岁，登场喜有秋。","社觞须痛饮，满瓮足新篘。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十七 十二侵","f":"五言律诗","c":["无营宜息踵，有客是知音。","幽意谐山水，高谈遍古今。","人如沮溺耦，溪比武陵深。","得句非相促，和风起浪吟。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十八 十三覃","f":"五言律诗","c":["避喧来净土，清景澹相涵。","山色拖空翠，天光抱蔚蓝。","翚飞楼直上，鸟鷇手堪探。","厌苦人间事，嵇康七不堪。"]},{"t":"和李自得题咏小园上下平韵三十首 其二十九 十四盐","f":"五言律诗","c":["吏隐昔难兼，归休万虑恬。","濠鱼还自乐，崖蜜为谁甜？","行处水窥影，坐时风入帘。","忘言惟抱膝，适意略掀髯。"]},{"t":"和李自得题咏小园上下平韵三十首 其三十 十五咸","f":"五言律诗","c":["众口自喃喃，忧讥更畏谗。","欲平急水浪，休使满风帆。","竹牖偏临沼，松庵合傍岩。","黄精冬可斸，吾已制长镵。"]},{"t":"南阳吊卧龙冈","f":"五言律诗","c":["哲人高卧处，龙气尚蒸云。","恩重隆中顾，心劳渭上军。","奇谋存八阵，天意竟三分。","多少英雄恨，归鸦带夕曛。"]},{"t":"入函谷关","f":"五言律诗","c":["枯河走白沙，叠岭锁苍霞。","谷转蟠蛇脊，崖倾斗虎牙。","七雄消霸气，四海正为家。","寄语鸡鸣客，从驰流水车。"]},{"t":"署中滴翠轩杂咏五首 其一","f":"五言律诗","c":["关塞之官远，琴书亦与偕。","谁栽四翠柏？","为荫一清斋。","宦拙世情澹，地偏幽意谐。","浮生元偶寄，何事强安排？"]},{"t":"署中滴翠轩杂咏五首 其二","f":"五言律诗","c":["暑气晚来薄，萧萧树自鸣。","风随微雨到，月向破云明。","簿领闲曹少，园林野兴清。","已能齐显晦，渐觉厌逢迎。"]},{"t":"署中滴翠轩杂咏五首 其三","f":"五言律诗","c":["有客仕三已，何人岁九迁？","浮云倏过眼，司命亦无权。","浪出非初志，微名合避贤。","夜来牵远梦，多在海鸥边。"]},{"t":"署中滴翠轩杂咏五首 其四","f":"五言律诗","c":["吏散重门闭，翛然太隐居。","清凉饶树石，苍翠滴庭除。","薄禄堪供酒，呼僮更种蔬。","寄言弹铗客，此地本无鱼。"]},{"t":"署中滴翠轩杂咏五首 其五","f":"五言律诗","c":["癖诗堪一笑，得句享千金。","比兴皆诸景，推敲哎寸心。","词坛谁胜负，仕路任升沉。","试展探珠手，骊龙伏海深。"]},{"t":"端阳后一日刘觐国招酌署中三首 其一","f":"五言律诗","c":["署近过从易，情深对语真。","虚堂不受暑，嘉树爱留人。","渐觉愁城破，转于欢伯亲。","杯中饶胜地，索醉敢辞频。"]},{"t":"端阳后一日刘觐国招酌署中三首 其二","f":"五言律诗","c":["报国竟无策，怀归多苦吟。","秦城连北斗，越客奏南音。","宦薄从薪积，时危叹陆沉。","独醒良不易，谁识七贤心。"]},{"t":"端阳后一日刘觐国招酌署中三首 其三","f":"五言律诗","c":["隐吏容疏放，馀闲且拍浮。","客筵罗海味，乡思绕龙舟。","令节过蒲酒，和风度麦秋。","相看同逆旅，休上仲宣楼。"]},{"t":"刘觐国馈菜酬以酒","f":"五言律诗","c":["应念庾郎贫，贻来菜甲新。","偏怜摘鲜趣，欲作灌园人。","添我伊蒲馔，酬君曲米春。","西风万里客，此夕不思莼。"]},{"t":"度崤","f":"五言律诗","c":["诘曲云生石，崚嶒磴叠冰。","往来车互击，人马气如蒸。","古驿通三晋，高原没二陵。","因嗟割据者，天险未须凭。"]},{"t":"度圜辕","f":"五言律诗","c":["崤函天下险，尚觉让轘辕。","百折盘孤径，双崖锁一门。","秃松云共袅，怪石虎同蹲。","默忆垂堂戒，吞声未敢言。"]},{"t":"襄阳仲宣楼","f":"五言律诗","c":["汉水暂依刘，秦川忆旧游。","别离悲两地，词赋擅千秋。","去国人同远，行云客共浮。","为嫌归思急，不敢更登楼。"]},{"t":"度溰州兰江","f":"五言律诗","c":["兰江春水满，兰叶正初抽。","系马绿杨树，扬帆青翰舟。","香风吹两岸，旭日照中流。","慷慨思公子，烟波未易求。"]},{"t":"武陵县道旁梅花","f":"五言律诗","c":["积雪犹含冻，孤芳自弄春。","虽当车马道，不杂往来尘。","庾岭遥相望，桃源近接邻。","花神劳指点，吾欲访秦人。"]},{"t":"度沧浪水","f":"五言律诗","c":["皎洁无冬春，清流一镜新。","风恬波浩浩，岸险石粼粼。","鼓枻逢渔父，怀沙吊楚臣。","长缨行欲濯，凉雨未沾尘。"]},{"t":"藤江舟中怀周贵谔却寄","f":"五言律诗","c":["烟波凝望远，簿领入舟闲。","野泊同鸥宿，乡心逐水还。","开樽聊自劝，得句倩谁删？","时有寻君梦，柴门莫夜关。"]},{"t":"冬日烟雨冥濛同谢在杭方伯陪贾侍御游全州湘山寺","f":"五言律诗","c":["金界踏苔钱，跻攀石磴悬。","江流通楚粤，梵宇接人天。","花落双林雨，钟敲万壑烟。","谁能悟真果，不堕老狐禅。"]},{"t":"舟回再咏画山","f":"五言律诗","c":["笑领故人意，诸峰待客还。","一官贫酌水，两岸饱看山。","顾盼如招手，徘徊可破颜。","夜来清入梦，鸾鹤碧云间。"]},{"t":"题乌蛮滩二首 其一 下滩","f":"五言律诗","c":["石啮旋涡急，舟惊下濑忙。","危机缘斗捷，利涉是轻装。","猿送三声泪，波随九转肠。","纵然清见底，终不似沧浪。"]},{"t":"题乌蛮滩二首 其二 上滩","f":"五言律诗","c":["水心元不竞，奔逼欲何之。","浪挟毒龙斗，舟如退鹢迟。","中流殊险恶，傍岸自平夷。","百丈徐徐意，惟应拙宦知。"]},{"t":"重入朗宁署","f":"五言律诗","c":["署冷厌重游，新愁并旧愁。","看梅今待腊，把菊昔悲秋。","两篆官仍寄，三冬岁欲周。","谁家调晚笛，偏倚夕阳楼。"]},{"t":"五月六日夏至彭贞元祁仲鱼陈永平集镜园赏荔时凶岁艰食","f":"五言律诗","c":["节过泛蒲后，堂开曲港滨。","白鸥元狎客，丹荔似佳人。","夏盛一阴长，年荒三径贫。","宜乘晚潮至，击水贷波臣。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其一","f":"五言律诗","c":["久避城中地，新成浦外桥。","荒郊来好客，归鹤下层霄。","暑气随潮退，商风倩竹招。","翛然幽事足，顿觉世尘遥。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其二","f":"五言律诗","c":["息荫火云净，雄潭秋水清。","闲门惟待淮，求友尚闻莺。","茗碗青浮乳，莼丝紫和羹。","前堤共携手，偶伴野鸥行。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其三","f":"五言律诗","c":["莲社叶心期，谈禅辨辟支。","观空聊指月，照寂更窥池。","发论鱼潜听，忘言石已知。","悠悠对挥麈，云雾豁然披。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其四","f":"五言律诗","c":["句觅囊中锦，诗裁笔里花。","但将声应钵，莫以足添蛇。","一字推敲细，千秋事业赊。","词坛今屈指，南北几名家。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其五","f":"五言律诗","c":["于野同人处，寒塘一镜开。","舟移剡曲棹，书忆陇头梅。","已叹三秋别，那过七夕来。","醉眠宜藉草，莫损石阶苔。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其六","f":"五言律诗","c":["潮来没古岸，雨过涨新泉。","移席花为幄，侵鞋草似绵。","壶觞馀种秫，风月不论钱。","更有沧浪曲，渔歌起夕川。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其七","f":"五言律诗","c":["谁能鲸吸海，亦有酒如池。","乘兴还骑马，何妨倒接䍠。","科头看醉态，拍手任群儿。","言念昔人达，携壶荷锸随。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其八","f":"五言律诗","c":["共识禽鱼乐，微闻菡萏香。","池亭不受暑，水木自生凉。","溪暗海烟接，林深雨气藏。","数峰遥对酒，日暮转青苍。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其九","f":"五言律诗","c":["更领夕佳景，高台踏紫云。","双龙占剑气，百里验星文。","酌罢月初上，吟成夜正分。","醉乡堪避世，时俗日纷纷。"]},{"t":"甲子孟秋十九日西园公过访镜园步杜少陵游何将军山林十律韵投赠步元韵酬之同集者尹用平温尔惇时溪桥初成十首 其十","f":"五言律诗","c":["同声自求应，倡和有羊何。","斗酒勿云薄，百篇奚足多。","倾杯鱼渐醉，得句鸟先歌。","愿扫矶头石，时邀彩鹢过。"]},{"t":"四老吟和周贵谔四首 其一 老将","f":"五言律诗","c":["百战清胡塞，廿年归汉关。","乞身辞北阙，赐第傍南山。","铁券勋名远，金丹日月闲。","还闻奉朝请，剑履近龙颜。"]},{"t":"四老吟和周贵谔四首 其二 老僧","f":"五言律诗","c":["庞眉耳到颐，剃发雪霏霏。","面壁不知岁，栽松大几围。","谈空三世事，传法六朝衣。","振锡南天遍，西方只履归。"]},{"t":"四老吟和周贵谔四首 其三 老妓","f":"五言律诗","c":["荡子太无情，徒劳巧笑迎。","容颜异今昔，门馆有虚盈。","云雨迷前梦，琵琶理旧声。","独怜卖赋客，还慕校书名。"]},{"t":"四老吟和周贵谔四首 其四 老农","f":"五言律诗","c":["作苦半生忙，劳劳鬓尽霜。","倦勤百亩力，剩得几年粮。","晚景桑榆末，闲身酒瓮旁。","代耕孙辈事，策杖饭牛羊。"]},{"t":"香淡斋对梅读何凝生寄怀诗赋酬","f":"五言律诗","c":["试索寒梅笑，闲窗独立时。","花如平叔粉，人忆水曹诗。","影动疑君到，书来慰梦思。","赠章何以报，聊折陇头枝。"]},{"t":"题大笑出门卷送李烟客三首 其一","f":"五言律诗","c":["我已卧游倦，君今始出门。","遨游称上客，顾盼尽中原。","然诺千金重，防身一剑存。","阳关不下泪，任听峡边猿。"]},{"t":"题大笑出门卷送李烟客三首 其二","f":"五言律诗","c":["俱是低眉者，谁为大笑人。","才名同入洛，傲骨耻干秦。","川陆征途远，湖山引兴新。","片言堪赠璧，行矣岂长贫。"]},{"t":"题大笑出门卷送李烟客三首 其三","f":"五言律诗","c":["四方男子事，儿女强牵衣。","名岳行应遍，雄心去若飞。","泛交投剌易，高调和人稀。","揽胜兼怀古，奚囊满载归。"]},{"t":"夏日罗翊文携歌者镜园泛舟","f":"五言律诗","c":["银塘摇锦浪，泛泛木兰堂。","酾酒鱼皆醉，听歌鸟亦狂。","荔浓迎巧笑，莲艳妒新妆。","夏日长如岁，沿洄乐未央。"]},{"t":"泛舟次日翊文复携四妓小演湛碧蓬时暑甚不雨来献负约不至末句戏嘲之二首 其一","f":"五言律诗","c":["可怜花解语，结伴得重陪。","缓唱回风曲，徐传避暑杯。","火云笼竹径，香汗湿桃腮。","借问阳台女，曾携楚雨来？"]},{"t":"泛舟次日翊文复携四妓小演湛碧蓬时暑甚不雨来献负约不至末句戏嘲之二首 其二","f":"五言律诗","c":["三竿睡未足，四美又逢迎。","风曳冰轮薄，歌□碧浪轻。","登场试小演，掩袖转多情。","避席者谁子？","虚传惊座名。"]},{"t":"夏至日翊文携两小娃过镜园赏荔酌在藻轩得十四盐","f":"五言律诗","c":["荔林红若焰，莫助火云炎。","岁觉一阴长，人逢二妙兼。","腰纤摇弱柳，歌细逗疏帘。","何物能消暑，盘中绛雪甜。"]},{"t":"纪异诗","f":"五言律诗","c":["沉醉欲无醒，悲歌只自听。","弥天开火宅，半夜斗妖星。","梗稻空南亩，烽烟满北庭。","群仙方濯足，且莫竭沧溟。"]},{"t":"酬二尹瞿尔锡父母过访镜园留题","f":"五言律诗","c":["散衙生野兴，飞盖出芳郊。","偶载词人笔，留题逋客巢。","水云溪畔舫，鸡黍竹间庖。","不厌闲门冷，知君爱淡交。"]},{"t":"集海珠寺","f":"七言律诗","c":["万道金光涌蕊宫，诸天色界坐来空。","闲从赤水嬉游里，拾得玄珠罔象中。","八月灵槎天路近，三山仙峤海门通。","吹笙不待骑羊子，此夜泠泠已御风。"]},{"t":"罗浮二首 其一","f":"七言律诗","c":["万里罡风吹鹖冠，扶桑碣石倚筇看。","乾坤一指浮空界，日月双珠在晓盘。","雨过黄龙初返洞，烟销玉女静临坛。","寻真丹灶行应得，未信刀圭不羽翰。"]},{"t":"罗浮二首 其二","f":"七言律诗","c":["朱明岩壑洞天遥，楼结青霞傍斗杓。","呼吸可能通帝座，啸歌犹听和鸾箫。","上清缥缈无今古，下界苍茫自暮朝。","不用登高誇作赋，游仙须奏白云谣。"]},{"t":"杨妃春睡图","f":"七言律诗","c":["脉脉芳心倚洞房，娇姿无力罢霓裳。","枕欹寒玉秋波迥，钗堕明瑶春恨长。","化蝶香魂迷上苑，行云仙佩绕高唐。","落红万点愁如许，谁送东风醉海棠？"]},{"t":"泛海二首 其一","f":"七言律诗","c":["谢傅轻舟兴渺茫，图南人挟大鹏翔。","六鳌自涌三山动，四渎终输百谷王。","且慢回帆归小虎，直将散发到扶桑。","鸣榔一笑人间事，驱石何因解作梁。"]},{"t":"泛海二首 其二","f":"七言律诗","c":["落魄高阳一酒徒，几年清梦寄江湖。","观涛秋壮枚乘笔，击楫风传海若呼。","遥礼东皇基北斗，更窥鲛室采骊珠。","蓬莱山下国清浅，问讯麻姑近到无。"]},{"t":"白云山寺","f":"七言律诗","c":["白云高锁上方幽，有客乘秋赋胜游。","石涧菖蒲人不识，安期黄鹤自深愁。","台隍远近分夷夏，宫殿依稀逼女牛。","东望罗浮顾沧海，粤王灵气未全收。"]},{"t":"结茅石湖山中","f":"七言律诗","c":["岂为逃名遂陆沉，闲情原不借云林。","畏人渐觉蓬蒿长，舒啸时闻鸾凤音。","古洞夜寒占剑气，空山春静适琴心。","齐盟此道还吾辈，和得新诗细细吟。"]},{"t":"小金山东坡祠","f":"七言律诗","c":["烟笼蜃气晓霏微，竹色波光碧四围。","冕服三朝留直骨，文章千载握灵玑。","箫声月下成今古，鹤梦人间有是非。","前世德云谁更问，怀仙孤屿憺忘归。"]},{"t":"登新安城楼时有边报","f":"七言律诗","c":["醉倚层楼发浩歌，忧时孤愤意如何？","奔涛动地鲸鲵斗，毒雾笼城瘴疠多。","望支朔方多锁钥，愁多炎塞有干戈。","书生谈剑真迂拙，横海何年起伏波？"]},{"t":"五层楼秋望","f":"七言律诗","c":["岭外天空人泬㵳，层楼登眺倚璇霄。","关河又报风霜急，城郭空嗟世代遥。","谁把长绳牵落日？","欲将强弩射回潮。","秋怀直寄蓬山远，玄鹤东归未易招。"]},{"t":"赠二陈兄弟二首 其一","f":"七言律诗","c":["风雅谁云此道难，齐盟天地尔登坛。","百年共梦文通笔，千里同弹贡禹冠。","望去青云推骏逸，飞来白雪动秋寒。","先朝北斗声华在，人拟玄成旧业看。"]},{"t":"赠二陈兄弟二首 其二","f":"七言律诗","c":["人入芝兰味自芬，翱翔偏得凤毛群。","风流已羡淮王妙，江左犹传小陆文。","玉树双标依丽日，金茎并秀擢丛云。","酒酣共倚青萍看，星聚遥占百粤分。"]},{"t":"吊崖","f":"七言律诗","c":["弹剑崖门赋大招，伤心指点问前朝。","胶舟云暗昭王魄，鸱革风驱伍子潮。","半夜星辰归海岛，千年肝胆照烟霄。","可怜秦玺龙宫得，长使鲛人泪满绡。"]}]};